-- ####################################################################
-- ## docs/directory_privacy.sql
-- ####################################################################
-- Reachability choices on the public directory.
-- ============================================================================
-- Run ONCE in the Supabase SQL editor.
--
-- WHY. The app offers two doors to a person: their phone number (contact
-- sync matches hashed numbers) and their profile (username search). These
-- columns let each account choose which doors are open. Both default open —
-- that is the behaviour everyone already has.
--
-- The flags are honoured by the app's directory queries. Like the rest of
-- this project's client-side rules, a modified client could ignore them;
-- what they protect against is being *listed*, not being contacted by
-- someone who already knows you.

alter table public.usernames
  add column if not exists find_by_username boolean not null default true;
alter table public.usernames
  add column if not exists find_by_phone boolean not null default true;


-- ####################################################################
-- ## docs/platform_moderation.sql
-- ####################################################################
-- App-wide roles, sanctions, and reports.
-- ============================================================================
-- Run ONCE in the Supabase SQL editor. Then grant yourself the owner role with
-- the statement at the very bottom (replace the number with your own).
--
-- WHAT THIS CAN DO. A sanction removes an account from the *shared*
-- infrastructure: the directory it is found through, claiming a username, push
-- notifications, payments. Postgres enforces the directory part through row
-- level security, so it holds against any client, modified or not.
--
-- WHAT IT CANNOT DO, BY DESIGN. It cannot read, remove, or moderate anybody's
-- messages. Message bodies are end-to-end encrypted before they leave the
-- device and the server only ever holds sealed envelopes it has no key for.
-- There is no server-side copy of a conversation to act on, and adding one
-- would break the promise the whole app rests on. Moderation here is about
-- access to the platform, not about content in private chats.

-- ---------------------------------------------------------------------------
-- Who holds power
-- ---------------------------------------------------------------------------
-- Service-role only: RLS is on and there is no client policy, so no app build
-- can read or write this table. A role the client could grant itself would be
-- worth nothing, so roles are granted here, by SQL, by whoever owns the
-- project.
create table if not exists public.platform_roles (
  phone      text primary key,              -- E.164 digits
  role       text not null check (role in ('owner', 'admin', 'moderator')),
  granted_by text not null default '',
  created_at timestamptz not null default now()
);
alter table public.platform_roles enable row level security;

-- ---------------------------------------------------------------------------
-- What has been done to an account
-- ---------------------------------------------------------------------------
-- One row per sanctioned account. Written only by the moderation-act Edge
-- Function (service role), which checks the caller's role first. `until` null
-- means permanent, which only a ban is.
create table if not exists public.account_sanctions (
  phone       text primary key,             -- E.164 digits
  kind        text not null check (kind in ('timeout', 'suspend', 'ban')),
  reason      text not null default '' check (char_length(reason) <= 500),
  until       timestamptz,
  actor_phone text not null default '',
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
alter table public.account_sanctions enable row level security;

-- Read-only to the app so a sanctioned device can be told why it is locked
-- out (and so every device agrees who is hidden). Nothing here is private:
-- it is a list of accounts that may not use the app.
drop policy if exists account_sanctions_read on public.account_sanctions;
create policy account_sanctions_read on public.account_sanctions
  for select to anon, authenticated using (true);
-- No insert/update/delete policy: only the service role changes a sanction.

create index if not exists account_sanctions_until_idx
  on public.account_sanctions (until);

-- Every sanction and lift, kept even after the sanction goes away. Moderation
-- without a record of who did what is just power.
create table if not exists public.moderation_log (
  id           bigint generated always as identity primary key,
  created_at   timestamptz not null default now(),
  actor_phone  text not null default '',
  actor_role   text not null default '',
  target_phone text not null default '',
  action       text not null default '',
  reason       text not null default '',
  until        timestamptz
);
alter table public.moderation_log enable row level security;

-- ---------------------------------------------------------------------------
-- Reports from people using the app
-- ---------------------------------------------------------------------------
-- "Report" used to be honest about going nowhere: it hid a listing locally and
-- said so, because there was no central moderator. Now there is one, and this
-- is where a report lands. A report carries what was reported and why — never
-- message content, which the reporter's device holds and the server cannot
-- read anyway.
create table if not exists public.moderation_reports (
  id             bigint generated always as identity primary key,
  created_at     timestamptz not null default now(),
  target_phone   text not null default '',
  target_handle  text not null default '',
  reporter_phone text not null default '',
  reason         text not null default '',
  detail         text not null default '' check (char_length(detail) <= 1000),
  context        text not null default '',   -- 'listing', 'post', 'chat', …
  handled        boolean not null default false
);
alter table public.moderation_reports enable row level security;

-- Anyone with the app may file one, and only about themselves as reporter.
-- Reports are not readable by clients — one person's report is nobody else's
-- business; moderators read them through the Edge Function.
drop policy if exists moderation_reports_insert on public.moderation_reports;
create policy moderation_reports_insert on public.moderation_reports
  for insert to anon, authenticated with check (true);

create index if not exists moderation_reports_open_idx
  on public.moderation_reports (handled, created_at desc);

-- ---------------------------------------------------------------------------
-- THE ENFORCEMENT: banned and suspended accounts leave the directory
-- ---------------------------------------------------------------------------
-- This is the part that is real regardless of what any app build does, because
-- Postgres applies it to every query. A hidden account cannot be found by
-- username search or by contact sync, and cannot claim or change a username.
--
-- A time-out is deliberately NOT hidden: it silences, it does not disappear
-- someone mid-conversation.
create or replace function public.is_locked_out(p text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.account_sanctions s
     where s.phone = p
       and s.kind in ('ban', 'suspend')
       and (s.until is null or s.until > now())
  );
$$;

-- Reading the directory: locked-out rows are invisible. Your own row stays
-- visible to you, so a suspended account can still see its own profile and be
-- told what happened instead of appearing to have been deleted.
drop policy if exists usernames_read on public.usernames;
create policy usernames_read on public.usernames
  for select to authenticated
  using (
    phone = (auth.jwt() ->> 'phone')
    or not public.is_locked_out(phone)
  );

-- Claiming or changing a username: locked out means locked out.
drop policy if exists usernames_insert_own on public.usernames;
create policy usernames_insert_own on public.usernames
  for insert to authenticated
  with check (
    phone = (auth.jwt() ->> 'phone')
    and not public.is_locked_out(phone)
  );

drop policy if exists usernames_update_own on public.usernames;
create policy usernames_update_own on public.usernames
  for update to authenticated
  using (phone = (auth.jwt() ->> 'phone'))
  with check (
    phone = (auth.jwt() ->> 'phone')
    and not public.is_locked_out(phone)
  );

-- Push tokens too: a locked-out account stops receiving notifications at the
-- source rather than being quietly delivered to.
drop policy if exists push_tokens_upsert_own on public.push_tokens;
create policy push_tokens_upsert_own on public.push_tokens
  for insert to authenticated
  with check (
    phone = (auth.jwt() ->> 'phone')
    and not public.is_locked_out(phone)
  );

-- ---------------------------------------------------------------------------
-- Housekeeping
-- ---------------------------------------------------------------------------
-- Lapsed sanctions stop applying the moment their clock runs out (the checks
-- above are all time-aware), so sweeping is tidiness rather than enforcement.
-- Call it from a scheduled job if you want the table to stay small.
create or replace function public.sweep_expired_sanctions()
returns integer
language plpgsql
as $$
declare removed integer;
begin
  delete from public.account_sanctions
   where until is not null and until <= now();
  get diagnostics removed = row_count;
  return removed;
end;
$$;

-- ---------------------------------------------------------------------------
-- GRANT YOURSELF THE OWNER ROLE — edit the number, then run this line.
-- ---------------------------------------------------------------------------
-- insert into public.platform_roles (phone, role, granted_by)
-- values ('15551234567', 'owner', 'bootstrap')
-- on conflict (phone) do update set role = 'owner';


-- ####################################################################
-- ## docs/audit_log_immutable.sql
-- ####################################################################
-- ---------------------------------------------------------------------------
-- The moderation audit trail becomes APPEND-ONLY, and tamper-EVIDENT
-- ---------------------------------------------------------------------------
-- Run after docs/platform_moderation.sql, which creates `moderation_log`.
-- Safe to run twice.
--
-- `moderation_log` has recorded every sanction, takedown and role change since
-- the console existed, and RLS with no policies at all already kept every
-- client out of it. What it never had was any defence against the one party
-- that can actually reach it: whoever holds the service-role key. A log the
-- operator can quietly rewrite is a log that says whatever the operator needs
-- it to have said, and that is the only threat model an audit trail exists for
-- — nobody keeps one to defend against a stranger who cannot see the table.
--
-- Two separate things, and the difference matters:
--
--   * APPEND-ONLY is prevention. A BEFORE UPDATE OR DELETE trigger raises, and
--     a trigger binds every role — the table owner and the service role
--     included, unlike a GRANT, which the owner is exempt from, or RLS, which
--     BYPASSRLS skips. This is why it is a trigger and not a revoke.
--
--   * The HASH CHAIN is detection, and it is what makes the word "immutable"
--     checkable instead of merely asserted. Each row carries the hash of the
--     one before it, so removing or editing any row breaks every hash after it
--     and `moderation_log_verify()` names the first entry that stopped adding
--     up. Prevention alone would be a promise; this is the evidence.
--
-- Honest about the ceiling, rather than letting the word "immutable" carry
-- more than it earns:
--   * A superuser can `alter table … disable trigger` or drop it outright.
--     That cannot be prevented from inside the database by anything short of
--     shipping the rows off it. What it is instead is a DELIBERATE, VISIBLE
--     act that leaves the chain broken behind it — which is the whole point
--     of pairing prevention with detection.
--   * It covers MODERATION ACTIONS. It is not an access log and not a data
--     log: it does not record who read a report or who opened the console.
--   * Detection needs somebody to look. The console's History tab runs the
--     check when it loads, so the answer is in front of the person who would
--     care rather than waiting for a query nobody runs.

-- ---------------------------------------------------------------------------
-- No client reaches this table, spelled out rather than left to RLS
-- ---------------------------------------------------------------------------
-- The table has RLS on and no policies, so a client already selects nothing.
-- The revoke is belt as well as braces, and this codebase has been burned
-- twice by the reason: Supabase grants table-wide privileges on every NEW
-- table in `public` to `anon` and `authenticated` by default (see
-- docs/community_structure.sql, where four tables quietly carried full CRUD
-- for anon, and docs/directory_phone_privacy.sql, where `revoke … from public`
-- did not revoke `anon`). A raw grant sitting unused is a hole waiting for the
-- day somebody adds a policy. Name the roles.
revoke all on table public.moderation_log from anon, authenticated;

-- ---------------------------------------------------------------------------
-- The chain columns
-- ---------------------------------------------------------------------------
-- Nullable, and filled by the trigger — never by the writer. `moderation-act`
-- and `roles-set` insert without naming them and must keep working unchanged;
-- more to the point, a hash the INSERTER supplies is a hash the inserter can
-- forge, which would make the chain decorative.
alter table public.moderation_log
  add column if not exists prev_hash text,
  add column if not exists row_hash  text;

-- The payload a row's hash is taken over: every field that carries meaning,
-- plus the link to the row before it. `id` and `created_at` are in it so a row
-- cannot be moved or re-timed without breaking, and `prev_hash` is what turns
-- a list of independent hashes into a chain.
--
-- IMMUTABLE and taking only the values (not the row type) so the verify pass
-- and the insert trigger cannot drift into hashing two different things —
-- there is one definition of what a row's hash is.
create or replace function public.moderation_log_hash(
  p_prev text, p_id bigint, p_created timestamptz, p_actor_phone text,
  p_actor_role text, p_target_phone text, p_action text, p_reason text,
  p_until timestamptz)
returns text language sql immutable as $$
  select encode(
    sha256(convert_to(
      coalesce(p_prev, '') || '|' ||
      p_id::text || '|' ||
      -- A fixed offset, so the same instant hashes the same regardless of
      -- what TimeZone the session that reads it happens to be set to.
      to_char(p_created at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.USOF') || '|' ||
      coalesce(p_actor_phone, '')  || '|' ||
      coalesce(p_actor_role, '')   || '|' ||
      coalesce(p_target_phone, '') || '|' ||
      coalesce(p_action, '')       || '|' ||
      coalesce(p_reason, '')       || '|' ||
      coalesce(to_char(p_until at time zone 'UTC',
                       'YYYY-MM-DD"T"HH24:MI:SS.USOF'), ''),
      'UTF8')),
    'hex');
$$;

-- ---------------------------------------------------------------------------
-- Append: link the new row to the last one
-- ---------------------------------------------------------------------------
-- The advisory lock serialises appends. Two moderators acting in the same
-- instant would otherwise both read the same tail and both claim it as their
-- predecessor, forking the chain — which reads exactly like tampering. It is
-- held to the end of the transaction, so a second appender waits for the first
-- to commit and then sees it; a rollback burns an identity value and leaves no
-- row, which the chain does not care about since it walks committed rows.
-- Moderation is a handful of actions a day, so the lock costs nothing.
create or replace function public.moderation_log_append()
returns trigger language plpgsql as $$
declare
  last_hash text;
begin
  perform pg_advisory_xact_lock(hashtext('moderation_log_chain'));
  select l.row_hash into last_hash
    from public.moderation_log l
    order by l.id desc
    limit 1;

  new.prev_hash := last_hash;
  new.row_hash := public.moderation_log_hash(
    last_hash, new.id, new.created_at, new.actor_phone, new.actor_role,
    new.target_phone, new.action, new.reason, new.until);
  return new;
end $$;

drop trigger if exists moderation_log_append on public.moderation_log;
create trigger moderation_log_append
  before insert on public.moderation_log
  for each row execute function public.moderation_log_append();

-- ---------------------------------------------------------------------------
-- Append-only: nothing is ever edited or removed
-- ---------------------------------------------------------------------------
-- Deliberately one trigger for both verbs and one message. There is no
-- legitimate UPDATE on this table either — a correction is a new entry saying
-- what was corrected, which is what an audit trail IS.
create or replace function public.moderation_log_immutable()
returns trigger language plpgsql as $$
begin
  raise exception
    'moderation_log is append-only: entries cannot be % (%)',
    lower(tg_op), 'audit trail';
end $$;

drop trigger if exists moderation_log_no_update on public.moderation_log;
create trigger moderation_log_no_update
  before update on public.moderation_log
  for each row execute function public.moderation_log_immutable();

drop trigger if exists moderation_log_no_delete on public.moderation_log;
create trigger moderation_log_no_delete
  before delete on public.moderation_log
  for each row execute function public.moderation_log_immutable();

-- ---------------------------------------------------------------------------
-- Backfill, for a project whose log predates the chain
-- ---------------------------------------------------------------------------
-- Rows written before this file ran have no hashes, so they get them now, in
-- id order. Said plainly because it is a real limit and not a small one:
-- hashing an existing row proves nothing about whether it was already
-- altered — the chain can only vouch for what happens AFTER it is laid down.
-- What the backfill buys is that the old entries cannot be quietly changed
-- from here on, and that the chain is continuous rather than starting mid-log.
--
-- The no-update trigger is disabled for the backfill: this is the one write to
-- this table that is legitimate, it happens exactly once, inside this
-- migration, and only for rows that have no hash yet.
do $$
declare
  r record;
  last_hash text;
  filled int := 0;
begin
  if not exists (select 1 from public.moderation_log where row_hash is null) then
    return;
  end if;

  alter table public.moderation_log disable trigger moderation_log_no_update;

  select l.row_hash into last_hash
    from public.moderation_log l
    where l.row_hash is not null
    order by l.id desc
    limit 1;

  for r in
    select * from public.moderation_log where row_hash is null order by id
  loop
    update public.moderation_log
       set prev_hash = last_hash,
           row_hash = public.moderation_log_hash(
             last_hash, r.id, r.created_at, r.actor_phone, r.actor_role,
             r.target_phone, r.action, r.reason, r.until)
     where id = r.id;
    last_hash := public.moderation_log_hash(
      last_hash, r.id, r.created_at, r.actor_phone, r.actor_role,
      r.target_phone, r.action, r.reason, r.until);
    filled := filled + 1;
  end loop;

  alter table public.moderation_log enable trigger moderation_log_no_update;
  raise notice 'moderation_log: hashed % existing entries', filled;
end $$;

-- ---------------------------------------------------------------------------
-- Verify: what makes "immutable" a claim somebody can check
-- ---------------------------------------------------------------------------
-- Walks the log in order and recomputes each hash. Returns one row:
--   ok       — the whole chain adds up
--   entries  — how many were checked, so "ok" over an emptied table is not
--              mistaken for a clean bill of health
--   broken_id / detail — the FIRST entry that does not, and why
--
-- The first break is what is reported rather than every mismatch, because one
-- altered row breaks every hash after it: a list of two hundred "failures"
-- from one edit would bury the one that matters.
--
-- Not SECURITY DEFINER, deliberately. It reads a table under RLS with no
-- policies, so an invoker function returns nothing to a client even if the
-- EXECUTE grant were somehow reachable — the caller has to be the service
-- role, which is what the Edge Function is. A definer here would build a door
-- into the log that only exists because the verifier needed one.
create or replace function public.moderation_log_verify()
returns table (ok boolean, entries bigint, broken_id bigint, detail text)
language plpgsql as $$
declare
  r record;
  last_hash text;
  want text;
  n bigint := 0;
begin
  for r in select * from public.moderation_log order by id loop
    n := n + 1;
    if r.row_hash is null then
      return query select false, n, r.id, 'entry has no hash'::text;
      return;
    end if;
    if coalesce(r.prev_hash, '') is distinct from coalesce(last_hash, '') then
      return query select false, n, r.id,
        'entry does not follow the one before it'::text;
      return;
    end if;
    want := public.moderation_log_hash(
      last_hash, r.id, r.created_at, r.actor_phone, r.actor_role,
      r.target_phone, r.action, r.reason, r.until);
    if want is distinct from r.row_hash then
      return query select false, n, r.id, 'entry has been altered'::text;
      return;
    end if;
    last_hash := r.row_hash;
  end loop;
  return query select true, n, null::bigint, ''::text;
end $$;

-- No client calls this — the console asks the Edge Function, which is the
-- service role.
--
-- PUBLIC is named as well as the two client roles, and that is not padding:
-- a new function is granted EXECUTE to PUBLIC by Postgres itself, and `anon`
-- holds it through that membership as well as through Supabase's own default
-- privileges. Revoking one and not the other leaves the function callable —
-- the mirror of the `find_people_by_hashes` bug in
-- docs/directory_phone_privacy.sql, where revoking PUBLIC left the explicit
-- anon grant standing. Both ends, or neither works.
revoke all on function public.moderation_log_verify()
  from public, anon, authenticated;
revoke all on function public.moderation_log_hash(
  text, bigint, timestamptz, text, text, text, text, text, timestamptz)
  from public, anon, authenticated;

-- …and give it back to the one caller there is. Guarded because a plain
-- Postgres (the throwaway one `tool/check_sql.sh` stands up, before its
-- harness runs) has no such role.
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function public.moderation_log_verify() to service_role;
    grant execute on function public.moderation_log_hash(
      text, bigint, timestamptz, text, text, text, text, text, timestamptz)
      to service_role;
  end if;
end $$;


-- ####################################################################
-- ## docs/identity_verification.sql
-- ####################################################################
-- Government-ID verification behind the blue check.
-- ============================================================================
-- Run this ONCE in the Supabase dashboard (SQL Editor -> New query -> Run).
--
-- WHY IT EXISTS. The badge used to be a free toggle — tap "Verify me" and you
-- were verified — which made it a decoration rather than a claim about who
-- someone is. It now requires a Stripe Identity document check with a selfie
-- match, and this table is the record of who passed.
--
-- WHAT IS *NOT* IN IT. No document images, no name, no date of birth, no
-- document number. Stripe holds all of that; this table stores a phone, the
-- session id, and a status string. The app never sees the document either —
-- the check happens in Stripe's hosted flow.

create table if not exists public.identity_verifications (
  phone      text primary key,          -- E.164 digits
  session_id text not null,
  -- Stripe's own vocabulary: requires_input | processing | verified | canceled
  status     text not null default 'processing',
  updated_at timestamptz not null default now()
);

-- Locked down completely: only the Edge Functions touch this, via the
-- service-role key, which bypasses RLS. Enabling RLS with no policies means a
-- client holding the publishable key can neither read nor write it — which is
-- the entire point, since this table is what says whose identity was checked.
alter table public.identity_verifications enable row level security;

drop policy if exists identity_select on public.identity_verifications;
drop policy if exists identity_insert on public.identity_verifications;
drop policy if exists identity_update on public.identity_verifications;

-- Sanity check: should return zero rows for the anon role.
-- select * from public.identity_verifications;


-- ####################################################################
-- ## docs/identity_name_match.sql
-- ####################################################################
-- The verified legal name, for card-holder matching.
-- ============================================================================
-- Run this AFTER docs/identity_verification.sql.
--
-- WHY THIS COLUMN EXISTS. Sending money requires that the card belongs to the
-- person sending it. The only trustworthy name to compare against is the one
-- Stripe read off a government ID, so it has to be stored to be compared.
--
-- This is a deliberate exception to keeping server-side data minimal, and it
-- is the narrowest one that makes the rule work: a name, nothing else. No
-- document images, no number, no date of birth, no address — those stay with
-- Stripe and are never requested by this project.

alter table public.identity_verifications
  add column if not exists verified_name text;

-- RLS is already enabled with no policies by identity_verification.sql, so
-- this column is no more readable than the rest of the row: only the Edge
-- Functions, using the service-role key, can see it.


-- ####################################################################
-- ## docs/identity_directory_badge.sql
-- ####################################################################
-- The blue check on the public directory.
-- ============================================================================
-- Run ONCE in the Supabase SQL editor, then re-paste payments-webhook (which
-- sets the flag when Stripe's identity verdict arrives).
--
-- WHY. The badge already flows peer-to-peer: a verified user's own posts and
-- messages attest it. But directory search results and contact-sync matches
-- come from the `usernames` table, which knew nothing about verification —
-- so those lists could either show no badge, or trust whatever a client
-- claimed. This column is the server's own answer: set exclusively by the
-- identity webhook on Stripe's verdict, never writable by clients.

alter table public.usernames
  add column if not exists verified boolean not null default false;

-- Clients may read it (it's what a badge is for) but never write it: the
-- claim path (upsert from the app) must not be able to grant itself a badge.
-- The webhook writes with the service role, which bypasses RLS.
do $$
begin
  if exists (
    select 1 from pg_policies
    where schemaname = 'public' and tablename = 'usernames'
  ) then
    -- Existing per-project policies vary; the important property is that no
    -- anon/authenticated policy grants UPDATE on this column specifically.
    -- If your policies allow client updates to usernames rows, split the
    -- verified column out of them.
    null;
  end if;
end $$;

-- Backfill anyone already verified before the column existed.
update public.usernames u
   set verified = true
  from public.identity_verifications v
 where v.phone = u.phone
   and v.status = 'verified';


-- ####################################################################
-- ## docs/chargeback_bans.sql
-- ####################################################################
-- Accounts banned from sending money, and the disputes that banned them.
-- ============================================================================
-- Run this ONCE in the Supabase dashboard (SQL Editor -> New query -> Run).
--
-- POLICY. A chargeback on a peer-to-peer transfer is not a billing disagreement
-- with a merchant — the money reached another person, who has already been
-- paid. Taking it back through the card network makes the recipient carry the
-- loss. So filing one ends the sender's ability to send.
--
-- WHY IT ALSO PROTECTS THE PLATFORM. Stripe closes accounts whose dispute
-- ratio climbs too high. Every dispute counts against that ratio whether it is
-- won or lost, so the cheapest dispute is the one that never happens and the
-- second cheapest is the one that never happens again.
--
-- WHAT IS STORED. A phone, a reason, the dispute and charge ids, and a
-- timestamp. No card details ever reach this project.

create table if not exists public.payment_bans (
  phone        text primary key,          -- E.164 digits of the sender
  reason       text not null default 'chargeback',
  dispute_id   text,
  charge_id    text,
  amount_cents int,
  banned_at    timestamptz not null default now()
);

create index if not exists payment_bans_banned_at_idx
  on public.payment_bans (banned_at);

-- Only the Edge Functions touch this, via the service-role key, which
-- bypasses RLS. Enabling RLS with no policies means a client holding the
-- publishable key can neither read it nor — far more importantly — delete
-- its own ban.
alter table public.payment_bans enable row level security;

drop policy if exists payment_bans_select on public.payment_bans;
drop policy if exists payment_bans_insert on public.payment_bans;
drop policy if exists payment_bans_delete on public.payment_bans;

-- Lifting a ban is a deliberate act, done here:
--   delete from public.payment_bans where phone = '15551234567';


-- ####################################################################
-- ## docs/iap_subscriptions.sql
-- ####################################################################
-- Auto-renewable storage subscriptions.
-- ============================================================================
-- Run this ONCE in the Supabase dashboard (SQL Editor -> New query -> Run).
--
-- WHY IT EXISTS. Apple bills an auto-renewable subscription every month on its
-- own. Without somewhere to record what Apple says, the app can only know
-- about the first purchase: month two would charge the customer while their
-- storage quietly lapsed. This table is the entitlement of record, written by
-- `iap-validate` (first purchase / restore) and kept current by `iap-notify`
-- (App Store Server Notifications V2).
--
-- WHAT'S IN IT. Nothing Apple didn't already tell us, plus the phone that
-- links a subscription to an account — the same identifier `push_tokens` and
-- `payment_accounts` already use. No payment details ever land here; Apple
-- handles the money and never shares a card with us.

create table if not exists public.subscriptions (
  -- Stable for the life of a subscription, and the only identifier Apple's
  -- renewal notifications carry.
  original_transaction_id text primary key,
  phone       text        not null,          -- E.164 digits
  product_id  text        not null,
  gb          int         not null default 0,
  expires_at  timestamptz,
  -- active | canceled (won't renew, still paid up) | grace (billing retry)
  -- | expired | refunded
  status      text        not null default 'active',
  environment text        not null default 'Production',
  updated_at  timestamptz not null default now()
);

create index if not exists subscriptions_phone_idx
  on public.subscriptions (phone);

-- Locked down completely: only the Edge Functions touch this, and they use the
-- service-role key, which bypasses RLS. Enabling RLS with no policies means a
-- client holding the publishable key can neither read nor write it — which
-- matters, because this table is what says who has paid.
alter table public.subscriptions enable row level security;

-- Explicitly drop any policy an earlier run may have created.
drop policy if exists subscriptions_select on public.subscriptions;
drop policy if exists subscriptions_insert on public.subscriptions;
drop policy if exists subscriptions_update on public.subscriptions;

-- Sanity check: should return zero rows for the anon role.
-- select * from public.subscriptions;


-- ####################################################################
-- ## docs/storage_usage_setup.sql
-- ####################################################################
-- Server-side storage accounting for Okay Messaging's paid chat backup.
-- ============================================================================
-- OPTIONAL. Run this AFTER docs/supabase_setup.sql, in the Supabase dashboard
-- (SQL Editor -> New query -> paste -> Run). It adds:
--
--   1. per-account storage accounting (bytes used), maintained automatically
--      by a trigger as chat/communal blobs are written and deleted;
--   2. monthly egress accounting with a fair-use ceiling (1x stored bytes);
--   3. a totals view so you can watch the whole project against your plan's
--      included storage (e.g. a $25 Supabase Pro project = 100 GB / 250 GB
--      egress) and know when to raise prices or archive cold data.
--
-- PRIVACY / TRUST NOTE. To attribute usage to a person we group a person's
-- blobs by an `account` tag the client sends. This tag is an HMAC of the phone
-- number under a FIXED app label (NOT the encryption key), so:
--   * it is stable across passphrase changes (usage survives a re-key), and
--   * it still reveals nothing about the number to anyone reading the table.
-- It DOES let the server see how many blobs and how many bytes one account
-- holds — a deliberate, minimal trade for being able to meter a paid plan.
-- Blob CONTENTS remain end-to-end-encrypted ciphertext the server can't read.
--
-- ENFORCEMENT NOTE. This project has no server-side auth (REQUIRE_OTP is off),
-- so RLS cannot bind a row to a verified caller: anyone with the publishable
-- key could in principle write any account's usage row. The accounting here is
-- therefore ACCURATE (the trigger derives bytes from the real blobs) but the
-- egress ceiling is ADVISORY until you add auth. Treat egress_over_limit() as
-- a signal to throttle in your Edge Function / gateway, not a hard gate.

-- ----------------------------------------------------------------------------
-- 1. Tag each blob with the account that owns it.
-- ----------------------------------------------------------------------------
-- Nullable, so existing rows and any client that hasn't been updated keep
-- working. Usage is only metered for rows that carry a tag.
alter table public.sync_blobs
  add column if not exists account text;

create index if not exists sync_blobs_account_idx
  on public.sync_blobs (account);

-- ----------------------------------------------------------------------------
-- 2. Per-account usage, kept current by a trigger.
-- ----------------------------------------------------------------------------
create table if not exists public.user_storage_usage (
  account      text primary key,
  used_bytes   bigint      not null default 0,
  tier         text        not null default 'free',
  egress_bytes bigint      not null default 0,
  period_start timestamptz not null default date_trunc('month', now()),
  updated_at   timestamptz not null default now()
);

alter table public.user_storage_usage enable row level security;

-- Readable/writable with the app key (see ENFORCEMENT NOTE above).
drop policy if exists usage_select on public.user_storage_usage;
create policy usage_select on public.user_storage_usage
  for select to anon, authenticated using (true);
drop policy if exists usage_upsert on public.user_storage_usage;
create policy usage_upsert on public.user_storage_usage
  for insert to anon, authenticated with check (true);
drop policy if exists usage_update on public.user_storage_usage;
create policy usage_update on public.user_storage_usage
  for update to anon, authenticated using (true);

-- Recompute an account's stored bytes from the real blobs — the source of
-- truth is always the sum of what's actually there, so the number can't drift.
create or replace function public.recompute_account_usage(acct text)
returns void language plpgsql as $$
begin
  if acct is null then
    return;
  end if;
  insert into public.user_storage_usage (account, used_bytes, updated_at)
  values (
    acct,
    coalesce((select sum(octet_length(data)) from public.sync_blobs
              where account = acct), 0),
    now()
  )
  on conflict (account) do update
    set used_bytes = excluded.used_bytes,
        updated_at = now();
end $$;

-- Fire on every write/delete of a tagged blob, for the affected account(s).
create or replace function public.sync_blobs_usage_trigger()
returns trigger language plpgsql as $$
begin
  if tg_op = 'DELETE' then
    perform public.recompute_account_usage(old.account);
    return old;
  end if;
  perform public.recompute_account_usage(new.account);
  -- An UPDATE that moved a blob between accounts must fix the old one too.
  if tg_op = 'UPDATE' and new.account is distinct from old.account then
    perform public.recompute_account_usage(old.account);
  end if;
  return new;
end $$;

drop trigger if exists sync_blobs_usage on public.sync_blobs;
create trigger sync_blobs_usage
  after insert or update or delete on public.sync_blobs
  for each row execute function public.sync_blobs_usage_trigger();

-- ----------------------------------------------------------------------------
-- 3. Monthly egress accounting with a fair-use ceiling.
-- ----------------------------------------------------------------------------
-- Call this from wherever you serve a restore/download, passing the bytes sent.
-- It rolls the counter over at the start of each month automatically.
create or replace function public.record_egress(acct text, bytes bigint)
returns void language plpgsql as $$
begin
  if acct is null or bytes is null or bytes <= 0 then
    return;
  end if;
  insert into public.user_storage_usage (account, egress_bytes, period_start, updated_at)
  values (acct, bytes, date_trunc('month', now()), now())
  on conflict (account) do update set
    egress_bytes = case
      when public.user_storage_usage.period_start < date_trunc('month', now())
        then bytes                                            -- new month, reset
      else public.user_storage_usage.egress_bytes + bytes end,
    period_start = greatest(public.user_storage_usage.period_start,
                            date_trunc('month', now())),
    updated_at = now();
end $$;

-- Fair use: downloads are limited to ~1x what you store, per month. Returns
-- true once an account is over — your gateway/Edge Function should then
-- throttle further downloads for the rest of the period.
create or replace function public.egress_over_limit(acct text)
returns boolean language sql stable as $$
  select coalesce(
    (select egress_bytes > 1 * greatest(used_bytes, 1)
       from public.user_storage_usage
      where account = acct
        and period_start >= date_trunc('month', now())),
    false);
$$;

-- ----------------------------------------------------------------------------
-- 4. Project totals — watch the whole thing against your plan's ceiling.
-- ----------------------------------------------------------------------------
-- e.g. a $25 Supabase Pro project includes 100 GB storage / 250 GB egress.
-- When total_used_bytes nears ~80 GB, raise prices or archive cold blobs.
--
-- security_invoker, and granted to NOBODY — see the note on
-- chat_backup_totals. Without it the view runs as its owner and hands every
-- account's usage to any client that asks; Supabase's advisor flags it
-- CRITICAL, and it is right to.
create or replace view public.storage_totals
with (security_invoker = on) as
  select
    count(*)                                    as accounts,
    count(*) filter (where tier = 'free')       as free_accounts,
    coalesce(sum(used_bytes), 0)                as total_used_bytes,
    coalesce(sum(egress_bytes), 0)              as total_egress_bytes_this_month
  from public.user_storage_usage;

revoke all on public.storage_totals from anon, authenticated;


-- ####################################################################
-- ## docs/public_feed.sql
-- ####################################################################
-- The public newsfeed: posts anyone can read, anyone signed in can write.
-- ============================================================================
-- Run ONCE in the Supabase SQL editor, AFTER docs/platform_moderation.sql —
-- this leans on public.is_locked_out() to keep banned accounts out of the feed.
--
-- WHAT IS DIFFERENT ABOUT THIS TABLE, SAID PLAINLY.
--
-- Everything else in this app is either on the device or sealed before it
-- leaves: private messages are end-to-end encrypted, server posts and listings
-- are encrypted with their server's key, and the mailbox holds only ciphertext.
-- This table is the first thing that holds **plaintext the server can read**,
-- and that is not a weakening of the promise — it is what "public" means. A
-- post whose audience is everyone cannot be encrypted to everyone; the key
-- would have to be public, which is the same as no key.
--
-- So the rule for this table is different and worth stating: **anything posted
-- here is public.** Not "private unless shared" — public, permanently, to
-- anybody with the app. Private messaging is untouched by this file.
--
-- What is still protected: the author's phone number. A public feed that
-- printed a phone number next to every post would make harvesting them
-- trivial, so clients are granted the other columns and never that one. Posts
-- are attributed by username, which is already public in the directory.
--
-- ORDER MATTERS HERE, in both directions:
--   * a SQL function's body is parsed when it is created, so the tables it
--     reads must exist first;
--   * a policy resolves the functions it calls when it is created, so those
--     must exist before the policies.
-- Hence: tables, then functions, then privileges and policies, then the view.

-- ---------------------------------------------------------------------------
-- 1. Tables
-- ---------------------------------------------------------------------------
create table if not exists public.public_posts (
  -- Client-generated, so a device recognises its own post coming back.
  id            text primary key,
  -- E.164 digits. Ownership only — never granted to a client role below.
  author_phone  text not null,
  author_username text not null default '',
  author_name   text not null default '',
  -- Self-attested, exactly like the badge on a chat message. The directory's
  -- server-written `verified` column is the stronger claim; this is for
  -- rendering without a join.
  author_verified boolean not null default false,
  -- Empty is allowed only when the post carries an image or is a plain
  -- repost; the check below spells that out.
  body          text not null default '' check (char_length(body) <= 500),
  -- A reply points at its parent; deleting a post takes its replies with it.
  reply_to      text references public.public_posts(id) on delete cascade,
  -- A repost points at what it repeats. With a body it reads as a quote post,
  -- without one as a plain repost. Deleting the original takes the reposts:
  -- a repost of nothing is not a post.
  repost_of     text references public.public_posts(id) on delete cascade,
  -- Path inside the public-media bucket, not a full URL, so moving the project
  -- doesn't strand every image ever posted.
  image_path    text not null default '',
  -- An address, not bytes. A GIF picked from the provider is already served
  -- from their CDN; copying it here would be paying to store and serve a
  -- file somebody else already serves for free.
  gif_url       text not null default '',
  -- Object name in the same public-media bucket. Unsealed, unlike a server
  -- feed's video, because a public post is world-readable by definition —
  -- there is nobody to keep it from.
  video_path    text not null default '',
  -- A poll: two to four answers, with the question in `body`. Null for an
  -- ordinary post. Who voted for what is in public_post_votes and is readable
  -- by nobody; only the tally comes back, from the counter below.
  poll_options  text[],
  poll_closes_at timestamptz,
  created_at    timestamptz not null default now(),
  -- Something has to be in a post. Text, a picture, a GIF, a video, or a
  -- repost — an entirely empty row is a rendering bug waiting to happen.
  constraint public_posts_not_empty check (
    char_length(body) > 0 or image_path <> '' or gif_url <> ''
    or video_path <> '' or repost_of is not null
  ),
  -- A post cannot be both a reply and a repost: the two mean different places
  -- in the tree and the UI would have to pick one anyway.
  constraint public_posts_reply_xor_repost check (
    reply_to is null or repost_of is null
  )
);

-- Migration for a project that already ran the first version of this file.
alter table public.public_posts
  add column if not exists repost_of text references public.public_posts(id) on delete cascade;
alter table public.public_posts
  add column if not exists image_path text not null default '';
alter table public.public_posts
  alter column body set default '';
do $$ begin
  -- The original CHECK required 1..500; an image-only post needs 0 allowed.
  alter table public.public_posts drop constraint if exists public_posts_body_check;
  alter table public.public_posts
    add constraint public_posts_body_check check (char_length(body) <= 500);
exception when duplicate_object then null; end $$;
do $$ begin
  alter table public.public_posts add constraint public_posts_not_empty check (
    char_length(body) > 0 or image_path <> '' or repost_of is not null);
exception when duplicate_object then null; end $$;
do $$ begin
  alter table public.public_posts add constraint public_posts_reply_xor_repost
    check (reply_to is null or repost_of is null);
exception when duplicate_object then null; end $$;
alter table public.public_posts
  add column if not exists poll_options text[];
alter table public.public_posts
  add column if not exists poll_closes_at timestamptz;

-- Media beyond a still photo.
--
-- gif_url is an ADDRESS, not bytes: a GIF picked from the provider already
-- lives on their CDN, and copying it into our bucket would be paying to
-- store and serve a file somebody else is already serving for free.
--
-- video_path is an object name in the same public-media bucket the images
-- use. Unsealed, unlike a server feed's video, because a public post is
-- world-readable by definition — there is nobody to keep it from, and a seal
-- whose key everybody holds is decoration.
alter table public.public_posts
  add column if not exists gif_url text not null default '';
alter table public.public_posts
  add column if not exists video_path text not null default '';
do $$ begin
  -- A post carrying only a GIF or only a video is a post. The original
  -- constraint predates both and would reject them as empty.
  alter table public.public_posts drop constraint if exists public_posts_not_empty;
  alter table public.public_posts add constraint public_posts_not_empty check (
    char_length(body) > 0 or image_path <> '' or gif_url <> ''
    or video_path <> '' or repost_of is not null);
exception when duplicate_object then null; end $$;

-- How many times a post was opened (2026-08-04). A COUNTER, not tracking:
-- no viewer identity is stored anywhere — there is no views table with a
-- phone in it, just a number on the post. Clients bump it through
-- public_post_viewed below (once per post per app run, by their own
-- discipline) and can never write it directly. Approximate by nature and
-- worth exactly what an X view count is worth.
alter table public.public_posts
  add column if not exists view_count bigint not null default 0;

create table if not exists public.public_post_likes (
  post_id     text not null references public.public_posts(id) on delete cascade,
  liker_phone text not null,
  created_at  timestamptz not null default now(),
  primary key (post_id, liker_phone)
);

-- Who has viewed a post (2026-08-07). Unlike the old anonymous view_count,
-- this holds one row per (post, viewer), so the same reader re-opening a post
-- can never inflate its count, and the author can be shown WHO looked. The
-- primary key IS the dedupe. viewer_phone is never granted to a client (below);
-- the count comes off the denormalised public_posts.view_count, kept in step by
-- public_post_viewed, and the author's "viewed by" list comes from the
-- public_post_viewers window — a client can never read this table directly.
create table if not exists public.public_post_views (
  post_id      text not null references public.public_posts(id) on delete cascade,
  viewer_phone text not null,
  created_at   timestamptz not null default now(),
  primary key (post_id, viewer_phone)
);
create index if not exists public_post_views_post_idx
  on public.public_post_views (post_id, created_at desc);

-- One vote per person per poll — that is the primary key, not a rule the app
-- is trusted to keep. There is no UPDATE or DELETE granted below either: a
-- vote you can take back is a vote somebody can be talked into taking back,
-- and the tally would move under people who had already read it.
create table if not exists public.public_post_votes (
  post_id     text not null references public.public_posts(id) on delete cascade,
  voter_phone text not null,
  -- Zero-based index into the post's poll_options. Bounded statically here
  -- and against the actual number of answers in the insert policy.
  choice      int not null check (choice >= 0 and choice < 4),
  created_at  timestamptz not null default now(),
  primary key (post_id, voter_phone)
);

create index if not exists public_posts_recent_idx
  on public.public_posts (created_at desc);
create index if not exists public_posts_replies_idx
  on public.public_posts (reply_to, created_at);
create index if not exists public_posts_author_idx
  on public.public_posts (author_phone);
create index if not exists public_posts_reposts_idx
  on public.public_posts (repost_of);
create index if not exists public_posts_username_idx
  on public.public_posts (author_username, created_at desc);

-- Sparks: real-money tips pinned to a post. The MONEY moves person-to-person
-- over Stripe (payments-create-intent resolves the author server-side, so the
-- sparker never learns a phone number); this table is only the public tally.
-- Not keyed like likes on purpose — the same person may spark twice.
create table if not exists public.public_post_sparks (
  id            bigint generated always as identity primary key,
  post_id       text not null references public.public_posts(id) on delete cascade,
  sparker_phone text not null,
  cents         int not null check (cents > 0 and cents <= 50000),
  created_at    timestamptz not null default now()
);
create index if not exists public_post_sparks_post_idx
  on public.public_post_sparks (post_id);

alter table public.public_posts enable row level security;
alter table public.public_post_likes enable row level security;
alter table public.public_post_views enable row level security;
alter table public.public_post_votes enable row level security;
alter table public.public_post_sparks enable row level security;

-- ---------------------------------------------------------------------------
-- 2. Functions (the tables above have to exist first)
-- ---------------------------------------------------------------------------

-- Whether an account may write right now. A time-out silences without hiding:
-- existing posts stay up, no new ones land. A ban or suspension does both, via
-- is_locked_out in the read policy further down.
create or replace function public.is_silenced(p text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.account_sanctions s
     where s.phone = p
       and (s.until is null or s.until > now())
  );
$$;

-- Counters that see past the like policy. Likes are readable only by the
-- person who made them, so a plain count() as the caller would return "1" for
-- your own like and 0 for everyone else's. These run as the owner precisely so
-- the totals are true without exposing who liked what.
create or replace function public.public_post_like_count(p text)
returns bigint
language sql
stable
security definer
set search_path = public
as $$
  select count(*) from public.public_post_likes where post_id = p;
$$;

create or replace function public.public_post_repost_count(p text)
returns bigint
language sql
stable
security definer
set search_path = public
as $$
  select count(*) from public.public_posts where repost_of = p;
$$;

create or replace function public.public_post_reply_count(p text)
returns bigint
language sql
stable
security definer
set search_path = public
as $$
  select count(*) from public.public_posts where reply_to = p;
$$;

-- The poll tally, one count per answer, in the answers' own order. Same reason
-- as the like counter: votes are readable only by the person who cast them, so
-- counting as the caller would report your own vote and nothing else. This
-- runs as the owner so the totals are true while who voted stays private.
create or replace function public.public_post_vote_counts(p text)
returns int[]
language sql
stable
security definer
set search_path = public
as $$
  select array(
    select (select count(*)::int
              from public.public_post_votes v
             where v.post_id = p and v.choice = i - 1)
      from generate_subscripts(
             coalesce((select poll_options from public.public_posts where id = p),
                      '{}'::text[]), 1) i
     order by i);
$$;

-- Spark tallies, same shape as the like counter: rows are readable only by
-- the person who sparked, so counting as the caller would report your own
-- sparks and nothing else. The totals are true while who sparked stays
-- private.
create or replace function public.public_post_spark_count(p text)
returns bigint
language sql
stable
security definer
set search_path = public
as $$
  select count(*) from public.public_post_sparks where post_id = p;
$$;

-- Whether [digitsv] wrote post [p]. SECURITY DEFINER because the spark
-- policy needs the answer and the caller is (rightly) not allowed to read
-- author_phone — a plain subquery in the policy dies on the column grant.
create or replace function public.is_post_author(p text, digitsv text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.public_posts
     where id = p and author_phone = digitsv);
$$;

create or replace function public.public_post_spark_cents(p text)
returns bigint
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(sum(cents), 0) from public.public_post_sparks where post_id = p;
$$;

-- Whether a set of answers is one a poll may have. A CHECK cannot hold a
-- subquery, so the per-answer rules live in an immutable function it can call.
create or replace function public.poll_options_ok(opts text[])
returns boolean
language sql
immutable
as $$
  select opts is null or (
    array_length(opts, 1) between 2 and 4
    and not exists (
      select 1 from unnest(opts) o
       where char_length(btrim(o)) = 0 or char_length(o) > 40));
$$;

-- A poll is a top-level post with a question, two to four answers, and a
-- closing time. Anything else called a poll is a rendering bug.
do $$ begin
  alter table public.public_posts add constraint public_posts_poll_shape check (
    poll_options is null or (
      public.poll_options_ok(poll_options)
      and reply_to is null
      and repost_of is null
      and char_length(body) > 0
      and poll_closes_at is not null));
exception when duplicate_object then null; end $$;

-- ---------------------------------------------------------------------------
-- 3. Column privileges
-- ---------------------------------------------------------------------------
-- THE PHONE COLUMNS, PROPERLY.
--
-- `revoke select (author_phone) ...` on its own does nothing here, and that is
-- worth spelling out because it looks like it should work: Supabase grants
-- these roles table-wide SELECT on every new table in public, and Postgres
-- cannot carve a column out of a table-wide grant. The revoke succeeds, changes
-- nothing, and leaves every poster's phone number readable by anyone with the
-- app.
--
-- So the table-wide grant goes first, and the readable columns are handed back
-- one by one. Anything asking for `*` is refused outright.
revoke select on table public.public_posts from anon, authenticated;
-- gif_url and video_path belong on this list, not merely in the table. A
-- column added without being granted here is a column the app cannot read —
-- the post comes back with its video silently missing and nothing says why.
grant select (id, author_username, author_name, author_verified, body,
              reply_to, repost_of, image_path, gif_url, video_path,
              poll_options, poll_closes_at, created_at, view_count)
  on public.public_posts to anon, authenticated;

revoke select on table public.public_post_likes from anon, authenticated;
grant select (post_id, created_at)
  on public.public_post_likes to anon, authenticated;

-- The views table is never client-readable in any column: who viewed a post is
-- the author's to see, and only through the public_post_viewers window below.
-- No insert/delete/update grant either — the only writer is the security-
-- definer public_post_viewed, which runs as the table owner past this.
revoke select on table public.public_post_views from anon, authenticated;
revoke insert, update, delete on public.public_post_views from anon, authenticated;

-- Your own vote comes back so the app can show which answer you picked.
-- voter_phone is never granted, so the row is only ever yours to read — the
-- policy below sees to that as well.
revoke select on table public.public_post_votes from anon, authenticated;
grant select (post_id, choice, created_at)
  on public.public_post_votes to authenticated;

-- Your own sparks come back so the app can show the amber bolt; who else
-- sparked is nobody's business — totals come from the counters.
revoke select on table public.public_post_sparks from anon, authenticated;
grant select (post_id, cents, created_at)
  on public.public_post_sparks to authenticated;

-- Writing is by whole row; the policies below decide whose row it may be.
grant insert, delete on public.public_posts to authenticated;
grant insert, delete on public.public_post_likes to authenticated;
-- Insert only. A vote is cast once and stands.
grant insert on public.public_post_votes to authenticated;
-- Insert only, likewise: a spark is money that moved — it does not un-move.
grant insert on public.public_post_sparks to authenticated;

-- No UPDATE for anyone. There is no update policy either, but relying on that
-- alone makes an edit fail *silently* — an UPDATE matching no policy affects
-- zero rows without raising, which reads like success. Taking the privilege
-- away makes the refusal explicit.
revoke update on public.public_posts from anon, authenticated;
revoke update on public.public_post_likes from anon, authenticated;
revoke update, delete on public.public_post_votes from anon, authenticated;
revoke update, delete on public.public_post_sparks from anon, authenticated;

-- ---------------------------------------------------------------------------
-- 4. Policies (the functions above have to exist first)
-- ---------------------------------------------------------------------------

-- Readable by anyone with the app — except posts by an account that is banned
-- or suspended, which leave the feed the moment the sanction lands.
drop policy if exists public_posts_read on public.public_posts;
create policy public_posts_read on public.public_posts
  for select to anon, authenticated
  using (not public.is_locked_out(author_phone));

-- You may only post as yourself, and only while you are allowed to post. Both
-- halves are enforced here, so a modified client gains nothing: the phone comes
-- from a JWT it cannot forge, and a sanctioned account is refused outright.
drop policy if exists public_posts_insert_own on public.public_posts;
create policy public_posts_insert_own on public.public_posts
  for insert to authenticated
  with check (
    author_phone = (auth.jwt() ->> 'phone')
    and not public.is_silenced(author_phone)
  );

-- Deleting your own post. No update policy at all: an edited public post with
-- no history is a way to bait people and then rewrite it.
drop policy if exists public_posts_delete_own on public.public_posts;
create policy public_posts_delete_own on public.public_posts
  for delete to authenticated
  using (author_phone = (auth.jwt() ->> 'phone'));

-- You can see which posts YOU liked, and nobody else's. Who liked what is
-- nobody's business; the totals come from the counters above.
drop policy if exists public_post_likes_read_own on public.public_post_likes;
create policy public_post_likes_read_own on public.public_post_likes
  for select to authenticated
  using (liker_phone = (auth.jwt() ->> 'phone'));

drop policy if exists public_post_likes_insert_own on public.public_post_likes;
create policy public_post_likes_insert_own on public.public_post_likes
  for insert to authenticated
  with check (
    liker_phone = (auth.jwt() ->> 'phone')
    and not public.is_silenced(liker_phone)
  );

drop policy if exists public_post_likes_delete_own on public.public_post_likes;
create policy public_post_likes_delete_own on public.public_post_likes
  for delete to authenticated
  using (liker_phone = (auth.jwt() ->> 'phone'));

-- Same shape as likes: you can see your own vote, nobody else's, and the
-- tally comes from the counter that runs as the owner.
drop policy if exists public_post_votes_read_own on public.public_post_votes;
create policy public_post_votes_read_own on public.public_post_votes
  for select to authenticated
  using (voter_phone = (auth.jwt() ->> 'phone'));

-- Everything that makes a vote a vote is checked here rather than in the app.
-- A modified client gains nothing: it cannot vote as somebody else, cannot
-- pick an answer the poll does not have, cannot vote on a post that is not a
-- poll, and cannot vote after it closes. Voting twice is stopped by the
-- primary key above.
drop policy if exists public_post_votes_insert_own on public.public_post_votes;
create policy public_post_votes_insert_own on public.public_post_votes
  for insert to authenticated
  with check (
    voter_phone = (auth.jwt() ->> 'phone')
    and not public.is_silenced(voter_phone)
    and exists (
      select 1 from public.public_posts p
       where p.id = post_id
         and p.poll_options is not null
         and choice < coalesce(array_length(p.poll_options, 1), 0)
         and p.poll_closes_at > now()));

-- Sparks: you may record only your own, only while allowed to interact, and
-- never on your own post — self-sparking is a fake tally with your own money.
drop policy if exists public_post_sparks_read_own on public.public_post_sparks;
create policy public_post_sparks_read_own on public.public_post_sparks
  for select to authenticated
  using (sparker_phone = (auth.jwt() ->> 'phone'));

drop policy if exists public_post_sparks_insert_own on public.public_post_sparks;
create policy public_post_sparks_insert_own on public.public_post_sparks
  for insert to authenticated
  with check (
    sparker_phone = (auth.jwt() ->> 'phone')
    and not public.is_silenced(sparker_phone)
    -- The FK guarantees the post exists; the definer function answers the
    -- one question the caller may not ask directly.
    and not public.is_post_author(post_id, sparker_phone));

-- ---------------------------------------------------------------------------
-- 5. What clients actually read
-- ---------------------------------------------------------------------------
-- A view with no phone column in it at all, so the ordinary path cannot leak
-- one even by accident. security_invoker keeps the caller's RLS in force, which
-- is what hides a banned author's posts.
--
-- DROPPED FIRST, and it has to be. `create or replace view` may only append
-- columns to the end of an existing view; anything else is read as renaming
-- the columns that moved, and Postgres refuses:
--
--   42P16: cannot change name of view column "created_at" to "repost_of"
--
-- Which is exactly what happened to this file, because repost_of and
-- image_path belong next to the other post columns rather than tacked on after
-- the counters. Dropping is safe: no app reads this view through a stored
-- object, and the grant is re-issued below.
drop view if exists public.public_feed;
create or replace view public.public_feed
with (security_invoker = on) as
select
  p.id,
  p.author_username,
  p.author_name,
  p.author_verified,
  p.body,
  p.reply_to,
  p.repost_of,
  p.image_path,
  p.gif_url,
  p.video_path,
  p.poll_options,
  p.poll_closes_at,
  p.created_at,
  p.view_count,
  public.public_post_like_count(p.id)   as like_count,
  public.public_post_reply_count(p.id)  as reply_count,
  public.public_post_repost_count(p.id) as repost_count,
  public.public_post_vote_counts(p.id)  as poll_votes,
  public.public_post_spark_count(p.id)  as spark_count,
  public.public_post_spark_cents(p.id)  as spark_cents
from public.public_posts p;

grant select on public.public_feed to anon, authenticated;

-- ---------------------------------------------------------------------------
-- 6. Images
-- ---------------------------------------------------------------------------
-- A public bucket, and public is the honest setting: these are attachments on
-- posts anyone can read, so sealing them the way listing videos are sealed
-- would accomplish nothing — the key would have to be as public as the post.
--
-- The object name is the post id, which is 8 random bytes, so a path is not
-- guessable from a username or a phone number.
insert into storage.buckets (id, name, public, file_size_limit)
values ('public-media', 'public-media', true, 4194304)
on conflict (id) do update
  set public = true,
      file_size_limit = 4194304;

-- Anyone may read (the bucket is public); only a signed-in account may add.
-- No update or delete for clients: an image swapped under a post that people
-- have already read is the same trick as editing the text.
drop policy if exists public_media_read on storage.objects;
create policy public_media_read on storage.objects
  for select to anon, authenticated
  using (bucket_id = 'public-media');

drop policy if exists public_media_insert on storage.objects;
create policy public_media_insert on storage.objects
  for insert to authenticated
  with check (bucket_id = 'public-media');

-- ---------------------------------------------------------------------------
-- Who liked a post (2026-08-04). The likes table stores the liker's PHONE
-- and its policy hides every row but your own — that stays exactly as it
-- is. This function is the one window: it joins to the directory and
-- answers USERNAMES only, so "who liked" is as public as a like on a
-- public post while a phone number still never leaves the table. Likers
-- with no directory row — or a hidden (deactivated) one — are simply not
-- listed, so the like count can honestly exceed the names shown.
-- (Reposts need nothing here: a repost is an ordinary public post whose
-- repost_of points at the original, readable like any other.)

-- Order-independent with docs/account_lifecycle.sql, which also adds this.
alter table public.usernames
  add column if not exists hidden boolean not null default false;

create or replace function public.public_post_likers(p text)
returns table(username text, name text)
language sql
stable
security definer
set search_path = public
as $$
  select u.username, coalesce(u.name, '')
    from public.public_post_likes l
    join public.usernames u on u.phone = l.liker_phone
   where l.post_id = p
     and not coalesce(u.hidden, false)
   order by l.created_at desc
   limit 100;
$$;

grant execute on function public.public_post_likers(text) to anon, authenticated;

-- Counts one view — ONCE per viewer, forever. The (post, viewer) primary key
-- on public_post_views is the dedupe: a reader re-opening a post inserts
-- nothing the second time, so view_count only moves on a genuinely new viewer.
-- An anonymous reader (numberless account on the anon key, no jwt phone) is not
-- counted and not listed — a view you can't attribute can't be deduped or shown
-- either. The table grants clients nothing, so this definer function is the
-- only writer.
create or replace function public.public_post_viewed(p text)
returns void
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  ph text := nullif(auth.jwt() ->> 'phone', '');
begin
  if ph is null then
    return;
  end if;
  insert into public.public_post_views (post_id, viewer_phone)
    values (p, ph)
    on conflict (post_id, viewer_phone) do nothing;
  if found then
    update public.public_posts set view_count = view_count + 1 where id = p;
  end if;
end;
$$;

grant execute on function public.public_post_viewed(text) to anon, authenticated;

-- Who viewed a post — the SAME directory-join window as public_post_likers,
-- newest first. Only ever reached by the post's author from the app (the UI
-- shows the "viewed by" list on your own posts), but the window itself carries
-- no phones and hides accounts that asked to be hidden, like every other.
create or replace function public.public_post_viewers(p text)
returns table(username text, name text)
language sql
stable
security definer
set search_path = public
as $$
  select u.username, coalesce(u.name, '')
    from public.public_post_views v
    join public.usernames u on u.phone = v.viewer_phone
   where v.post_id = p
     and not coalesce(u.hidden, false)
   order by v.created_at desc
   limit 100;
$$;

grant execute on function public.public_post_viewers(text) to anon, authenticated;

-- ---------------------------------------------------------------------------
-- 6. Follows — the one social-graph table (2026-08-05, the owner's call:
--    follower and following counts should be real for everybody).
--
-- Same privacy shape as likes: phones inside, usernames out. Both ends of
-- an edge are stored by PHONE — the follower's vouched for by the JWT, the
-- followed resolved from their handle at follow time INSIDE a definer
-- function, so a later username change never orphans the edge and the
-- handle→phone mapping never crosses the wire. There are NO direct grants
-- on the table at all: the functions below are the only doors, and none of
-- them ever returns a phone number.
-- ---------------------------------------------------------------------------

create table if not exists public.public_follows (
  follower_phone text not null,
  followed_phone text not null,
  created_at     timestamptz not null default now(),
  primary key (follower_phone, followed_phone)
);

alter table public.public_follows enable row level security;
revoke all on table public.public_follows from anon, authenticated;

-- Follow by handle. Idempotent; a self-follow or an unknown handle is a
-- silent no-op — the client treats the server graph as best-effort beside
-- its local list, so there is nothing useful to throw at it.
-- Both edges are keyed by the phone format the username directory stores
-- (E.164, with the leading '+'). The JWT's `phone` claim, though, arrives
-- WITHOUT the '+', so writing it raw made `follower_phone` a value that could
-- never join back to `usernames.phone` — the follower's own row — and the
-- FOLLOWING count silently stayed 0 for everyone. So resolve the caller to
-- their directory phone first (compare on digits only), and store THAT.
-- RETURNS BOOLEAN since 2026-08-19, and the reason is worth keeping. It was
-- `returns void`, and it gives up SILENTLY when it cannot resolve the caller
-- — PostgREST answers 204 and the client sees a clean write. That is worse
-- than an error, and it cost a real bug: an email-verified account's
-- directory row still named the address it signed up with, so `me` was null
-- on every call. The Follow button flipped, the server recorded nothing, and
-- the count went back to zero at the next sync with nothing anywhere
-- reporting a fault. It took a live probe to find, because there was nothing
-- to find in a log.
--
-- The client already keeps and retries edges the server did not take
-- (`FollowStore._pending`); that machinery was useless here for one reason
-- only — a silent no-op is not a failure, so nothing was ever kept. The
-- boolean is what connects the two.
--
-- FALSE means, precisely: "I could not work out who you are." That is the one
-- failure worth retrying, and it clears itself the moment the directory row
-- is right. Everything else is TRUE, including an unknown handle and a
-- self-follow, because those are DECISIONS rather than failures and retrying
-- them would be a loop that can never succeed.
--
-- DROPPED first because the return type changed and `create or replace`
-- cannot do that — without this, re-running this file over an older
-- deployment fails with "cannot change return type". Safe: a caller that
-- ignores the result is unaffected.
drop function if exists public.public_follow(text);
create or replace function public.public_follow(u text)
returns boolean
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  jwt_phone text := (auth.jwt() ->> 'phone');
  me   text;
  them text;
begin
  if jwt_phone is null or jwt_phone = '' then return false; end if;
  select phone into me from public.usernames
   where regexp_replace(phone, '\D', '', 'g')
       = regexp_replace(jwt_phone, '\D', '', 'g')
   limit 1;
  -- The bug above: a session, but no directory row at that address, so
  -- nothing can be attributed. Retryable — claiming the handle fixes it.
  if me is null then return false; end if;
  select phone into them from public.usernames
   where lower(username) = lower(u) limit 1;
  if them is null or them = me then return true; end if;
  insert into public.public_follows (follower_phone, followed_phone)
  values (me, them)
  on conflict do nothing;
  return true;
end;
$$;

-- Same change, same reasoning — see public_follow above.
drop function if exists public.public_unfollow(text);
create or replace function public.public_unfollow(u text)
returns boolean
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  jwt_phone text := (auth.jwt() ->> 'phone');
  me   text;
  them text;
begin
  if jwt_phone is null or jwt_phone = '' then return false; end if;
  select phone into me from public.usernames
   where regexp_replace(phone, '\D', '', 'g')
       = regexp_replace(jwt_phone, '\D', '', 'g')
   limit 1;
  if me is null then return false; end if;
  select phone into them from public.usernames
   where lower(username) = lower(u) limit 1;
  if them is null then return true; end if;
  delete from public.public_follows
   where follower_phone = me and followed_phone = them;
  -- True whether or not a row was there: the END STATE the caller asked for
  -- holds either way, and unfollowing somebody you never followed is not
  -- something to retry.
  return true;
end;
$$;

-- Both numbers in one round trip, for the profile header.
create or replace function public.public_follow_counts(u text)
returns table(followers bigint, following bigint)
language sql
stable
security definer
set search_path = public
as $$
  select
    (select count(*)
       from public.public_follows f
       join public.usernames t on t.phone = f.followed_phone
      where lower(t.username) = lower(u)),
    (select count(*)
       from public.public_follows f
       join public.usernames s on s.phone = f.follower_phone
      where lower(s.username) = lower(u));
$$;

-- Who follows them / who they follow — usernames only, hidden accounts
-- filtered, bounded like the likers window.
create or replace function public.public_followers(u text)
returns table(username text, name text)
language sql
stable
security definer
set search_path = public
as $$
  select s.username, coalesce(s.name, '')
    from public.public_follows f
    join public.usernames t on t.phone = f.followed_phone
    join public.usernames s on s.phone = f.follower_phone
   where lower(t.username) = lower(u)
     and not coalesce(s.hidden, false)
   order by f.created_at desc
   limit 100;
$$;

create or replace function public.public_following(u text)
returns table(username text, name text)
language sql
stable
security definer
set search_path = public
as $$
  select t.username, coalesce(t.name, '')
    from public.public_follows f
    join public.usernames s on s.phone = f.follower_phone
    join public.usernames t on t.phone = f.followed_phone
   where lower(s.username) = lower(u)
     and not coalesce(t.hidden, false)
   order by f.created_at desc
   limit 100;
$$;

-- A new function is EXECUTABLE BY EVERYONE until told otherwise, and the
-- drop+create above makes these new every time this file runs. Read live, the
-- ACL was `=X/postgres | postgres=… | authenticated=… | service_role=…` — that
-- leading empty grantee is PUBLIC, which `anon` inherits from, so
-- `revoke ... from anon` alone changed nothing (verified: it ran clean and
-- anon still held EXECUTE).
--
-- This is the MIRROR of the case find_people_by_hashes taught, where revoking
-- PUBLIC left an explicit anon grant standing. Both have now bitten this
-- project from opposite directions, so the rule is: revoke BOTH, and check the
-- ACL rather than the intent.
--
-- Nothing is lost by closing it — both read `auth.jwt() ->> 'phone'`, so an
-- anon caller only ever got `false`. This shuts a door that was already
-- answering no, rather than fixing a hole.
revoke execute on function public.public_follow(text) from public, anon;
revoke execute on function public.public_unfollow(text) from public, anon;
grant execute on function public.public_follow(text) to authenticated;
grant execute on function public.public_unfollow(text) to authenticated;
grant execute on function public.public_follow_counts(text) to anon, authenticated;
grant execute on function public.public_followers(text) to anon, authenticated;
grant execute on function public.public_following(text) to anon, authenticated;


-- ####################################################################
-- ## docs/creator_subscriptions.sql
-- ####################################################################
-- Creator subscriptions (2026-08-05): a creator may publish subscribers-only
-- posts to the public feed, and a reader pays a monthly pass to read them.
--
-- WHY ACCESS-CONTROL, NOT END-TO-END SEALING. The public feed is world-readable
-- and SERVER-MODERATED (every post's text is screened). A paid post is therefore
-- gated by ACCESS, not sealed: a sealed body could never be screened, and
-- unscreenable pay-walled content is exactly the abuse vector that has burned
-- other creator platforms. True sealing is reserved for paid SERVERS, whose feed
-- is already private by design. So the public row carries only a teaser; the
-- real text lives in `public_paid_bodies`, which NOTHING may select directly —
-- `public_paid_body()` is the one door, and it opens only for the author or an
-- account holding an active pass.
--
-- WHY THE CLIENT CANNOT GRANT ITSELF A PASS. The entitlement in
-- `creator_subscriptions` is written ONLY by the `creator-subscribe` Edge
-- Function, which verifies the App Store receipt first (the same trust model as
-- the storage subscription). There are no client-facing writes on that table.
--
-- Idempotent: safe to run more than once. Apply after docs/public_feed.sql
-- (it extends public_posts and the public_feed view, both defined there).

-- ---------------------------------------------------------------------------
-- 1. Post columns: whether it's a paid post, and the monthly price.
-- ---------------------------------------------------------------------------
-- sub_cents is denormalised onto the row so the locked card can show a price
-- to a stranger who holds no profile for the creator.
alter table public.public_posts
  add column if not exists paid boolean not null default false;
alter table public.public_posts
  add column if not exists sub_cents int not null default 0;

-- The feed view reads by COLUMN grant (author_phone is deliberately withheld),
-- so a new column the view returns has to be granted here too, or it reads back
-- null with nothing to say why.
grant select (paid, sub_cents) on public.public_posts to anon, authenticated;

-- ---------------------------------------------------------------------------
-- 2. The feed view, now carrying paid + sub_cents.
-- ---------------------------------------------------------------------------
-- The `body` it returns is already the public teaser for a paid post — the
-- composer writes only the teaser to public_posts.body and the real text to
-- public_paid_bodies below — so the private text never enters this view.
create or replace view public.public_feed
with (security_invoker = on) as
select
  p.id,
  p.author_username,
  p.author_name,
  p.author_verified,
  p.body,
  p.reply_to,
  p.repost_of,
  p.image_path,
  p.gif_url,
  p.video_path,
  p.poll_options,
  p.poll_closes_at,
  p.created_at,
  p.view_count,
  public.public_post_like_count(p.id)   as like_count,
  public.public_post_reply_count(p.id)  as reply_count,
  public.public_post_repost_count(p.id) as repost_count,
  public.public_post_vote_counts(p.id)  as poll_votes,
  public.public_post_spark_count(p.id)  as spark_count,
  public.public_post_spark_cents(p.id)  as spark_cents,
  p.paid,
  p.sub_cents
from public.public_posts p;

grant select on public.public_feed to anon, authenticated;

-- ---------------------------------------------------------------------------
-- 3. The paid bodies — the private text, readable by nobody directly.
-- ---------------------------------------------------------------------------
create table if not exists public.public_paid_bodies (
  post_id      text primary key
                 references public.public_posts(id) on delete cascade,
  author_phone text not null,
  body         text not null,
  created_at   timestamptz not null default now()
);

alter table public.public_paid_bodies enable row level security;

-- Take back the table-wide SELECT Supabase grants every new public table: the
-- whole point of this table is that its body is never world-readable. The
-- security-definer reader below bypasses this; a direct `select body` does not.
revoke select on table public.public_paid_bodies from anon, authenticated;
-- No update or delete for anyone — a paid body swapped under readers who
-- already paid is the same trick as editing a public post after the fact.
revoke update, delete on table public.public_paid_bodies from anon, authenticated;
grant insert on public.public_paid_bodies to authenticated;

-- A creator inserts only their OWN row, vouched by the JWT phone.
drop policy if exists paid_bodies_insert on public.public_paid_bodies;
create policy paid_bodies_insert on public.public_paid_bodies
  for insert to authenticated
  with check (author_phone = (auth.jwt() ->> 'phone'));

-- ---------------------------------------------------------------------------
-- 4. The passes. Both ends by phone (like follows); NO client grants at all —
--    the entitlement is written only by the receipt-verifying edge function
--    (service role, which bypasses RLS), and read only through the functions
--    below. last_txn_id dedupes a receipt so one purchase grants one month.
-- ---------------------------------------------------------------------------
create table if not exists public.creator_subscriptions (
  subscriber_phone text not null,
  creator_phone    text not null,
  expires_at       timestamptz not null,
  product_id       text not null default '',
  last_txn_id      text not null default '',
  updated_at       timestamptz not null default now(),
  primary key (subscriber_phone, creator_phone)
);

alter table public.creator_subscriptions enable row level security;
revoke all on table public.creator_subscriptions from anon, authenticated;

-- One row per consumed receipt, so the same signed transaction can't be
-- replayed to buy a month of a dozen different creators.
create table if not exists public.creator_sub_receipts (
  txn_id     text primary key,
  created_at timestamptz not null default now()
);
alter table public.creator_sub_receipts enable row level security;
revoke all on table public.creator_sub_receipts from anon, authenticated;

-- ---------------------------------------------------------------------------
-- 5. Read gates (security definer — the only doors).
-- ---------------------------------------------------------------------------

-- The one door to a paid body: the author, or an account with an active pass.
-- Anyone else (or anon, which has no phone) gets null.
create or replace function public.public_paid_body(p text)
returns text
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  me     text := (auth.jwt() ->> 'phone');
  author text;
  txt    text;
begin
  select author_phone, body into author, txt
    from public.public_paid_bodies where post_id = p;
  if author is null then return null; end if;
  if me is not null and me = author then return txt; end if;
  if me is null then return null; end if;
  if exists (
    select 1 from public.creator_subscriptions s
     where s.subscriber_phone = me
       and s.creator_phone = author
       and s.expires_at > now()
  ) then
    return txt;
  end if;
  return null;
end;
$$;

-- Whether the caller holds an active pass to a creator (by handle).
create or replace function public.creator_sub_active(u text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
      from public.creator_subscriptions s
      join public.usernames t on t.phone = s.creator_phone
     where s.subscriber_phone = (auth.jwt() ->> 'phone')
       and lower(t.username) = lower(u)
       and s.expires_at > now()
  );
$$;

-- The caller's own active passes — creator handle + expiry — for reconciling
-- the local list on start. Only ever your own rows; no phone ever returned.
create or replace function public.creator_my_subs()
returns table(creator text, expires_at timestamptz)
language sql
stable
security definer
set search_path = public
as $$
  select t.username, s.expires_at
    from public.creator_subscriptions s
    join public.usernames t on t.phone = s.creator_phone
   where s.subscriber_phone = (auth.jwt() ->> 'phone')
     and s.expires_at > now();
$$;

-- How many active subscribers a creator has, for their own dashboard. A count
-- only — who is subscribed is nobody's business but the counter's.
create or replace function public.creator_subscribers_count(u text)
returns bigint
language sql
stable
security definer
set search_path = public
as $$
  select count(*)
    from public.creator_subscriptions s
    join public.usernames t on t.phone = s.creator_phone
   where lower(t.username) = lower(u)
     and s.expires_at > now();
$$;

grant execute on function public.public_paid_body(text) to anon, authenticated;
grant execute on function public.creator_sub_active(text) to authenticated;
grant execute on function public.creator_my_subs() to authenticated;
grant execute on function public.creator_subscribers_count(text)
  to anon, authenticated;


-- ####################################################################
-- ## docs/payment_controls.sql
-- ####################################################################
-- Who may send you money, how much can leave at once, and how much in a day.
-- ============================================================================
-- Run this in the Supabase dashboard (SQL Editor -> New query -> Run). Safe to
-- run again: a project already holding the first version is upgraded in place.
--
-- Every one of these is enforced in payments-create-intent, before a charge
-- exists. A limit the app applies is a limit a modified app ignores.

create table if not exists public.payment_settings (
  phone text primary key,                    -- E.164 digits

  -- Who is allowed to send money to this person.
  --   anyone  - the default
  --   nobody  - receiving is switched off entirely
  accepts_from text not null default 'anyone'
    check (accepts_from in ('anyone', 'nobody')),

  -- The most this account may SEND in a rolling 24 hours, in cents. Caps the
  -- damage from a phone someone else has picked up, and from a mistake made
  -- repeatedly. Null means the project default applies.
  daily_send_limit_cents int,

  -- The most one single transfer may be, in cents. A day's worth of small
  -- mistakes and one big one are different failures; the rolling cap only
  -- catches the first. Null or 0 means no per-transfer cap.
  max_send_cents int,

  -- Everything off, both directions, in one tap. Nothing leaves and nothing
  -- arrives while this is set.
  paused boolean not null default false,

  -- A raise that has been asked for and has not arrived yet. Lowering a limit
  -- takes effect immediately; raising one waits 24 hours, so an unlocked phone
  -- in the wrong hands is held to whatever its owner chose while calm. Both
  -- columns of a pair are set together or not at all.
  pending_daily_send_limit_cents int,
  pending_daily_effective_at timestamptz,
  pending_max_send_cents int,
  pending_max_effective_at timestamptz,

  updated_at timestamptz not null default now()
);

-- Added after the first version shipped. The columns are in the CREATE above
-- too, so a fresh project reads the whole table in one place; these ALTERs are
-- what upgrade a project that already ran v1. Both are no-ops on the other.
alter table public.payment_settings
  add column if not exists paused boolean not null default false;
alter table public.payment_settings
  add column if not exists max_send_cents int;
alter table public.payment_settings
  add column if not exists pending_daily_send_limit_cents int;
alter table public.payment_settings
  add column if not exists pending_daily_effective_at timestamptz;
alter table public.payment_settings
  add column if not exists pending_max_send_cents int;
alter table public.payment_settings
  add column if not exists pending_max_effective_at timestamptz;

-- People this account refuses money from, whatever accepts_from says.
create table if not exists public.payment_blocks (
  phone         text not null,   -- the recipient doing the blocking
  blocked_phone text not null,   -- the sender being refused
  created_at    timestamptz not null default now(),
  primary key (phone, blocked_phone)
);

-- Only the Edge Functions touch either table, via the service-role key, which
-- bypasses RLS. Enabling RLS with no policies means a client holding the
-- publishable key cannot raise its own send limit or unblock itself.
alter table public.payment_settings enable row level security;
alter table public.payment_blocks enable row level security;

drop policy if exists payment_settings_all on public.payment_settings;
drop policy if exists payment_blocks_all on public.payment_blocks;

-- The rolling-window sum the send limit is checked against. Only completed
-- and in-flight charges count; blocked and failed ones never took money.
create index if not exists payment_transactions_from_created_idx
  on public.payment_transactions (from_phone, updated_at);

-- What a transfer said it was for, so the history can show it (and mark
-- sparks). The note was always plaintext payment data — it already rides the
-- Stripe intent's metadata — so storing it here exposes nothing new. The
-- table stays RLS-locked; payments-history is still the only way to read it.
alter table public.payment_transactions
  add column if not exists note text not null default '';

-- ---------------------------------------------------------------------------
-- Debit-card attach history — the record behind two safeguards: a newly
-- attached card waits seven business days before instant payouts (an account
-- takeover attaches its own card and drains the balance in one motion; the
-- wait gives the real owner time to notice), and a third card inside thirty
-- days locks the feature until the changes age out. SERVICE ROLE ONLY: the
-- Edge Functions write and read it, clients get nothing — a row a client
-- could delete is a waiting period a thief could skip.
-- ---------------------------------------------------------------------------
create table if not exists public.payment_card_events (
  id         bigint generated always as identity primary key,
  phone      text not null,
  created_at timestamptz not null default now()
);
-- Bank (direct deposit) changes share the ledger: same safeguards, same
-- reasons — swapping where the money lands is the other half of the drain.
alter table public.payment_card_events
  add column if not exists kind text not null default 'card';
create index if not exists payment_card_events_phone_idx
  on public.payment_card_events (phone, created_at desc);
alter table public.payment_card_events enable row level security;
revoke all on table public.payment_card_events from anon, authenticated;


-- ####################################################################
-- ## docs/directory_numberless.sql
-- ####################################################################
-- Username search and directory rows for accounts with no phone number.
-- ============================================================================
-- Run ONCE in the Supabase SQL editor, AFTER docs/platform_moderation.sql
-- (the search filter reuses its is_locked_out()).
--
-- WHY. A numberless account has no Supabase session at all — Supabase
-- authenticates a phone — and the directory's RLS speaks only to
-- `authenticated`. So such an account could neither claim its @handle nor
-- search anyone else's, and the handle is the ONE thing a numberless account
-- can be found by. Two SECURITY DEFINER functions open exactly that path and
-- nothing more:
--
--   find_people(q)      what an authenticated directory search already shows
--                       (opted-in, not-locked-out rows), now answerable with
--                       the anon key. The raw table stays unreadable to anon.
--   claim_numberless()  inserts a directory row for an ACCOUNT CODE only —
--                       12 digits with a leading 00, a shape no real E.164
--                       number can have — so a phone account's row still
--                       requires the verified session that owns it. First
--                       claim wins: with no session there is no way to prove
--                       a code is yours, so an existing row's handle can
--                       never be changed through here (only its display name,
--                       and only when the handle matches).

-- The columns the functions read, for projects that have not run
-- docs/directory_privacy.sql / docs/identity_directory_badge.sql yet.
alter table public.usernames
  add column if not exists find_by_username boolean not null default true;
alter table public.usernames
  add column if not exists verified boolean not null default false;

-- A DROP first, because the return type has changed since this file was
-- written (docs/public_profiles.sql widened it to carry a profile) and
-- `create or replace` cannot change one — re-running the migrations in order
-- fails outright without this. Harmless on a fresh project.
drop function if exists public.find_people(text);
create function public.find_people(q text)
returns table (phone text, username text, name text, verified boolean)
language plpgsql security definer set search_path = public as $$
begin
  -- Handle-shaped queries only; anything else could smuggle LIKE wildcards.
  if q is null or q !~ '^[a-z0-9_.]{2,32}$' then
    return;
  end if;
  return query
    select u.phone, u.username, u.name, coalesce(u.verified, false)
    from public.usernames u
    -- '_' is a legal handle character but a LIKE wildcard; escape it so
    -- searching a_b does not match axb.
    where lower(u.username) like replace(q, '_', '\_') || '%'
      and coalesce(u.find_by_username, true)
      and not public.is_locked_out(u.phone)
    order by u.username
    limit 25;
end $$;

revoke all on function public.find_people(text) from public;
grant execute on function public.find_people(text) to anon, authenticated;

create or replace function public.claim_numberless(
    code text, uname text, display text default '')
returns boolean
language plpgsql security definer set search_path = public as $$
begin
  -- Codes only. A real number's row is written through RLS by its session.
  if code is null or code !~ '^00[0-9]{10}$' then
    return false;
  end if;
  if uname is null or uname !~ '^[a-z0-9_.]{3,32}$' then
    return false;
  end if;
  if public.is_locked_out(code) then
    return false;
  end if;
  insert into public.usernames (phone, username, name, updated_at)
  values (code, uname, coalesce(display, ''), now())
  -- The same account re-claiming (a display-name change, a retried sign-up)
  -- is fine; CHANGING the handle is not — no session, no proof the code is
  -- yours.
  on conflict (phone) do update
    set name = excluded.name, updated_at = now()
    where usernames.username = excluded.username;
  return found;
exception
  when unique_violation then
    return false; -- the handle belongs to someone else
end $$;

revoke all on function public.claim_numberless(text, text, text) from public;
grant execute on function public.claim_numberless(text, text, text)
  to anon, authenticated;


-- ####################################################################
-- ## docs/identity_backup.sql
-- ####################################################################
-- ============================================================================
-- Encryption recovery (run whole file in Supabase SQL editor; idempotent)
-- ============================================================================
-- One sealed blob per account: the device's identity private key, encrypted
-- ON THE DEVICE under a recovery code the app minted and only the user holds
-- (PBKDF2-HMAC-SHA256 at 120k rounds over a random salt, then AES-256-GCM).
-- The server stores ciphertext it can never open — 80 bits of code entropy
-- stand between a leaked row and the key. This is what lets a reinstall or a
-- new phone restore the SAME identity instead of minting a fresh one, which
-- is the root cause of "sealed to a key this device no longer has".
--
-- Access is the part worth being careful about, because a REPLACED blob is a
-- broken restore (nothing leaks — the thief's blob won't open with the
-- user's code — but the user's backup is gone):
--
--   * Phone accounts ride their session: RLS pins insert/update/select to
--     the JWT's own number, so nobody can read, plant, or replace anybody
--     else's backup.
--   * Numberless accounts (minted '00…' codes) have no session at all, so
--     two SECURITY DEFINER RPCs are their only door, and both refuse
--     anything that is not a '00' inbox. Writes are first-come: the blob
--     can be created but never overwritten anonymously.

create table if not exists public.identity_backups (
  inbox      text primary key,               -- phone digits / account code
  blob       text not null,                  -- sealed archive, never plaintext
  updated_at timestamptz not null default now()
);

alter table public.identity_backups enable row level security;

-- Supabase grants every new public table to anon and authenticated; the
-- policies below only mean anything once that blanket grant is gone.
revoke all on table public.identity_backups from anon;
revoke all on table public.identity_backups from authenticated;
grant select, insert, update on public.identity_backups to authenticated;

drop policy if exists identity_backups_own_select on public.identity_backups;
create policy identity_backups_own_select on public.identity_backups
  for select to authenticated
  using (inbox = regexp_replace(coalesce(auth.jwt() ->> 'phone', ''), '\D', '', 'g'));

drop policy if exists identity_backups_own_insert on public.identity_backups;
create policy identity_backups_own_insert on public.identity_backups
  for insert to authenticated
  with check (inbox = regexp_replace(coalesce(auth.jwt() ->> 'phone', ''), '\D', '', 'g'));

drop policy if exists identity_backups_own_update on public.identity_backups;
create policy identity_backups_own_update on public.identity_backups
  for update to authenticated
  using (inbox = regexp_replace(coalesce(auth.jwt() ->> 'phone', ''), '\D', '', 'g'))
  with check (inbox = regexp_replace(coalesce(auth.jwt() ->> 'phone', ''), '\D', '', 'g'));

-- The numberless door. First write wins: an anonymous caller can create a
-- '00' account's backup but never replace one, because "anonymous" and
-- "allowed to overwrite" cannot coexist without some proof of ownership,
-- and a numberless account has none to offer.
create or replace function public.put_identity_backup(inboxv text, blobv text)
returns boolean
language plpgsql security definer set search_path = public as $$
begin
  if inboxv is null or inboxv !~ '^00\d+$' or blobv is null or blobv = '' then
    return false;
  end if;
  insert into public.identity_backups (inbox, blob)
    values (inboxv, blobv)
    on conflict (inbox) do nothing;
  return exists (
    select 1 from public.identity_backups
    where inbox = inboxv and blob = blobv);
end $$;

-- Reading is also '00'-only: a REAL number's blob is reachable only through
-- its owner's session, so an anonymous caller can never even fetch the
-- ciphertext to brute-force offline.
create or replace function public.get_identity_backup(inboxv text)
returns text
language sql security definer set search_path = public as $$
  select blob from public.identity_backups
  where inbox = inboxv and inboxv ~ '^00\d+$';
$$;


-- ####################################################################
-- ## docs/account_lifecycle.sql
-- ####################################################################
-- Temporary deactivation for the people directory.
-- ============================================================================
-- Run ONCE in the Supabase SQL editor, AFTER docs/directory_numberless.sql
-- (this replaces its find_people with one more filter).
--
-- WHY. "Deactivate my account" has to mean something on the server, or it
-- means nothing: the app can sign somebody out locally, but their @handle
-- stayed findable by everyone. The `hidden` flag is that meaning — a hidden
-- row answers no search, while the handle stays THEIRS (the row keeps
-- existing, so nobody can take the name while they're away). Reactivation is
-- signing back in: the app clears the flag through the same own-row RLS
-- update that set it.
--
-- Deletion is not here on purpose: deleting an account also has to delete
-- the AUTH user, which no RLS policy can do — that is the delete-account
-- Edge Function (service role), which removes every phone-keyed row and the
-- user itself.

alter table public.usernames
  add column if not exists hidden boolean not null default false;

-- The same function docs/directory_numberless.sql installs, with one more
-- line: hidden rows answer no search — not by handle, not by anyone.
-- A DROP first, because the return type has changed since this file was
-- written (docs/public_profiles.sql widened it to carry a profile) and
-- `create or replace` cannot change one — re-running the migrations in order
-- fails outright without this. Harmless on a fresh project.
drop function if exists public.find_people(text);
create function public.find_people(q text)
returns table (phone text, username text, name text, verified boolean)
language plpgsql security definer set search_path = public as $$
begin
  -- Handle-shaped queries only; anything else could smuggle LIKE wildcards.
  if q is null or q !~ '^[a-z0-9_.]{2,32}$' then
    return;
  end if;
  return query
    select u.phone, u.username, u.name, coalesce(u.verified, false)
    from public.usernames u
    -- '_' is a legal handle character but a LIKE wildcard; escape it so
    -- searching a_b does not match axb.
    where lower(u.username) like replace(q, '_', '\_') || '%'
      and coalesce(u.find_by_username, true)
      and not coalesce(u.hidden, false)
      and not public.is_locked_out(u.phone)
    order by u.username
    limit 25;
end $$;

revoke all on function public.find_people(text) from public;
grant execute on function public.find_people(text) to anon, authenticated;


-- ####################################################################
-- ## docs/admin_users.sql
-- ####################################################################
-- Admin user roster (2026-08-07)
-- ---------------------------------------------------------------------------
-- An owner/admin-only window onto the WHOLE account directory — including the
-- name-only ("numberless") signups whose key is a 00-prefixed account code, not
-- a phone. Those accounts get a real public.usernames row at sign-up
-- (claim_numberless), but they never appear in reports or sanctions, so before
-- this there was no way for staff to see them, or to know how many accounts
-- exist at all.
--
-- platform_roles is service-role only (RLS on, no client policy), so the staff
-- check runs INSIDE these security-definer functions: a client that isn't an
-- owner or admin — as the SERVER sees it, not as the app claims — gets nothing.
-- Neither function returns a phone number: staff act on an account by its
-- @username (the moderation console's "Act on account" already does), so the
-- roster is handles, names and flags, never the directory's phone column.
--
-- Run this AFTER platform_moderation.sql (platform_roles), directory_numberless.sql
-- (verified/find_by_username) and account_lifecycle.sql (hidden).

-- ---------------------------------------------------------------------------
-- Last seen (2026-08-08). A single timestamp per account, bumped by the client
-- on sign-in and every time the app comes to the foreground. It is what lets
-- the moderation roster show who is online now and when everyone else was last
-- around. Only the account itself can bump its own row (the definer function
-- resolves the caller from their JWT), and only staff can read it (through
-- admin_list_users). A NAME-ONLY account has no session, so it can never call
-- touch_last_seen — its last_seen stays null and the roster shows "never seen",
-- which is the honest answer: the app has no way to know it is online.
alter table public.usernames
  add column if not exists last_seen timestamptz;

-- The caller stamps their own last_seen = now(). Resolve the caller to their
-- directory phone by DIGITS (the JWT's phone claim has no '+', the directory
-- stores E.164 with one), the same normalisation public_follow uses.
create or replace function public.touch_last_seen()
returns void
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  jwt_phone text := nullif(auth.jwt() ->> 'phone', '');
begin
  if jwt_phone is null then return; end if;
  update public.usernames
     set last_seen = now()
   where regexp_replace(phone, '\D', '', 'g')
       = regexp_replace(jwt_phone, '\D', '', 'g');
end;
$$;

revoke execute on function public.touch_last_seen() from anon;
grant execute on function public.touch_last_seen() to authenticated;

-- How many accounts exist, all kinds. Owner/admin only.
create or replace function public.admin_user_count()
returns bigint
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  ph text := nullif(auth.jwt() ->> 'phone', '');
begin
  if ph is null or not exists (
      select 1 from public.platform_roles r
       where r.phone = ph and r.role in ('owner', 'admin')) then
    raise exception 'not authorised';
  end if;
  return (select count(*) from public.usernames);
end;
$$;

revoke execute on function public.admin_user_count() from anon;
grant execute on function public.admin_user_count() to authenticated;

-- The roster, newest first. numberless is true for a name-only account (its key
-- is a 00-prefixed code, not a phone). No phone column crosses the wire.
--
-- Dropped first: this file gained a last_seen column in the return type, and
-- create-or-replace cannot change a function's OUT parameters ("cannot change
-- return type of existing function") — so a project that ran the earlier
-- version must drop it before the new shape can land. Harmless on a fresh DB.
drop function if exists public.admin_list_users(int, int);
create or replace function public.admin_list_users(lim int default 200, off int default 0)
returns table(
  username    text,
  name        text,
  verified    boolean,
  hidden      boolean,
  numberless  boolean,
  updated_at  timestamptz,
  last_seen   timestamptz)
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  ph text := nullif(auth.jwt() ->> 'phone', '');
begin
  if ph is null or not exists (
      select 1 from public.platform_roles r
       where r.phone = ph and r.role in ('owner', 'admin')) then
    raise exception 'not authorised';
  end if;
  return query
    select u.username,
           coalesce(u.name, ''),
           coalesce(u.verified, false),
           coalesce(u.hidden, false),
           (u.phone ~ '^00[0-9]{10}$'),
           u.updated_at,
           u.last_seen
      from public.usernames u
     -- Most-recently-active first: who's online floats to the top, then the
     -- freshest sign-ups (a name-only account has no last_seen, so it sorts
     -- by when its row was written).
     order by coalesce(u.last_seen, u.updated_at) desc
     limit greatest(1, least(lim, 500))
    offset greatest(0, off);
end;
$$;

revoke execute on function public.admin_list_users(int, int) from anon;
grant execute on function public.admin_list_users(int, int) to authenticated;


-- ####################################################################
-- ## docs/community_posts.sql
-- ####################################################################
-- Server-side persistence for community feed posts and marketplace listings.
-- ============================================================================
-- Run ONCE in the Supabase SQL editor.
--
-- WHY. Server posts used to be broadcast-only: a sealed envelope relayed
-- live plus a mailbox copy for whoever was offline that minute. If delivery
-- missed — a member joined later, a mailbox write failed, a device was
-- reinstalled — the listing existed only on its author's phone, which read
-- as "the marketplace doesn't show listings". This table is the durable
-- copy: every post stored ONCE, fetched by members whenever they open or
-- refresh.
--
-- WHAT THE SERVER CAN READ: nothing. `payload` is the same AES-GCM
-- ciphertext the broadcast carries, sealed to the community's secret —
-- which lives only on members' devices, handed over inside invites the
-- server also cannot read. Like the mailbox, possession of the community id
-- fetches ciphertext; the secret is what turns it into posts. Chats are
-- NOT here and never will be: message content stays on devices, full stop.
--
-- Row lifecycle: upserted on post and on every listing update (revision
-- checks on the client keep replays harmless), deleted when the author
-- deletes the post. The client caps a payload the same place the relay
-- does; the CHECK below is the backstop.

create table if not exists public.community_posts (
  community_id text not null,
  post_id      text not null,
  payload      text not null check (char_length(payload) <= 400000),
  updated_at   timestamptz not null default now(),
  primary key (community_id, post_id)
);

create index if not exists community_posts_cid_idx
  on public.community_posts (community_id, updated_at desc);

alter table public.community_posts enable row level security;

-- The mailbox's trust model: the app key may write and read rows, because
-- rows are sealed ciphertext and the community id is unguessable. A delete
-- needs the row's exact ids — the same capability writing needed.
drop policy if exists community_posts_insert on public.community_posts;
create policy community_posts_insert on public.community_posts
  for insert to anon, authenticated with check (true);

drop policy if exists community_posts_select on public.community_posts;
create policy community_posts_select on public.community_posts
  for select to anon, authenticated using (true);

drop policy if exists community_posts_update on public.community_posts;
create policy community_posts_update on public.community_posts
  for update to anon, authenticated using (true) with check (true);

drop policy if exists community_posts_delete on public.community_posts;
create policy community_posts_delete on public.community_posts
  for delete to anon, authenticated using (true);


-- ####################################################################
-- ## docs/ai_usage.sql
-- ####################################################################
-- Server-side rate limit for Okay AI (2026-08-06). Real cost control on top of
-- the client's free-tier UX: a per-caller daily message count the `ai-chat`
-- Edge Function checks BEFORE calling OpenRouter, so a modified client can't
-- run the token bill past the cap.
--
-- Written ONLY by the `ai-chat` function through `ai_note_usage` (service
-- role). No client grants at all — a client can neither read another caller's
-- usage nor reset its own. The cap itself is the function's `AI_DAILY_CAP`
-- env var; this just keeps the tally.
--
-- Run this in the SQL editor. Until it exists the function fails OPEN (no
-- limit), so a missing migration never breaks the assistant — it just leaves
-- the ceiling off.
-- ---------------------------------------------------------------------------

create table if not exists public.ai_usage (
  usage_key text not null,   -- the caller: their phone, or an IP fallback
  day       date not null default current_date,
  count     int  not null default 0,
  primary key (usage_key, day)
);

alter table public.ai_usage enable row level security;
revoke all on table public.ai_usage from anon, authenticated;

-- Atomically bump today's count for a caller and return the new value. The
-- function checks it against the cap; the increment is harmless for a refused
-- request because the refusal happens before any model call, so no tokens are
-- spent — the counter simply keeps climbing while every over-cap request is
-- turned away.
create or replace function public.ai_note_usage(k text)
returns int
language sql
volatile
security definer
set search_path = public
as $$
  insert into public.ai_usage (usage_key, day, count)
  values (k, current_date, 1)
  on conflict (usage_key, day)
    do update set count = public.ai_usage.count + 1
  returning count;
$$;

-- Only the service role (the Edge Function) may call it — never a client.
-- Postgres grants EXECUTE to PUBLIC on a new function, so revoke that too, or
-- anon/authenticated inherit it no matter what the named revokes say.
revoke execute on function public.ai_note_usage(text)
  from public, anon, authenticated;


-- ####################################################################
-- ## docs/ai_training.sql
-- ####################################################################
-- AI training corpus (2026-08-06). The rated Okay AI exchanges a future
-- fine-tune of "your own AI" is built from — collected ONLY from users who
-- opted in to "Help improve Okay AI", and ONLY assistant conversations (never
-- human-to-human chats, which are end-to-end encrypted and never reach a server
-- that can read them).
--
-- Written ONLY by the `ai-feedback` Edge Function (service role). No client
-- grants at all: a client can neither read the corpus nor write to it directly.
-- The `submitter` is a salted hash, not a phone — enough to rate-limit an
-- abuser or drop one person's samples on request, without storing identity.
--
-- The `rating` is the curation signal: train on the thumbs-up (rating = 1)
-- rows, filtered, so the model learns from good exchanges, not nonsense.
--
-- Run this in the SQL editor, then paste the `ai-feedback` function. Until
-- then feedback is best-effort and silently collects nothing.
-- ---------------------------------------------------------------------------

create table if not exists public.ai_training_samples (
  id         bigint generated always as identity primary key,
  prompt     text not null,
  reply      text not null,
  rating     int  not null check (rating in (-1, 1)),
  submitter  text not null default '',
  created_at timestamptz not null default now()
);

alter table public.ai_training_samples enable row level security;
-- Take back every grant Supabase gives a new public table, and add none: the
-- ai-feedback function (service role) is the only writer, and nobody reads it
-- through the API — the corpus is exported for training out of band.
revoke all on table public.ai_training_samples from anon, authenticated;
revoke all on sequence public.ai_training_samples_id_seq from anon, authenticated;


-- ####################################################################
-- ## docs/legal_documents.sql
-- ####################################################################
-- Owner-editable legal documents (2026-08-06). The Terms of Service and
-- Privacy Policy, so the owner can update them from inside the app without
-- shipping a new build. A single row (id = 1).
--
-- READABLE BY EVERYONE — the app fetches the current text on launch, the same
-- way it fetches any public config; the documents are public policy. WRITABLE
-- ONLY by the `legal-set` Edge Function (service role), which first checks the
-- caller is the platform owner. No client write grants at all.
--
-- The `version` is what the acceptance gate compares against: bumping it (which
-- publishing does) asks every user to agree again.
--
-- Run this in the SQL editor, then paste the `legal-set` function. Until then
-- the app shows its built-in documents and the owner editor says it isn't set
-- up yet.
-- ---------------------------------------------------------------------------

create table if not exists public.legal_documents (
  id           int primary key default 1,
  terms        jsonb not null default '[]'::jsonb,
  privacy      jsonb not null default '[]'::jsonb,
  version      int  not null default 0,
  last_updated text not null default '',
  edited_at    timestamptz not null default now(),
  constraint legal_documents_singleton check (id = 1)
);

alter table public.legal_documents enable row level security;

-- Anyone may READ the current documents (public policy, fetched on launch).
drop policy if exists legal_documents_read on public.legal_documents;
create policy legal_documents_read on public.legal_documents
  for select using (true);
grant select on table public.legal_documents to anon, authenticated;

-- Nobody writes through the API. The legal-set function (service role, which
-- bypasses RLS) is the only writer, and it checks platform ownership first.
revoke insert, update, delete on table public.legal_documents
  from anon, authenticated;


-- ####################################################################
-- ## docs/public_feed_edit.sql
-- ####################################################################
-- Editing a public-feed post — a narrow, deliberate opening in the otherwise
-- append-only design (docs/public_feed.sql revokes UPDATE outright, because an
-- editable public post with no history is a way to bait people and then rewrite
-- it). This grants exactly enough to fix a post, and no more:
--
--   * only the AUTHOR, and only while not silenced (same as posting),
--   * only within a SHORT WINDOW after posting (15 minutes) — long enough for a
--     typo, too short to rewrite a post people have already acted on,
--   * only the BODY (and the edited_at stamp) — never author, never counts,
--   * and every edit is STAMPED, so an edited post says so.
--
-- The re-moderation is client-side, exactly like the original post: the app
-- screens the new text through the moderation-screen function before it calls
-- the update. The server enforces WHO and WHEN; the client enforces WHAT, the
-- same split posting already uses.
--
-- Idempotent, and safe to run more than once. Apply AFTER docs/public_feed.sql
-- and docs/creator_subscriptions.sql: it re-creates the public_feed view as the
-- final word on its shape, carrying paid + sub_cents (from creator
-- subscriptions) AND the new edited_at — so running this also restores the
-- paywall columns if a re-run of public_feed.sql had dropped them.

-- 1. The stamp: null means never edited.
alter table public.public_posts
  add column if not exists edited_at timestamptz;

-- public_posts is granted SELECT column-by-column (never table-wide, so the
-- phone stays unreadable), and the feed view runs security_invoker — so a NEW
-- column is invisible through the view until it's granted too, exactly like
-- paid/sub_cents were.
--
-- paid/sub_cents are RE-GRANTED here, not merely assumed: this file recreates
-- the view carrying them, and it runs LAST. If public_feed.sql was re-run
-- after creator_subscriptions.sql, its table-wide `revoke select … from anon`
-- wiped those column grants while leaving the view that reads them — and the
-- whole feed then fails for anon with "permission denied for table
-- public_posts" (a security_invoker view needs the caller to hold every column
-- it selects). Granting them here makes this file self-sufficient: run it and
-- the feed reads, whatever order came before.
grant select (paid, sub_cents, edited_at)
  on public.public_posts to anon, authenticated;

-- 2. Give back UPDATE, but only on the two columns an edit may touch. A
-- column-level grant means an UPDATE of anything else is refused before RLS is
-- even consulted.
grant update (body, edited_at) on public.public_posts to authenticated;

-- 3. The policy: your own post, not silenced, inside the window. Both USING
-- (which rows you may target) and WITH CHECK (what the row may become) carry
-- the window, so the edit is refused the moment it closes.
drop policy if exists public_posts_update_own on public.public_posts;
create policy public_posts_update_own on public.public_posts
  for update to authenticated
  using (
    author_phone = (auth.jwt() ->> 'phone')
    and not public.is_silenced(author_phone)
    and created_at > now() - interval '15 minutes'
  )
  with check (
    author_phone = (auth.jwt() ->> 'phone')
    and created_at > now() - interval '15 minutes'
  );

-- 4. The feed view, now also carrying edited_at (and still paid + sub_cents).
create or replace view public.public_feed
with (security_invoker = on) as
select
  p.id,
  p.author_username,
  p.author_name,
  p.author_verified,
  p.body,
  p.reply_to,
  p.repost_of,
  p.image_path,
  p.gif_url,
  p.video_path,
  p.poll_options,
  p.poll_closes_at,
  p.created_at,
  p.view_count,
  public.public_post_like_count(p.id)   as like_count,
  public.public_post_reply_count(p.id)  as reply_count,
  public.public_post_repost_count(p.id) as repost_count,
  public.public_post_vote_counts(p.id)  as poll_votes,
  public.public_post_spark_count(p.id)  as spark_count,
  public.public_post_spark_cents(p.id)  as spark_cents,
  p.paid,
  p.sub_cents,
  -- Appended LAST on purpose: create-or-replace can only add view columns at
  -- the end, never insert one mid-list (it reads as renaming the column there).
  p.edited_at
from public.public_posts p;

grant select on public.public_feed to anon, authenticated;


-- ####################################################################
-- ## docs/public_feed_avatars.sql
-- ####################################################################
-- Public newsfeed: carry the author's AVATAR on the post, beside the name and
-- the badge it already carries.
--
-- Reported as "it doesn't show the right profile pictures on my other phone":
-- a second account, with no chats, saw a timeline of letter avatars. That was
-- not a rendering fault. `FeedAvatar` resolves a face through `knownUserFor`,
-- which answers only for YOURSELF or a chat CONTACT — and the feed row carried
-- nothing else to draw, because `public_posts` has only ever held
-- author_username, author_name and author_verified. A stranger on the public
-- timeline is exactly the person a device cannot know, so the one surface
-- built for meeting people was the one that could never show their face.
--
-- **The snapshot is the existing pattern, not a new exposure.** author_name
-- and author_verified are already written onto the post at post time — the
-- author's own presentation, published because they chose to post in public.
-- The avatar joins them on the same terms: only somebody who posts publicly
-- publishes a face, and only for the post they chose to make. That is why this
-- is on the POST rather than in the `usernames` directory, which would publish
-- the avatar of everyone who has an account, including people who never post,
-- to anyone who can guess a handle.
--
-- **The phone is deliberately NOT among these columns**, and nothing here
-- needs it: the client re-salts a legacy avatar seed (lib/util/avatar_seed.dart)
-- with the author's HANDLE, which a public post already carries, and only
-- falls back to a number when there is no handle at all.
--
-- A contact this device really knows still wins over the snapshot, so their
-- face stays live; the snapshot is what a STRANGER draws with. That split also
-- answers the one cost of snapshotting — a changed avatar does not reach back
-- into old posts, exactly as a changed display name already does not.
--
-- Idempotent, and safe to run more than once. Apply AFTER docs/public_feed.sql,
-- docs/creator_subscriptions.sql and docs/public_feed_edit.sql: like that last
-- one, this re-creates the public_feed view as the final word on its shape,
-- carrying paid + sub_cents + edited_at AND the six new columns.

-- 1. The columns. Empty is "said nothing", which every reader already treats
--    as "fall back to the initial", so an old row needs no migration.
alter table public.public_posts
  add column if not exists author_avatar_color  text not null default '',
  add column if not exists author_avatar_color2 text not null default '',
  add column if not exists author_emoji         text not null default '',
  add column if not exists author_avatar_seed   text not null default '',
  add column if not exists author_avatar_face   text not null default '',
  add column if not exists author_avatar_gif    text not null default '';

-- Bounded, because these are client-supplied and a public table is the wrong
-- place to discover somebody pasting a megabyte into a colour. The face is a
-- JSON selection (a couple of hundred bytes in practice) and the GIF is a URL
-- the client already refuses past 400 characters; these are the ceilings, not
-- the expected sizes.
do $$
begin
  alter table public.public_posts
    add constraint public_posts_avatar_len check (
      length(author_avatar_color)  <= 16
      and length(author_avatar_color2) <= 16
      and length(author_emoji)      <= 16
      and length(author_avatar_seed) <= 64
      and length(author_avatar_face) <= 2000
      and length(author_avatar_gif)  <= 512
    );
exception
  when duplicate_object then null;
end $$;

-- 2. public_posts is granted SELECT column-by-column — never table-wide, so
--    author_phone stays unreadable — and the feed view runs security_invoker,
--    so a new column is invisible through the view until it is granted too.
--    paid/sub_cents/edited_at are re-granted here for the same reason
--    public_feed_edit.sql re-grants its predecessors': this file runs LAST, and
--    a re-run of public_feed.sql in between would have wiped them with its
--    table-wide revoke while leaving the view that reads them, failing the
--    whole feed for anon with "permission denied for table public_posts".
grant select (paid, sub_cents, edited_at,
              author_avatar_color, author_avatar_color2, author_emoji,
              author_avatar_seed, author_avatar_face, author_avatar_gif)
  on public.public_posts to anon, authenticated;

-- The author writes their own, and only their own: the INSERT policy already
-- pins author_phone to the caller's JWT, so there is no way to publish a face
-- onto somebody else's post. UPDATE stays limited to body + edited_at, so an
-- edit cannot quietly swap the avatar on a post people have already read.
grant insert (author_avatar_color, author_avatar_color2, author_emoji,
              author_avatar_seed, author_avatar_face, author_avatar_gif)
  on public.public_posts to authenticated;

-- 3. The feed view, now also carrying the avatar.
create or replace view public.public_feed
with (security_invoker = on) as
select
  p.id,
  p.author_username,
  p.author_name,
  p.author_verified,
  p.body,
  p.reply_to,
  p.repost_of,
  p.image_path,
  p.gif_url,
  p.video_path,
  p.poll_options,
  p.poll_closes_at,
  p.created_at,
  p.view_count,
  public.public_post_like_count(p.id)   as like_count,
  public.public_post_reply_count(p.id)  as reply_count,
  public.public_post_repost_count(p.id) as repost_count,
  public.public_post_vote_counts(p.id)  as poll_votes,
  public.public_post_spark_count(p.id)  as spark_count,
  public.public_post_spark_cents(p.id)  as spark_cents,
  p.paid,
  p.sub_cents,
  p.edited_at,
  -- Appended LAST on purpose: create-or-replace can only add view columns at
  -- the end, never insert one mid-list (it reads as renaming the column there).
  p.author_avatar_color,
  p.author_avatar_color2,
  p.author_emoji,
  p.author_avatar_seed,
  p.author_avatar_face,
  p.author_avatar_gif
from public.public_posts p;

grant select on public.public_feed to anon, authenticated;


-- ####################################################################
-- ## docs/public_forum.sql
-- ####################################################################
-- The public forum: a world-readable, Reddit-shaped discussion board that lives
-- OUTSIDE any server. Anyone with the app can read it; anyone signed in can
-- post, comment and vote.
-- ============================================================================
-- Run ONCE in the Supabase SQL editor, AFTER docs/platform_moderation.sql and
-- docs/public_feed.sql — this leans on public.is_locked_out() (to keep banned
-- accounts out) and public.is_silenced() (to stop a timed-out account writing),
-- both defined by those files.
--
-- WHY THIS IS PLAINTEXT THE SERVER CAN READ, like the public feed.
--
-- Servers' forums are sealed under a community key; this one has no community,
-- so it has no key to seal under. A board whose audience is everyone cannot be
-- encrypted to everyone — the key would have to be public, which is the same as
-- no key. So the rule for these tables is the public feed's rule: **anything
-- posted here is public**, permanently, to anybody with the app. Private
-- messaging is untouched.
--
-- What is still protected is the author's phone number: clients are granted the
-- other columns and never that one, and attribution is by username (already
-- public in the directory), exactly as the public feed does it.
--
-- ORDER MATTERS, both directions: a function body is parsed at creation (its
-- tables must exist first), and a policy resolves the functions it calls at
-- creation (they must exist first). Hence tables, then functions, then
-- privileges and policies, then the view.

-- ---------------------------------------------------------------------------
-- 1. Tables
-- ---------------------------------------------------------------------------
create table if not exists public.public_forum_posts (
  -- Client-generated, so a device recognises its own post coming back.
  id              text primary key,
  -- E.164 digits. Ownership only — never granted to a client role below.
  author_phone    text not null,
  author_username text not null default '',
  author_name     text not null default '',
  -- Self-attested, like the badge on a chat message; the directory's own
  -- `verified` is the stronger claim. Here for rendering without a join.
  author_verified boolean not null default false,
  -- A forum post leads with a title, like Reddit. One to 140 characters.
  title           text not null check (char_length(title) between 1 and 140),
  -- The body may be empty when a GIF or image carries the post.
  body            text not null default '' check (char_length(body) <= 4000),
  -- One of the app's forumTags, or '' for untagged. Kept as a plain string so
  -- old rows stay valid if the tag list changes.
  tag             text not null default '',
  -- The section (subreddit-style board) this post lives in — a slug from
  -- public_forum_sections, or '' for the default "General" board. A plain
  -- string, not a foreign key, so a post survives its section being renamed
  -- or removed (it just falls back to General).
  section         text not null default '',
  -- An address, not bytes — a GIF picked from the provider is already served
  -- from their CDN; copying it here would be paying to serve it twice.
  gif_url         text not null default '',
  -- Object name in the world-readable public-media bucket (shared with the
  -- public feed). Unsealed, because a public post has nobody to keep it from.
  image_path      text not null default '',
  created_at      timestamptz not null default now(),
  -- Reserved for a later in-window edit path, like the public feed's; unused
  -- for now (there is no update grant or policy below, so posts are
  -- append-only until that lands).
  edited_at       timestamptz,
  -- Something has to be in a post: a title always is, so this only guards the
  -- degenerate all-blank row a bug could produce.
  constraint public_forum_posts_not_empty check (
    char_length(title) > 0
  )
);

create table if not exists public.public_forum_comments (
  id              text primary key,
  post_id         text not null
                    references public.public_forum_posts(id) on delete cascade,
  author_phone    text not null,
  author_username text not null default '',
  author_name     text not null default '',
  author_verified boolean not null default false,
  body            text not null default '' check (char_length(body) <= 4000),
  gif_url         text not null default '',
  -- A reply points at the comment it answers; deleting a comment takes its
  -- replies with it. Null for a top-level comment on the post.
  parent_id       text references public.public_forum_comments(id)
                    on delete cascade,
  created_at      timestamptz not null default now(),
  -- A comment with neither words nor a GIF is a rendering bug.
  constraint public_forum_comments_not_empty check (
    char_length(body) > 0 or gif_url <> ''
  )
);

-- One vote per person per post. Unlike a poll vote (which stands forever), a
-- forum vote TOGGLES: Reddit lets you change your mind or take it back, so
-- UPDATE and DELETE are granted on your own row below. dir is +1 or -1; the
-- score is their sum.
create table if not exists public.public_forum_votes (
  post_id     text not null
                references public.public_forum_posts(id) on delete cascade,
  voter_phone text not null,
  dir         smallint not null check (dir in (-1, 1)),
  created_at  timestamptz not null default now(),
  primary key (post_id, voter_phone)
);

create index if not exists public_forum_posts_recent_idx
  on public.public_forum_posts (created_at desc);
create index if not exists public_forum_posts_author_idx
  on public.public_forum_posts (author_phone);
create index if not exists public_forum_posts_tag_idx
  on public.public_forum_posts (tag, created_at desc);
create index if not exists public_forum_comments_post_idx
  on public.public_forum_comments (post_id, created_at);
create index if not exists public_forum_votes_post_idx
  on public.public_forum_votes (post_id);

-- Sections: the subreddit-style boards anyone signed in can create. The slug
-- is the id (lowercase, 2–24 of letters/digits/underscore); the title is what
-- shows. created_by_phone is ownership only, never granted to a client.
create table if not exists public.public_forum_sections (
  slug             text primary key check (slug ~ '^[a-z0-9_]{2,24}$'),
  title            text not null default '',
  description      text not null default '' check (char_length(description) <= 300),
  created_by_phone text not null,
  created_at       timestamptz not null default now()
);
create index if not exists public_forum_sections_recent_idx
  on public.public_forum_sections (created_at desc);

-- Migration for a project that already ran the first version of this file.
alter table public.public_forum_posts
  add column if not exists section text not null default '';
create index if not exists public_forum_posts_section_idx
  on public.public_forum_posts (section, created_at desc);

alter table public.public_forum_posts    enable row level security;
alter table public.public_forum_comments enable row level security;
alter table public.public_forum_votes    enable row level security;
alter table public.public_forum_sections enable row level security;

-- ---------------------------------------------------------------------------
-- 2. Functions (the tables above have to exist first)
-- ---------------------------------------------------------------------------

-- A post's score: the sum of its votes. SECURITY DEFINER because votes are
-- readable only by the person who cast them (the policy below), so counting as
-- the caller would report your own vote and nothing else. Running as the owner
-- makes the total true while who voted stays private — the same trick the
-- public feed's like/poll counters use.
create or replace function public.public_forum_score(p text)
returns bigint
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(sum(dir), 0)::bigint
    from public.public_forum_votes where post_id = p;
$$;

-- How many comments a post has. Comments are world-readable, but count through
-- a definer function anyway so a banned author's comments (hidden by the read
-- policy) don't quietly change the number under different callers.
create or replace function public.public_forum_comment_count(p text)
returns bigint
language sql
stable
security definer
set search_path = public
as $$
  select count(*)::bigint
    from public.public_forum_comments c
   where c.post_id = p
     and not public.is_locked_out(c.author_phone);
$$;

-- ---------------------------------------------------------------------------
-- 3. Column privileges
-- ---------------------------------------------------------------------------
-- THE PHONE COLUMN, PROPERLY — the same lesson as public_posts. Supabase grants
-- these roles table-wide SELECT on every new table in public, and Postgres
-- cannot carve a column out of a table-wide grant, so `revoke select
-- (author_phone)` on its own changes nothing and leaves every number readable.
-- Revoke the whole grant, then hand back the readable columns one by one.
revoke select on table public.public_forum_posts from anon, authenticated;
grant select (id, author_username, author_name, author_verified, title, body,
              tag, section, gif_url, image_path, created_at, edited_at)
  on public.public_forum_posts to anon, authenticated;

revoke select on table public.public_forum_comments from anon, authenticated;
grant select (id, post_id, author_username, author_name, author_verified,
              body, gif_url, parent_id, created_at)
  on public.public_forum_comments to anon, authenticated;

-- Your own vote comes back so the app can highlight the arrow you pressed.
--
-- voter_phone IS in this grant, and it has to be: the app changes a vote with
-- PostgreSQL's upsert, and `on conflict (post_id, voter_phone) do update`
-- requires SELECT on the columns of the conflict target. Withholding the
-- column made every DOWN-vote and every vote CHANGE fail with "permission
-- denied for table public_forum_votes" — the plain first upvote is an INSERT
-- and worked, which is why it looked like a moderation problem rather than a
-- grant one.
--
-- It costs no privacy. The read POLICY below is what keeps votes secret: it
-- scopes SELECT to `voter_phone = your own`, so the only number this column
-- can ever hand back is the one you already know. A column grant was never
-- what was protecting it.
revoke select on table public.public_forum_votes from anon, authenticated;
grant select (post_id, voter_phone, dir, created_at)
  on public.public_forum_votes to authenticated;

-- Sections are attributed to whoever made them by title only — created_by_phone
-- is ownership, never handed to a client.
revoke select on table public.public_forum_sections from anon, authenticated;
grant select (slug, title, description, created_at)
  on public.public_forum_sections to anon, authenticated;

-- Writing is by whole row; the policies decide whose row it may be.
grant insert, delete on public.public_forum_posts to authenticated;
grant insert, delete on public.public_forum_comments to authenticated;
-- A forum vote can be changed or taken back, unlike a poll vote.
grant insert, update, delete on public.public_forum_votes to authenticated;
-- Anyone signed in may create a section. No update/delete: a board people have
-- posted into is not one creator's to rename out from under them (a moderation
-- action can remove it server-side later).
grant insert on public.public_forum_sections to authenticated;
revoke update, delete on public.public_forum_sections from anon, authenticated;

-- No UPDATE on posts or comments for anyone, and no update policy either. An
-- UPDATE matching no policy affects zero rows *without raising*, which reads
-- like success; taking the privilege away makes the refusal explicit. (An
-- in-window edit path can be added later, like docs/public_feed_edit.sql.)
revoke update on public.public_forum_posts from anon, authenticated;
revoke update on public.public_forum_comments from anon, authenticated;

-- ---------------------------------------------------------------------------
-- 4. Policies (the functions above have to exist first)
-- ---------------------------------------------------------------------------

-- Readable by anyone with the app — except posts by an account that is banned
-- or suspended, which leave the board the moment the sanction lands.
drop policy if exists public_forum_posts_read on public.public_forum_posts;
create policy public_forum_posts_read on public.public_forum_posts
  for select to anon, authenticated
  using (not public.is_locked_out(author_phone));

-- You may only post as yourself, and only while you are allowed to. Both halves
-- are enforced here, so a modified client gains nothing: the phone comes from a
-- JWT it cannot forge, and a sanctioned account is refused.
drop policy if exists public_forum_posts_insert_own on public.public_forum_posts;
create policy public_forum_posts_insert_own on public.public_forum_posts
  for insert to authenticated
  with check (
    author_phone = (auth.jwt() ->> 'phone')
    and not public.is_silenced(author_phone)
  );

drop policy if exists public_forum_posts_delete_own on public.public_forum_posts;
create policy public_forum_posts_delete_own on public.public_forum_posts
  for delete to authenticated
  using (author_phone = (auth.jwt() ->> 'phone'));

-- Comments: same read rule (a banned author's comments vanish), same write
-- rule (only as yourself, only while allowed).
drop policy if exists public_forum_comments_read on public.public_forum_comments;
create policy public_forum_comments_read on public.public_forum_comments
  for select to anon, authenticated
  using (not public.is_locked_out(author_phone));

drop policy if exists public_forum_comments_insert_own
  on public.public_forum_comments;
create policy public_forum_comments_insert_own on public.public_forum_comments
  for insert to authenticated
  with check (
    author_phone = (auth.jwt() ->> 'phone')
    and not public.is_silenced(author_phone)
  );

drop policy if exists public_forum_comments_delete_own
  on public.public_forum_comments;
create policy public_forum_comments_delete_own on public.public_forum_comments
  for delete to authenticated
  using (author_phone = (auth.jwt() ->> 'phone'));

-- Votes: you can see only your own, cast/change/take back only your own, and
-- only while allowed to interact. Voting twice is stopped by the primary key;
-- changing your mind is an UPDATE of that one row.
drop policy if exists public_forum_votes_read_own on public.public_forum_votes;
create policy public_forum_votes_read_own on public.public_forum_votes
  for select to authenticated
  using (voter_phone = (auth.jwt() ->> 'phone'));

drop policy if exists public_forum_votes_insert_own on public.public_forum_votes;
create policy public_forum_votes_insert_own on public.public_forum_votes
  for insert to authenticated
  with check (
    voter_phone = (auth.jwt() ->> 'phone')
    and not public.is_silenced(voter_phone)
  );

drop policy if exists public_forum_votes_update_own on public.public_forum_votes;
create policy public_forum_votes_update_own on public.public_forum_votes
  for update to authenticated
  using (voter_phone = (auth.jwt() ->> 'phone'))
  with check (voter_phone = (auth.jwt() ->> 'phone'));

drop policy if exists public_forum_votes_delete_own on public.public_forum_votes;
create policy public_forum_votes_delete_own on public.public_forum_votes
  for delete to authenticated
  using (voter_phone = (auth.jwt() ->> 'phone'));

-- Sections: readable by anyone, created only as yourself while allowed to.
drop policy if exists public_forum_sections_read on public.public_forum_sections;
create policy public_forum_sections_read on public.public_forum_sections
  for select to anon, authenticated
  using (true);

drop policy if exists public_forum_sections_insert_own
  on public.public_forum_sections;
create policy public_forum_sections_insert_own on public.public_forum_sections
  for insert to authenticated
  with check (
    created_by_phone = (auth.jwt() ->> 'phone')
    and not public.is_silenced(created_by_phone)
  );

-- ---------------------------------------------------------------------------
-- 5. What clients actually read
-- ---------------------------------------------------------------------------
-- A view with no phone column in it at all, so the ordinary path cannot leak
-- one even by accident. security_invoker keeps the caller's RLS in force, which
-- is what hides a banned author's posts. Dropped first: create-or-replace may
-- only append columns to a view, and score/comment_count belong beside the post
-- columns, not tacked on after a later addition.
drop view if exists public.public_forum;
create view public.public_forum
with (security_invoker = on) as
select
  p.id,
  p.author_username,
  p.author_name,
  p.author_verified,
  p.title,
  p.body,
  p.tag,
  p.section,
  p.gif_url,
  p.image_path,
  p.created_at,
  p.edited_at,
  public.public_forum_score(p.id)         as score,
  public.public_forum_comment_count(p.id) as comment_count
from public.public_forum_posts p;

grant select on public.public_forum to anon, authenticated;


-- ####################################################################
-- ## docs/public_forum_comment_votes.sql
-- ####################################################################
-- Comment votes for the public forum — the piece that makes it read like
-- Reddit rather than a flat message board.
--
-- Run AFTER docs/public_forum.sql. Safe to re-run.
--
-- Posts have had up/down votes since the forum shipped; comments never did,
-- so a good answer three replies deep had no way to rise above a bad one at
-- the top. This adds the same shape one level down: one row per voter per
-- comment, a definer tally, and a phone-free view the client reads.
--
-- The author's phone is protected exactly as it is for comments themselves —
-- the vote table is never readable by a client at all, and the comments view
-- carries every column but author_phone.

create table if not exists public.public_forum_comment_votes (
  comment_id   text not null
    references public.public_forum_comments(id) on delete cascade,
  voter_phone  text not null,
  -- 1 or -1. A withdrawn vote is a deleted row, not a zero, so the tally
  -- never has to filter and an index stays useful.
  dir          smallint not null check (dir in (-1, 1)),
  created_at   timestamptz not null default now(),
  primary key (comment_id, voter_phone)
);

create index if not exists public_forum_comment_votes_comment_idx
  on public.public_forum_comment_votes (comment_id);

alter table public.public_forum_comment_votes enable row level security;

-- WHO voted is nobody's business but the voter's, so there is no read policy
-- and no select grant. The only way anyone learns anything about these rows
-- is the aggregate below, and their own row through the insert/delete
-- policies.
revoke select on table public.public_forum_comment_votes
  from anon, authenticated;
grant insert, delete, update on table public.public_forum_comment_votes
  to authenticated;

drop policy if exists public_forum_comment_votes_own
  on public.public_forum_comment_votes;
-- Vote as yourself or not at all. A silenced (timed-out) account cannot vote,
-- the same rule its posts and comments follow.
create policy public_forum_comment_votes_own
  on public.public_forum_comment_votes
  for all to authenticated
  using (voter_phone = (auth.jwt() ->> 'phone'))
  with check (
    voter_phone = (auth.jwt() ->> 'phone')
    and not public.is_silenced(voter_phone)
  );

-- Own-row reads, so a device can show which way it voted. Scoped to the
-- caller's own rows; it reveals nobody else.
drop policy if exists public_forum_comment_votes_read_own
  on public.public_forum_comment_votes;
create policy public_forum_comment_votes_read_own
  on public.public_forum_comment_votes
  for select to authenticated
  using (voter_phone = (auth.jwt() ->> 'phone'));
grant select on table public.public_forum_comment_votes to authenticated;

-- The tally. Definer so it can read the whole table while clients cannot,
-- which is what lets a score exist without exposing who cast it.
create or replace function public.public_forum_comment_score(c text)
returns integer
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(sum(v.dir), 0)::int
    from public.public_forum_comment_votes v
   where v.comment_id = c;
$$;

-- Named explicitly. Supabase's default privileges grant EXECUTE on every new
-- function in `public` to anon and authenticated outright, and revoking the
-- PUBLIC pseudo-role does NOT remove those — a lesson this project learned
-- the hard way with find_people_by_hashes. Reading a score is fine for both,
-- so both are granted deliberately rather than by accident.
grant execute on function public.public_forum_comment_score(text)
  to anon, authenticated;

-- The phone-free comments view the client reads. Same posture as the posts
-- view: every column except author_phone, plus the tally. security_invoker
-- keeps the caller's own RLS in force — every other view in this project has
-- it; this one was created without it, which meant `public_forum_comments_v`
-- ran as the view's OWNER rather than the querying role, silently bypassing
-- `public_forum_comments_read`'s ban-hiding (`not is_locked_out(author_phone)`)
-- — a banned author's comments were readable through the view the whole time,
-- caught by Supabase's own security advisor rather than by check_sql.sh.
create or replace view public.public_forum_comments_v
with (security_invoker = on) as
  select
    c.id,
    c.post_id,
    c.author_username,
    c.author_name,
    c.author_verified,
    c.body,
    c.gif_url,
    c.parent_id,
    c.created_at,
    public.public_forum_comment_score(c.id) as score
  from public.public_forum_comments c;

grant select on public.public_forum_comments_v to anon, authenticated;


-- ####################################################################
-- ## docs/community_notes.sql
-- ####################################################################
-- Community notes: reader-written fact-checks on public-feed posts, the way X's
-- Community Notes work. Anyone signed in may add a note giving context to a
-- post; anyone signed in may rate a note helpful or not; a note enough readers
-- find helpful is shown on the post (the client decides "shown" from the
-- tallies — see CommunityNote.isShown).
-- ============================================================================
-- Run ONCE in the Supabase SQL editor, AFTER docs/platform_moderation.sql and
-- docs/public_feed.sql — this references public.public_posts (the post a note
-- is about) and leans on public.is_locked_out() / public.is_silenced().
--
-- PLAINTEXT THE SERVER CAN READ, ON PURPOSE — the public-feed rule. A note on a
-- world-readable post has no key to seal under, and (like the feed itself) it is
-- server-moderated, so the text is public. What stays protected is the author's
-- and rater's phone number: clients are granted every column but the phone, and
-- attribution is by username, exactly as the public feed does it.
--
-- ORDER MATTERS: tables, then functions (bodies are parsed at creation, so the
-- tables they read must exist), then privileges and policies, then the view.

-- ---------------------------------------------------------------------------
-- 1. Tables
-- ---------------------------------------------------------------------------
create table if not exists public.community_notes (
  -- Client-generated, so a device recognises its own note coming back.
  id              text primary key,
  -- The post this note is about. Cascade so a deleted post takes its notes.
  post_id         text not null
                    references public.public_posts(id) on delete cascade,
  -- E.164 digits. Ownership only — never granted to a client role below.
  author_phone    text not null,
  author_username text not null default '',
  author_name     text not null default '',
  author_verified boolean not null default false,
  -- One to 280 characters of context. A note has to say something.
  body            text not null check (char_length(body) between 1 and 280),
  created_at      timestamptz not null default now()
);

-- One rating per person per note, changeable — like a forum vote, you can flip
-- helpful/not or take it back (update/delete on your own row, below).
create table if not exists public.community_note_ratings (
  note_id     text not null
                references public.community_notes(id) on delete cascade,
  rater_phone text not null,
  helpful     boolean not null,
  created_at  timestamptz not null default now(),
  primary key (note_id, rater_phone)
);

create index if not exists community_notes_post_idx
  on public.community_notes (post_id, created_at desc);
create index if not exists community_notes_author_idx
  on public.community_notes (author_phone);
create index if not exists community_note_ratings_note_idx
  on public.community_note_ratings (note_id);

alter table public.community_notes        enable row level security;
alter table public.community_note_ratings enable row level security;

-- ---------------------------------------------------------------------------
-- 2. Functions (the tables above have to exist first)
-- ---------------------------------------------------------------------------
-- Helpful / not-helpful tallies. SECURITY DEFINER because a rating row is
-- readable only by the person who cast it (the policy below), so counting as
-- the caller would see only your own rating — the same trick the feed's like
-- and poll counters use. Running as owner makes the totals true while who
-- rated stays private.
create or replace function public.community_note_helpful(n text)
returns bigint
language sql
stable
security definer
set search_path = public
as $$
  select count(*)::bigint
    from public.community_note_ratings where note_id = n and helpful;
$$;

create or replace function public.community_note_nothelpful(n text)
returns bigint
language sql
stable
security definer
set search_path = public
as $$
  select count(*)::bigint
    from public.community_note_ratings where note_id = n and not helpful;
$$;

-- ---------------------------------------------------------------------------
-- 3. Column privileges
-- ---------------------------------------------------------------------------
-- THE PHONE COLUMN, PROPERLY — Supabase grants every new table table-wide
-- SELECT, and Postgres can't carve a column out of that, so revoke the whole
-- grant and hand back the readable columns.
revoke select on table public.community_notes from anon, authenticated;
grant select (id, post_id, author_username, author_name, author_verified,
              body, created_at)
  on public.community_notes to anon, authenticated;

-- Your own rating comes back so the app can highlight the button you pressed;
-- rater_phone is never granted, and the policy shows you only your row.
revoke select on table public.community_note_ratings from anon, authenticated;
grant select (note_id, helpful, created_at)
  on public.community_note_ratings to authenticated;

-- Writing is by whole row; the policies decide whose row it may be.
grant insert, delete on public.community_notes to authenticated;
-- A rating can be changed or taken back.
grant insert, update, delete on public.community_note_ratings to authenticated;

-- No UPDATE on a note (append-only, like a forum post): an UPDATE matching no
-- policy affects zero rows without raising, which reads like success. Taking
-- the privilege away makes the refusal explicit.
revoke update on public.community_notes from anon, authenticated;

-- ---------------------------------------------------------------------------
-- 4. Policies (the functions above have to exist first)
-- ---------------------------------------------------------------------------
-- Readable by anyone with the app, except notes by a banned/suspended account.
drop policy if exists community_notes_read on public.community_notes;
create policy community_notes_read on public.community_notes
  for select to anon, authenticated
  using (not public.is_locked_out(author_phone));

-- Add a note only as yourself, and only while you are allowed to.
drop policy if exists community_notes_insert_own on public.community_notes;
create policy community_notes_insert_own on public.community_notes
  for insert to authenticated
  with check (
    author_phone = (auth.jwt() ->> 'phone')
    and not public.is_silenced(author_phone)
  );

drop policy if exists community_notes_delete_own on public.community_notes;
create policy community_notes_delete_own on public.community_notes
  for delete to authenticated
  using (author_phone = (auth.jwt() ->> 'phone'));

-- Ratings: see only your own, cast/change/take back only your own, and only
-- while allowed to interact.
drop policy if exists community_note_ratings_read_own
  on public.community_note_ratings;
create policy community_note_ratings_read_own on public.community_note_ratings
  for select to authenticated
  using (rater_phone = (auth.jwt() ->> 'phone'));

drop policy if exists community_note_ratings_insert_own
  on public.community_note_ratings;
create policy community_note_ratings_insert_own on public.community_note_ratings
  for insert to authenticated
  with check (
    rater_phone = (auth.jwt() ->> 'phone')
    and not public.is_silenced(rater_phone)
  );

drop policy if exists community_note_ratings_update_own
  on public.community_note_ratings;
create policy community_note_ratings_update_own on public.community_note_ratings
  for update to authenticated
  using (rater_phone = (auth.jwt() ->> 'phone'))
  with check (rater_phone = (auth.jwt() ->> 'phone'));

drop policy if exists community_note_ratings_delete_own
  on public.community_note_ratings;
create policy community_note_ratings_delete_own on public.community_note_ratings
  for delete to authenticated
  using (rater_phone = (auth.jwt() ->> 'phone'));

-- ---------------------------------------------------------------------------
-- 5. What clients actually read
-- ---------------------------------------------------------------------------
-- A view with no phone column in it at all. security_invoker keeps the caller's
-- RLS in force, which is what hides a banned author's notes.
drop view if exists public.community_notes_view;
create view public.community_notes_view
with (security_invoker = on) as
select
  n.id,
  n.post_id,
  n.author_username,
  n.author_name,
  n.author_verified,
  n.body,
  n.created_at,
  public.community_note_helpful(n.id)    as helpful_count,
  public.community_note_nothelpful(n.id) as not_helpful_count
from public.community_notes n;

grant select on public.community_notes_view to anon, authenticated;


-- ####################################################################
-- ## docs/public_market.sql
-- ####################################################################
-- The global marketplace: a world-readable table of for-sale listings that lives
-- OUTSIDE any server, so ANY user — including a brand-new account in no servers,
-- or someone who joined a server after an item was posted — can find them.
-- ============================================================================
-- Run ONCE in the Supabase SQL editor, AFTER docs/platform_moderation.sql —
-- this leans on public.is_locked_out() (to keep banned sellers' listings out)
-- and public.is_silenced() (to stop a timed-out account posting), both defined
-- there.
--
-- WHY THIS IS PLAINTEXT THE SERVER CAN READ, like the public feed and forum.
--
-- A marketplace listing is an ADVERTISEMENT: the seller wants strangers to find
-- it and buy. Its audience is everyone with the app, and a board whose audience
-- is everyone has no key to seal under — a public key is the same as no key. So
-- the rule here is the public feed's rule: what is posted to the marketplace is
-- public. Private messaging, chats, and a server's own sealed feed are all
-- untouched — this table is only ever fed the listing a seller chose to post.
--
-- Servers' own copies (community_posts, sealed under the community secret) still
-- exist for members; this GLOBAL table is what makes the marketplace visible to
-- people who are not in the seller's server.
--
-- What is still protected is the seller's PHONE NUMBER: clients are granted the
-- other columns and never that one, attribution and reach-out are by username
-- (already public in the directory, and how the app resolves a seller to message
-- or pay them), exactly as the public feed and forum do it.
--
-- ORDER MATTERS: the read policy calls is_locked_out(), which must already
-- exist. Tables, then privileges and policies, then the view.

-- ---------------------------------------------------------------------------
-- 1. Table
-- ---------------------------------------------------------------------------
create table if not exists public.market_listings (
  -- The listing's post id, client-generated, so a device recognises its own
  -- listing coming back and an edit upserts the same row.
  id              text primary key,
  -- E.164 digits. Ownership only — never granted to a client role below.
  author_phone    text not null,
  -- Public handle: how a buyer resolves the seller to message or pay them.
  author_username text not null default '',
  -- The full listing as the app's FeedPost JSON, with the phone stripped out
  -- before it ever leaves the device. Everything the marketplace renders — the
  -- price, photos, category, condition, place, attributes — is in here.
  payload         text not null,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);

create index if not exists market_listings_recent_idx
  on public.market_listings (updated_at desc);
create index if not exists market_listings_author_idx
  on public.market_listings (author_phone);

alter table public.market_listings enable row level security;

-- ---------------------------------------------------------------------------
-- 2. Column privileges
-- ---------------------------------------------------------------------------
-- THE PHONE COLUMN, PROPERLY — the same lesson as public_posts/public_forum.
-- Supabase grants these roles table-wide SELECT on every new table in public,
-- and Postgres cannot carve a column out of a table-wide grant, so `revoke
-- select (author_phone)` on its own changes nothing and leaves every seller's
-- number readable. Revoke the whole grant, then hand back the readable columns.
revoke select on table public.market_listings from anon, authenticated;
grant select (id, author_username, payload, created_at, updated_at)
  on public.market_listings to anon, authenticated;

-- Writing is by whole row; the policies decide whose row it may be. A listing
-- can be edited (price drop, sold flag) so UPDATE is granted, unlike the
-- append-only public feed.
grant insert, update, delete on public.market_listings to authenticated;

-- ---------------------------------------------------------------------------
-- 3. Policies
-- ---------------------------------------------------------------------------

-- Readable by anyone with the app — except listings by an account that is
-- banned or suspended, which leave the marketplace the moment the sanction
-- lands. This is what lets a brand-new (anon-key) account browse everything.
drop policy if exists market_listings_read on public.market_listings;
create policy market_listings_read on public.market_listings
  for select to anon, authenticated
  using (not public.is_locked_out(author_phone));

-- You may only post as yourself, and only while you are allowed to. The phone
-- comes from a JWT the client cannot forge, and a sanctioned account is refused
-- — so a modified client gains nothing.
drop policy if exists market_listings_insert_own on public.market_listings;
create policy market_listings_insert_own on public.market_listings
  for insert to authenticated
  with check (
    author_phone = (auth.jwt() ->> 'phone')
    and not public.is_silenced(author_phone)
  );

-- Editing a listing (price, sold) is an UPDATE of your own row only.
drop policy if exists market_listings_update_own on public.market_listings;
create policy market_listings_update_own on public.market_listings
  for update to authenticated
  using (author_phone = (auth.jwt() ->> 'phone'))
  with check (author_phone = (auth.jwt() ->> 'phone'));

drop policy if exists market_listings_delete_own on public.market_listings;
create policy market_listings_delete_own on public.market_listings
  for delete to authenticated
  using (author_phone = (auth.jwt() ->> 'phone'));

-- ---------------------------------------------------------------------------
-- 4. What clients actually read
-- ---------------------------------------------------------------------------
-- A view with no phone column in it at all, so the ordinary path cannot leak
-- one even by accident. security_invoker keeps the caller's RLS in force, which
-- is what hides a banned seller's listings.
drop view if exists public.market_listings_view;
create view public.market_listings_view
with (security_invoker = on) as
select
  m.id,
  m.author_username,
  m.payload,
  m.created_at,
  m.updated_at
from public.market_listings m;

grant select on public.market_listings_view to anon, authenticated;


-- ####################################################################
-- ## docs/market_reviews.sql
-- ####################################################################
-- Marketplace reviews, world-readable like the listings they attach to.
-- ============================================================================
-- Run ONCE in the Supabase SQL editor, AFTER docs/platform_moderation.sql
-- (is_locked_out/is_silenced) and docs/public_market.sql (the listing this
-- table's rows attach to — no foreign key enforced, since a review must
-- still exist even against a listing this device's own copy already
-- deleted).
--
-- WHY GLOBAL, LIKE LISTINGS. A review is an opinion about something
-- world-readable — the same public_feed/public_market rule applies: its
-- audience is everyone browsing the listing, so it has no key to seal
-- under. Same table shape as market_listings, on purpose, right down to
-- the phone-hiding trick.
--
-- THE BUG THIS FIXES. FeedStore.addReview built a review as a FeedPost
-- carrying `communityId: listing.communityId` — inherited from the
-- listing it reviews. Since the marketplace went global (2026-08-08), a
-- normal listing's communityId is '' (global-only), and
-- RelayService.sendFeedPost's dispatch had NO branch for a review: it is
-- not a listing (so it skips the market_listings publish), its communityId
-- resolves to no real Community (so it skips the sealed community bus),
-- and `if (post.communityId.isEmpty) return;` drops it on the floor. A
-- review only ever existed on the reviewer's own device — nobody else,
-- least of all the seller, ever saw it or was told about it.

create table if not exists public.market_reviews (
  -- The review's post id, client-generated (mirrors market_listings).
  id              text primary key,
  -- The listing being reviewed — FeedPost.parentId. Not a foreign key: a
  -- review must survive even against a listing already gone from this
  -- table (deleted, or never published because it predates this file).
  listing_id      text not null,
  -- E.164 digits. Ownership only — never granted to a client role below.
  author_phone    text not null,
  -- Public handle: how a reader knows who wrote it.
  author_username text not null default '',
  -- The whole review as the app's FeedPost JSON (rating, text,
  -- confirmedPurchase, authorVerified…), with the phone stripped before it
  -- ever leaves the device — same shape as a listing's payload.
  payload         text not null,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);

create index if not exists market_reviews_listing_idx
  on public.market_reviews (listing_id, created_at desc);
create index if not exists market_reviews_author_idx
  on public.market_reviews (author_phone);

alter table public.market_reviews enable row level security;

-- ---------------------------------------------------------------------------
-- Column privileges — the same table-wide-grant trap market_listings and
-- public_posts already learned from: Supabase grants every new public table
-- SELECT to anon/authenticated by default, and `revoke select (col)` alone
-- changes nothing against a table-wide grant. Revoke everything, then hand
-- back only the columns that don't carry a phone.
-- ---------------------------------------------------------------------------
revoke select on table public.market_reviews from anon, authenticated;
grant select (id, listing_id, author_username, payload, created_at, updated_at)
  on public.market_reviews to anon, authenticated;

grant insert, update, delete on public.market_reviews to authenticated;

-- ---------------------------------------------------------------------------
-- Policies
-- ---------------------------------------------------------------------------

-- Readable by anyone with the app — except a review by an account that is
-- banned or suspended, which leaves the marketplace the moment the sanction
-- lands, same as a listing does.
drop policy if exists market_reviews_read on public.market_reviews;
create policy market_reviews_read on public.market_reviews
  for select to anon, authenticated
  using (not public.is_locked_out(author_phone));

-- You may only review as yourself, and only while you are allowed to post.
-- The phone comes from a JWT the client cannot forge.
drop policy if exists market_reviews_insert_own on public.market_reviews;
create policy market_reviews_insert_own on public.market_reviews
  for insert to authenticated
  with check (
    author_phone = (auth.jwt() ->> 'phone')
    and not public.is_silenced(author_phone)
  );

-- addReview rewrites a review by deleting the old one and posting a new id
-- in its place, so UPDATE isn't exercised by the client today — granted
-- anyway, own-row-only, so it isn't a silent gap if that ever changes.
drop policy if exists market_reviews_update_own on public.market_reviews;
create policy market_reviews_update_own on public.market_reviews
  for update to authenticated
  using (author_phone = (auth.jwt() ->> 'phone'))
  with check (author_phone = (auth.jwt() ->> 'phone'));

drop policy if exists market_reviews_delete_own on public.market_reviews;
create policy market_reviews_delete_own on public.market_reviews
  for delete to authenticated
  using (author_phone = (auth.jwt() ->> 'phone'));

-- ---------------------------------------------------------------------------
-- What clients actually read: a view with no phone column at all, so the
-- ordinary path cannot leak one even by accident. security_invoker keeps the
-- caller's own RLS in force, which is what hides a banned author's reviews.
-- ---------------------------------------------------------------------------
drop view if exists public.market_reviews_view;
create view public.market_reviews_view
with (security_invoker = on) as
select
  r.id,
  r.listing_id,
  r.author_username,
  r.payload,
  r.created_at,
  r.updated_at
from public.market_reviews r;

grant select on public.market_reviews_view to anon, authenticated;


-- ####################################################################
-- ## docs/paid_servers.sql
-- ####################################################################
-- Paid servers (2026-08-06). The membership half of creator subscriptions:
-- who has paid to be in a paid server, verified from a store receipt.
--
-- A paid server's traffic is already END-TO-END SEALED under its own secret,
-- so this is NOT access-control over readable content — the server never sees
-- or stores a message. It records who holds an active membership pass, so the
-- join can be gated and (the hardening follow-up) the owner's device can
-- release the secret only to a verified-paid joiner.
--
-- `community_passes` is written ONLY by the `community-subscribe` Edge Function
-- (service role), after it verifies the Apple receipt. There are NO client
-- grants on the tables at all; the definer functions below are the only doors,
-- and none of them ever returns a phone number.
--
-- Run this in the Supabase SQL editor, then paste the `community-subscribe`
-- function. Until then paid servers run in test/simulation only (the client's
-- local pass drives the demo).
-- ---------------------------------------------------------------------------

-- Both ends stay off the client. subscriber_phone is the payer; server_id is
-- the community id. last_txn_id dedupes a receipt so one purchase grants one
-- month. Keyed by (subscriber, server): one live pass per server per account.
create table if not exists public.community_passes (
  subscriber_phone text not null,
  server_id        text not null,
  expires_at       timestamptz not null,
  product_id       text not null default '',
  last_txn_id      text not null default '',
  updated_at       timestamptz not null default now(),
  primary key (subscriber_phone, server_id)
);

alter table public.community_passes enable row level security;
revoke all on table public.community_passes from anon, authenticated;

-- One row per consumed receipt, so the same signed transaction can't be
-- replayed to buy membership of a dozen servers.
create table if not exists public.community_sub_receipts (
  txn_id     text primary key,
  created_at timestamptz not null default now()
);
alter table public.community_sub_receipts enable row level security;
revoke all on table public.community_sub_receipts from anon, authenticated;

-- ---------------------------------------------------------------------------
-- Read gates (security definer — the only doors). A client can ask about its
-- OWN passes; it can never grant itself one or read anybody else's.
-- ---------------------------------------------------------------------------

-- Whether the caller holds an active membership pass to [s] (a server id).
create or replace function public.community_pass_active(s text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
      from public.community_passes p
     where p.subscriber_phone = (auth.jwt() ->> 'phone')
       and p.server_id = s
       and p.expires_at > now()
  );
$$;

-- The caller's own active passes — server id + expiry — for reconciling the
-- local list on start. Only ever your own rows; no phone ever returned.
create or replace function public.community_my_passes()
returns table(server_id text, expires_at timestamptz)
language sql
stable
security definer
set search_path = public
as $$
  select p.server_id, p.expires_at
    from public.community_passes p
   where p.subscriber_phone = (auth.jwt() ->> 'phone')
     and p.expires_at > now();
$$;

grant execute on function public.community_pass_active(text) to authenticated;
grant execute on function public.community_my_passes() to authenticated;


-- ####################################################################
-- ## docs/banned_signups.sql
-- ####################################################################
-- Keeping a banned user's NUMBER and EMAIL from coming back.
-- ============================================================================
-- Run ONCE in the Supabase SQL editor, AFTER docs/platform_moderation.sql
-- (this leans on account_sanctions and platform_roles).
--
-- Two identifiers, two mechanisms:
--
--   * PHONE — a ban already lives in account_sanctions (kind 'ban'/'suspend').
--     is_phone_banned() is the canonicalizing lookup the signup path calls, so
--     a banned number is refused at the door instead of only being locked out
--     after it signs in. It canonicalizes both sides (the directory stores
--     E.164, a client passes digits) — the same '+' vs digits trap the follow
--     and admin lookups already learned.
--
--   * EMAIL — there is NO server column that maps an email to an account (a
--     verified email lives only inside the user's ENCRYPTED backup blob), so a
--     phone-ban cannot capture the email automatically. Instead an owner/admin
--     bans an email explicitly with ban_email(); the signup / email-set path
--     refuses anything on the list. The list is reachable only through the
--     definer functions — never enumerable by a client.

create table if not exists public.banned_emails (
  email       text primary key,          -- lowercased, trimmed
  actor_phone text not null default '',  -- who banned it (digits)
  reason      text not null default '',
  created_at  timestamptz not null default now()
);
alter table public.banned_emails enable row level security;
-- No client policy and no grants: the only doors are the definer functions
-- below. A raw list of banned emails is not something a client should read.
revoke all on table public.banned_emails from anon, authenticated;

-- Is this phone under an active ban or suspension? (A timeout is not a signup
-- ban — it lifts by itself.)
create or replace function public.is_phone_banned(p text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists(
    select 1 from public.account_sanctions s
     where regexp_replace(s.phone, '\D', '', 'g')
             = regexp_replace(p, '\D', '', 'g')
       and s.kind in ('ban', 'suspend')
       and (s.until is null or s.until > now()));
$$;
grant execute on function public.is_phone_banned(text) to anon, authenticated;

-- Is this email on the banned list?
create or replace function public.is_email_banned(e text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists(select 1 from public.banned_emails
                 where email = lower(trim(e)));
$$;
grant execute on function public.is_email_banned(text) to anon, authenticated;

-- Owner/admin only: add an email to the banned list. The caller is proven by
-- the JWT phone in platform_roles (canonicalized), the same gate the admin
-- roster uses. Returns false (changes nothing) for anyone else.
create or replace function public.ban_email(e text, reason text default '')
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare ph text; ok boolean;
begin
  ph := regexp_replace(coalesce(auth.jwt() ->> 'phone', ''), '\D', '', 'g');
  if ph = '' or lower(trim(e)) = '' then return false; end if;
  select exists(
    select 1 from public.platform_roles r
     where regexp_replace(r.phone, '\D', '', 'g') = ph
       and r.role in ('owner', 'admin')) into ok;
  if not ok then return false; end if;
  insert into public.banned_emails (email, actor_phone, reason)
    values (lower(trim(e)), ph, reason)
    on conflict (email) do nothing;
  return true;
end $$;
grant execute on function public.ban_email(text, text) to authenticated;

-- Owner/admin only: lift an email ban.
create or replace function public.unban_email(e text)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare ph text; ok boolean;
begin
  ph := regexp_replace(coalesce(auth.jwt() ->> 'phone', ''), '\D', '', 'g');
  select exists(
    select 1 from public.platform_roles r
     where regexp_replace(r.phone, '\D', '', 'g') = ph
       and r.role in ('owner', 'admin')) into ok;
  if not ok then return false; end if;
  delete from public.banned_emails where email = lower(trim(e));
  return true;
end $$;
grant execute on function public.unban_email(text) to authenticated;


-- ####################################################################
-- ## docs/public_servers.sql
-- ####################################################################
-- The Discover directory: a world-readable table of PUBLIC servers, so anyone
-- with the app can find a server and join it without an invite. This is the
-- "public vs private server" split — a private server stays invite-only (it is
-- simply never listed here); a public server publishes a row anybody can browse.
-- ============================================================================
-- Run ONCE in the Supabase SQL editor, AFTER docs/platform_moderation.sql —
-- this leans on public.is_locked_out() (to keep a banned owner's server out of
-- the directory) and public.is_silenced() (to stop a timed-out account listing
-- one), both defined there.
--
-- WHY THE JOIN SECRET IS WORLD-READABLE HERE, ON PURPOSE.
--
-- A server's traffic is E2E sealed under its `secret`, and the invite is what
-- hands that secret to a joiner. A PUBLIC server is one whose owner has decided
-- anyone may join — which is the same decision as "anyone may hold the key".
-- So the directory row carries the full invite snapshot (the same JSON a tapped
-- invite card carries, secret included): a browser joins by decoding it, exactly
-- as if someone had handed them the invite. That is the deliberate trade a
-- public server makes, and the in-app toggle says so before it is flipped.
--
-- Private servers, 1:1 chats, and a server's own sealed feed are all untouched —
-- this table is only ever fed a server whose owner chose to list it. A PAID
-- server is never listed (its secret must not be free); the client refuses to
-- publish one and the payload check below is the backstop.
--
-- What is still protected is the OWNER'S PHONE NUMBER: clients are granted every
-- column but that one, and reach-out/ownership is by the username already inside
-- the payload — exactly as the public feed, forum and marketplace do it.
--
-- ORDER MATTERS: the read policy calls is_locked_out(), which must already
-- exist. Tables, then privileges and policies, then the view.

-- ---------------------------------------------------------------------------
-- 1. Table
-- ---------------------------------------------------------------------------
create table if not exists public.server_directory (
  -- The server's id, so the owner's device recognises its own row and a
  -- re-list upserts the same one.
  id            text primary key,
  -- E.164 digits of the owner. Ownership only — never granted to a client role.
  owner_phone   text not null,
  -- Denormalized display fields, so the browse list renders without decoding
  -- every payload. Kept in step by the client on each publish.
  name          text not null default '',
  description   text not null default '',
  member_count  int  not null default 0,
  -- The full invite snapshot as JSON (CommunityStore.exportInvite), secret
  -- included — this is what a browser decodes to join. Never carries a phone.
  payload       text not null,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

create index if not exists server_directory_recent_idx
  on public.server_directory (updated_at desc);
create index if not exists server_directory_owner_idx
  on public.server_directory (owner_phone);

alter table public.server_directory enable row level security;

-- ---------------------------------------------------------------------------
-- 2. Column privileges
-- ---------------------------------------------------------------------------
-- THE PHONE COLUMN, PROPERLY — the same lesson as public_posts/market_listings.
-- Supabase grants these roles table-wide SELECT on every new table in public,
-- and Postgres cannot carve a column out of a table-wide grant, so `revoke
-- select (owner_phone)` on its own would change nothing. Revoke the whole
-- grant, then hand back the readable columns.
revoke select on table public.server_directory from anon, authenticated;
grant select (id, name, description, member_count, payload, created_at, updated_at)
  on public.server_directory to anon, authenticated;

-- Writing is by whole row; the policies decide whose row it may be. A listed
-- server's member count changes, so UPDATE is granted.
grant insert, update, delete on public.server_directory to authenticated;

-- ---------------------------------------------------------------------------
-- 3. Policies
-- ---------------------------------------------------------------------------

-- Readable by anyone with the app — except a server whose owner is banned or
-- suspended, which leaves the directory the moment the sanction lands. This is
-- what lets a brand-new (anon-key) account browse everything.
drop policy if exists server_directory_read on public.server_directory;
create policy server_directory_read on public.server_directory
  for select to anon, authenticated
  using (not public.is_locked_out(owner_phone));

-- You may only list a server as yourself, and only while you are allowed to.
-- The phone comes from a JWT the client cannot forge, and a sanctioned account
-- is refused — so a modified client gains nothing.
drop policy if exists server_directory_insert_own on public.server_directory;
create policy server_directory_insert_own on public.server_directory
  for insert to authenticated
  with check (
    owner_phone = (auth.jwt() ->> 'phone')
    and not public.is_silenced(owner_phone)
  );

-- Updating the row (member count, a settings change) is your own row only.
drop policy if exists server_directory_update_own on public.server_directory;
create policy server_directory_update_own on public.server_directory
  for update to authenticated
  using (owner_phone = (auth.jwt() ->> 'phone'))
  with check (owner_phone = (auth.jwt() ->> 'phone'));

-- Unlisting (going private, deleting the server) is a delete of your own row.
drop policy if exists server_directory_delete_own on public.server_directory;
create policy server_directory_delete_own on public.server_directory
  for delete to authenticated
  using (owner_phone = (auth.jwt() ->> 'phone'));

-- ---------------------------------------------------------------------------
-- 4. What clients actually read
-- ---------------------------------------------------------------------------
-- A view with no phone column in it at all, so the ordinary path cannot leak
-- one even by accident. security_invoker keeps the caller's RLS in force, which
-- is what hides a banned owner's server.
drop view if exists public.server_directory_view;
create view public.server_directory_view
with (security_invoker = on) as
select
  d.id,
  d.name,
  d.description,
  d.member_count,
  d.payload,
  d.created_at,
  d.updated_at
from public.server_directory d;

grant select on public.server_directory_view to anon, authenticated;


-- ####################################################################
-- ## docs/market_upsert_fix.sql
-- ####################################################################
-- Publishing a marketplace listing (or a review) was refused outright, and the
-- phone-hiding column grant was the reason.
-- ============================================================================
-- Run ONCE in the Supabase SQL editor, AFTER docs/public_market.sql and
-- docs/market_reviews.sql (it alters columns those two create).
--
-- THE BUG, exactly. Both tables deliberately withhold the author's phone from
-- clients: the table-wide SELECT is revoked and every column BUT author_phone
-- is granted back, so a seller's number can never be read by a browser. That
-- part was correct and stays.
--
-- What nobody checked is what the app actually SENDS. It publishes with
-- PostgREST's upsert, which becomes:
--
--   insert into market_listings (id, author_phone, author_username, payload, …)
--   values (…)
--   on conflict (id) do update set
--     author_phone    = excluded.author_phone,   -- <<< this line
--     author_username = excluded.author_username,
--     …
--
-- `excluded.author_phone` is a READ of the withheld column. Postgres checks
-- that at PLAN time — before any row exists, so it fails even on a brand-new
-- listing that could never conflict — and refuses the whole statement with
-- `42501 permission denied for table market_listings`, hinting at exactly the
-- table-wide SELECT grant that must never be given here. Every single publish
-- has been failing this way; the table has never held a row.
--
-- Confirmed live rather than reasoned about: the same upsert with
-- `author_phone` REMOVED from the DO UPDATE list succeeds, and with it present
-- fails, on both tables.
--
-- WHY NOT JUST GRANT SELECT ON THE COLUMN. That is what fixed the same class
-- of bug on public_forum_votes (see the note in CLAUDE.md), and it was safe
-- THERE because that table's read policy is scoped to the caller's own row —
-- the only number the column could hand back was one the caller already knew.
-- Here the read policy is `content_visible(author_phone)`: every listing is
-- world-readable by design, so granting the column would publish every
-- seller's phone number to anyone holding the publishable key. Not an option.
--
-- THE FIX: the client stops sending author_phone at all, and the column fills
-- itself from the caller's own JWT. Then the DO UPDATE never names the column,
-- so nothing reads it and no SELECT is required.
--
-- This is strictly SAFER than what it replaces, not merely equivalent:
--   * A fresh row takes the phone from `auth.jwt() ->> 'phone'`, which a
--     client cannot forge — it is no longer trusting a value the device sent.
--   * An UPDATE never touches author_phone, so a listing's owner can never be
--     reassigned by a later publish.
--   * The insert policy (`author_phone = auth.jwt() ->> 'phone'`) is unchanged
--     and still runs, so an older build that DOES send the column is refused
--     if it names somebody else's number — verified, still errors with
--     "new row violates row-level security policy".
--   * anon has no session, so the default is null and NOT NULL refuses the
--     row — a signed-out write cannot land even if RLS were ever loosened.

-- ---------------------------------------------------------------------------
-- 1. market_listings
-- ---------------------------------------------------------------------------
alter table public.market_listings
  alter column author_phone set default (auth.jwt() ->> 'phone');

-- ---------------------------------------------------------------------------
-- 2. market_reviews — the identical shape, and the identical bug
-- ---------------------------------------------------------------------------
alter table public.market_reviews
  alter column author_phone set default (auth.jwt() ->> 'phone');

-- ---------------------------------------------------------------------------
-- 3. server_directory — the SAME bug, found only because it was re-checked
-- ---------------------------------------------------------------------------
-- This file first claimed server_directory was fine. It is not, and the way
-- that mistake happened is worth recording: the first probe upserted it
-- WITHOUT owner_phone in the DO UPDATE list, which of course succeeded, and
-- that was read as "this table is unaffected". What the app actually sends
-- (`publishServerDirectory`) DOES name owner_phone — so publishing a public
-- server to the Discover directory was refused with the identical
-- `permission denied for table server_directory`, and a server toggled public
-- never appeared for anyone.
--
-- Test the statement the CLIENT really sends, not a simplified stand-in.
alter table public.server_directory
  alter column owner_phone set default (auth.jwt() ->> 'phone');


-- ####################################################################
-- ## docs/community_structure.sql
-- ####################################################################
-- Server-authoritative community structure (2026-08-13): a durable, RLS-scoped
-- copy of a server's identity, channel list, roster, and custom roles.
--
-- WHY THIS EXISTS. Until now a "server" had no server-side authority at all —
-- CommunityStore was pure local state, and every structural change (rename,
-- add a channel, change a role, remove a member, ban someone) was a full
-- re-serialization of the WHOLE community broadcast + mailboxed to every other
-- member, who unconditionally overwrote their local copy from whatever arrived
-- last. There was no conflict resolution and — the part worth saying plainly —
-- no server-side permission check at all: a modified client could forge any
-- structural change today and nothing would object.
--
-- This file is a CACHE-COHERENCE BACKSTOP layered on top of that gossip
-- protocol, not a replacement for it. Every existing broadcast/mailbox/mesh
-- path (chupd, chjoin, applyRemoteStructure, sendServerJoin, rotateServerKey,
-- the sender-key handshake) stays completely untouched, and keeps being the
-- ONLY path for a fully offline device or one reachable only over Bluetooth
-- mesh — that is not a migration-window limitation, it is the permanent,
-- correct shape for a local-first app. What this buys: a device that opens
-- the app can pull the current, permission-checked truth in one read instead
-- of trusting whatever the last full-snapshot broadcast happened to say, and
-- — for the first time — a real server-side check that a structural change
-- actually came from someone allowed to make it.
--
-- WHAT STAYS EXACTLY AS TODAY: message and channel-message CONTENT. chmsg,
-- chdel, chedt, chrxn, chpin, and every forum event are untouched — still
-- end-to-end sealed under the server's Signal-style sender key, still
-- peer-relayed. Nothing in this file can read a message body, and the
-- sender-key rotation that locks a removed member out of future content
-- (SenderKeyStore.rotate / RelayService.rotateServerKey) is unaffected by
-- where roster AUTHORITY lives — it stays a client-observed, client-triggered
-- event, same as today.
--
-- THE SECRET IS NEVER STORED HERE, ONLY ITS HASH. A public (listed) server's
-- secret already lives in the clear in `server_directory` (docs/public_servers.sql)
-- — that is the deliberate trade "anyone may join" already makes. A PRIVATE
-- server has never had a durable server-side home for its content-decryption
-- key, and this file does not give it one: `community_servers.secret_hash` is
-- sha256(secret), computed CLIENT-SIDE (AccountService.phoneHashHex's own
-- pattern, package:crypto), and the join RPC below only ever compares hashes.
-- A single RLS misconfiguration or compromised service-role credential can
-- never expose a private server's content key through this table.
--
-- A NEW RLS SHAPE FOR THIS CODEBASE. Every other table's read policy here is
-- either world-readable-minus-sanctioned or owner-only. Real membership needs
-- a third shape — "readable only by the N actual members of server X" — so
-- this file adds the first is_community_member()-style predicate, modeled on
-- community_pass_active()'s existing style (docs/paid_servers.sql).
--
-- JOIN IS AN RPC, NOT A PERMISSIVE INSERT POLICY, ON PURPOSE. Community.id is
-- 'c_${name.hashCode}_${count}' (lib/state/community_store.dart) — low-entropy
-- and guessable. A plain insert policy would let a stranger enumerate ids and
-- add themselves to a roster without ever holding an invite. The RPC compares
-- the caller-supplied hash against the stored one and silently no-ops on any
-- mismatch, exactly like every other RPC in this codebase that guards a real
-- secret (community_pass_active, the moderation functions).
--
-- PAID-SERVER JOIN NOW ENFORCED SERVER-SIDE — a real tightening, confirmed
-- with the owner. Today `joinFromInvite` performs NO payment check at all;
-- the paywall is a UI convention the app is trusted to have already applied.
-- The join RPC reuses the existing `community_pass_active()` (docs/paid_servers.sql)
-- so a leaked invite for a paid server can no longer register a holder as an
-- authoritative member without an active pass. This does not change the
-- underlying crypto exposure — anyone holding the secret can still decrypt
-- content regardless of payment, same as today — it only tightens who is
-- listed as a roster member.
--
-- NUMBERLESS ACCOUNTS ARE NOT REACHED BY THIS FILE. Every policy/helper below
-- is phone-JWT-based (auth.jwt() ->> 'phone'), and a numberless account has no
-- Supabase session to carry one (see docs/directory_numberless.sql). Such an
-- account transparently keeps using legacy peer-broadcast membership for
-- every community it's in, indefinitely — stated here rather than discovered
-- later. Closing that gap is its own follow-up, not this file's scope.
--
-- MIGRATION: NOTHING IS REQUIRED, EVERYTHING IS OPPORTUNISTIC. An existing
-- (legacy, local-only) server needs no manual recreation: the owner's device
-- upserts it here on its very next structural change (and, going forward,
-- once per relay start for every server it owns); every member's device
-- idempotently re-registers itself once per relay start for every community
-- it is already locally in (community_join's `on conflict do nothing` makes
-- that safe to call repeatedly). A community whose owner never opens the app
-- again simply never gets a row here and keeps working exactly as it does
-- today, forever.
--
-- Run ONCE in the Supabase SQL editor, AFTER docs/platform_moderation.sql
-- (is_locked_out/is_silenced), docs/public_feed.sql (is_silenced is actually
-- defined there), and docs/paid_servers.sql (community_pass_active). Safe to
-- re-run: every statement is idempotent.

-- ---------------------------------------------------------------------------
-- 1. Tables
-- ---------------------------------------------------------------------------
create table if not exists public.community_servers (
  id            text primary key,               -- matches Community.id
  owner_phone   text not null,
  -- sha256(secret) hex, client-computed. NEVER the raw secret — see the file
  -- header. Withheld from every client grant below on top of that.
  secret_hash   text not null,
  name          text not null default '',
  color         text not null default '#7A5CFF',
  color2        text not null default '',
  icon          text not null default '',
  description   text not null default '',
  slow_mode_seconds int not null default 0,
  members_can_create_channels boolean not null default true,
  members_can_post boolean not null default true,
  members_can_message boolean not null default true,
  invite_policy text not null default 'everyone',
  banned_words  text[] not null default '{}',
  paid          boolean not null default false,
  price_cents   int not null default 0,
  sub_pitch     text not null default '',
  updated_at    timestamptz not null default now(),
  created_at    timestamptz not null default now()
);

create table if not exists public.community_members (
  community_id text not null
                 references public.community_servers(id) on delete cascade,
  member_phone text not null,
  role         text not null default 'member'
                 check (role in ('owner', 'admin', 'moderator', 'member')),
  role_id      text not null default '',       -- CustomRole.id, or '' for none
  joined_at    timestamptz not null default now(),
  primary key (community_id, member_phone)
);

create table if not exists public.community_channels (
  id           text primary key,
  community_id text not null
                 references public.community_servers(id) on delete cascade,
  name         text not null default '',
  type         text not null default 'text',
  category     text not null default '',
  topic        text not null default '',
  position     int not null default 0,
  updated_at   timestamptz not null default now()
);

create table if not exists public.community_roles (
  id           text primary key,
  community_id text not null
                 references public.community_servers(id) on delete cascade,
  name         text not null default '',
  color        text not null default '#17708A',
  -- Never 'owner' — a role can lift at most to admin, mirroring
  -- CustomRole.tier's own clamp in lib/models/community.dart.
  tier         text not null default 'member'
                 check (tier in ('admin', 'moderator', 'member')),
  badge        text not null default ''
);

create table if not exists public.community_bans (
  community_id text not null
                 references public.community_servers(id) on delete cascade,
  member_phone text not null,
  member_name  text not null default '',
  banned_at    timestamptz not null default now(),
  primary key (community_id, member_phone)
);

create index if not exists community_members_phone_idx
  on public.community_members (member_phone);
create index if not exists community_channels_community_idx
  on public.community_channels (community_id);
create index if not exists community_roles_community_idx
  on public.community_roles (community_id);

alter table public.community_servers  enable row level security;
alter table public.community_members  enable row level security;
alter table public.community_channels enable row level security;
alter table public.community_roles    enable row level security;
alter table public.community_bans     enable row level security;

-- ---------------------------------------------------------------------------
-- 2. Functions (the tables above have to exist first)
-- ---------------------------------------------------------------------------

-- owner=3 / admin=2 / moderator=1 / member=0 — matches roleRank in
-- lib/models/community.dart exactly.
create or replace function public.community_role_rank(r text)
returns int
language sql
immutable
as $$
  select case r
    when 'owner' then 3
    when 'admin' then 2
    when 'moderator' then 1
    else 0
  end;
$$;

-- The core new predicate — every table's read policy below is built on this.
create or replace function public.is_community_member(cid text, p text default null)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.community_members m
     where m.community_id = cid
       and m.member_phone = coalesce(p, auth.jwt() ->> 'phone')
  );
$$;

-- The higher of a member's built-in role and their custom role's tier —
-- mirrors Community.effectiveRole in lib/models/community.dart exactly,
-- including that a role can never lift someone past admin.
create or replace function public.community_effective_role(cid text, p text default null)
returns text
language sql
stable
security definer
set search_path = public
as $$
  select case greatest(
      public.community_role_rank(m.role),
      public.community_role_rank(coalesce(r.tier, 'member'))
    )
    when 3 then 'owner'
    when 2 then 'admin'
    when 1 then 'moderator'
    else 'member'
  end
  from public.community_members m
  left join public.community_roles r
    on r.id = m.role_id and r.community_id = m.community_id
  where m.community_id = cid
    and m.member_phone = coalesce(p, auth.jwt() ->> 'phone');
$$;

-- Owners and admins only — matches CommunityStore.canManageServer.
create or replace function public.can_manage_community(cid text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.community_role_rank(
    coalesce(public.community_effective_role(cid), 'member')) >= 2;
$$;

-- Moderators and above — matches CommunityStore.canModerate.
create or replace function public.can_moderate_community(cid text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.community_role_rank(
    coalesce(public.community_effective_role(cid), 'member')) >= 1;
$$;

-- Matches CommunityStore.canCreateChannels: a moderator+ always may; an
-- ordinary member may only while the server's own setting allows it.
create or replace function public.can_create_channel(cid text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.can_moderate_community(cid)
    or coalesce(
      (select s.members_can_create_channels
         from public.community_servers s where s.id = cid),
      true);
$$;

-- THE JOIN GATE. Silently no-ops on any failure — a wrong secret, a ban, an
-- unpaid pass, a locked-out account — exactly like every other RPC here that
-- guards a real secret, rather than distinguishing failure reasons to a
-- caller who might be an attacker probing which one applied.
create or replace function public.community_join(cid text, secret_hash text, my_name text)
returns void
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  me  text := (auth.jwt() ->> 'phone');
  row record;
begin
  if me is null or public.is_locked_out(me) then return; end if;
  select * into row from public.community_servers where id = cid;
  if row is null then return; end if;
  if row.secret_hash <> secret_hash then return; end if;
  if exists (
    select 1 from public.community_bans b
     where b.community_id = cid and b.member_phone = me
  ) then return; end if;
  if row.paid and not public.community_pass_active(cid) then return; end if;
  -- ON CONFLICT DO NOTHING is also what makes this safe to call
  -- OPPORTUNISTICALLY on every relay start for a community already joined
  -- locally — see the migration note in the file header.
  insert into public.community_members (community_id, member_phone, role)
  values (cid, me, 'member')
  on conflict (community_id, member_phone) do nothing;
end;
$$;

grant execute on function public.community_join(text, text, text) to authenticated;

-- THE OWNER'S BOOTSTRAP. community_members_insert (below) is deliberately
-- admin-only, which is correct for every OTHER insert but creates a genuine
-- chicken-and-egg problem for the very first row: can_manage_community reads
-- community_effective_role, which reads community_members itself — before the
-- owner has a row there, effective role resolves to nothing and the insert
-- policy refuses even the real owner. A trigger, not a policy branch, is the
-- fix: seeding the owner's own 'owner' row is a direct, mechanical consequence
-- of the community_servers row existing at all, not something that needs its
-- own client-facing insert path (which would just reopen a version of the
-- same self-insert hole the members policy exists to close). Runs as definer,
-- so it bypasses community_members' RLS entirely for this one seed insert;
-- ON CONFLICT DO NOTHING makes it safe on every opportunistic republish too.
create or replace function public.community_servers_seed_owner()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.community_members (community_id, member_phone, role)
  values (new.id, new.owner_phone, 'owner')
  on conflict (community_id, member_phone) do nothing;
  return new;
end;
$$;

drop trigger if exists community_servers_seed_owner_trigger on public.community_servers;
create trigger community_servers_seed_owner_trigger
  after insert on public.community_servers
  for each row execute function public.community_servers_seed_owner();

-- ---------------------------------------------------------------------------
-- 3. Column privileges
-- ---------------------------------------------------------------------------
-- Unlike most tables in this codebase there is no phone-hiding dance for most
-- columns here — the whole point is that real members see the real roster (a
-- member's own wire-id digits are already visible to every other member
-- locally today). The one column withheld is secret_hash: clients never need
-- to read it directly, only the join RPC (running as definer) compares it.
revoke select on table public.community_servers from anon, authenticated;
grant select (id, owner_phone, name, color, color2, icon, description,
              slow_mode_seconds, members_can_create_channels, members_can_post,
              members_can_message, invite_policy, banned_words, paid,
              price_cents, sub_pitch, updated_at, created_at)
  on public.community_servers to authenticated;
grant insert, update, delete on public.community_servers to authenticated;

-- No anon grant anywhere in this file: private structure should never be
-- reachable on the anon key even in principle. A numberless/no-session
-- device has no path here at all — see the file header.
grant select, insert, update, delete on public.community_members  to authenticated;
grant select, insert, update, delete on public.community_channels to authenticated;
grant select, insert, update, delete on public.community_roles    to authenticated;
grant select, insert, delete         on public.community_bans     to authenticated;

-- REVOKE ANON EXPLICITLY, ON EVERY TABLE — the same lesson this codebase
-- already learned once (find_people_by_hashes, docs/directory_phone_privacy.sql):
-- a live Supabase project grants table-wide privileges to `anon` (and
-- `authenticated`) on every NEW table by default, and `revoke ... from public`
-- does not take that away — the role has to be named. Found live on this
-- exact file: `community_servers` was correctly revoked above (the select had
-- a sensitive column to protect), but community_members/_channels/_roles/_bans
-- had no revoke at all, so anon quietly held full SELECT/INSERT/UPDATE/DELETE
-- on all four the moment they were created — RLS still blocked every one of
-- them in practice (every policy in this file is scoped `to authenticated`
-- only, so no policy ever matches an anon caller), but relying on RLS ALONE
-- when a one-line revoke is free is exactly the gap that bit this codebase
-- before. `revoke all` is simpler than naming each privilege since anon
-- should never reach any of these five tables at all — unlike server_directory
-- or market_listings, nothing here is meant to be world-readable.
revoke all on public.community_servers  from anon;
revoke all on public.community_members  from anon;
revoke all on public.community_channels from anon;
revoke all on public.community_roles    from anon;
revoke all on public.community_bans     from anon;

-- ---------------------------------------------------------------------------
-- 4. Policies (the functions above have to exist first)
-- ---------------------------------------------------------------------------

-- Read if you own it OR are already a member. The OR is the bootstrap: right
-- after INSERTing your own new server you aren't a community_members row yet.
drop policy if exists community_servers_read on public.community_servers;
create policy community_servers_read on public.community_servers
  for select to authenticated
  using (owner_phone = (auth.jwt() ->> 'phone')
         or public.is_community_member(id));

drop policy if exists community_servers_insert_own on public.community_servers;
create policy community_servers_insert_own on public.community_servers
  for insert to authenticated
  with check (owner_phone = (auth.jwt() ->> 'phone')
              and not public.is_silenced(owner_phone));

drop policy if exists community_servers_update_managers on public.community_servers;
create policy community_servers_update_managers on public.community_servers
  for update to authenticated
  using (public.can_manage_community(id) or owner_phone = (auth.jwt() ->> 'phone'))
  with check (public.can_manage_community(id) or owner_phone = (auth.jwt() ->> 'phone'));

drop policy if exists community_servers_delete_owner on public.community_servers;
create policy community_servers_delete_owner on public.community_servers
  for delete to authenticated
  using (owner_phone = (auth.jwt() ->> 'phone'));

-- Read your own row (bootstrap, mirrors the servers table) or any row once
-- you're already a member.
drop policy if exists community_members_read on public.community_members;
create policy community_members_read on public.community_members
  for select to authenticated
  using (member_phone = (auth.jwt() ->> 'phone')
         or public.is_community_member(community_id));

-- Deliberately admin-only. Self-join does NOT get a policy branch here —
-- community_join() is a SECURITY DEFINER function, so it inserts as the
-- table owner and needs no client-facing INSERT privilege for the self-join
-- case at all. A policy that allowed "member_phone = you" directly would
-- let any authenticated stranger add themselves to ANY community_id with no
-- secret check whatsoever — exactly the guessable-id hole the RPC exists to
-- close (see the file header). Never widen this to allow a direct self-insert.
drop policy if exists community_members_insert on public.community_members;
create policy community_members_insert on public.community_members
  for insert to authenticated
  with check (role <> 'owner' and public.can_manage_community(community_id));

drop policy if exists community_members_update on public.community_members;
create policy community_members_update on public.community_members
  for update to authenticated
  using (public.can_manage_community(community_id))
  with check (role <> 'owner' and public.can_manage_community(community_id));

-- Self-leave, or a manager removing a non-owner — the owner-role guard is
-- enforced by the database itself now, not only by a client-side check.
drop policy if exists community_members_delete on public.community_members;
create policy community_members_delete on public.community_members
  for delete to authenticated
  using (
    (member_phone = (auth.jwt() ->> 'phone') or public.can_manage_community(community_id))
    and role <> 'owner'
  );

drop policy if exists community_channels_read on public.community_channels;
create policy community_channels_read on public.community_channels
  for select to authenticated
  using (public.is_community_member(community_id));

drop policy if exists community_channels_insert on public.community_channels;
create policy community_channels_insert on public.community_channels
  for insert to authenticated
  with check (public.can_create_channel(community_id));

drop policy if exists community_channels_update on public.community_channels;
create policy community_channels_update on public.community_channels
  for update to authenticated
  using (public.can_create_channel(community_id))
  with check (public.can_create_channel(community_id));

drop policy if exists community_channels_delete on public.community_channels;
create policy community_channels_delete on public.community_channels
  for delete to authenticated
  using (public.can_manage_community(community_id));

drop policy if exists community_roles_read on public.community_roles;
create policy community_roles_read on public.community_roles
  for select to authenticated
  using (public.is_community_member(community_id));

drop policy if exists community_roles_write on public.community_roles;
create policy community_roles_write on public.community_roles
  for insert to authenticated
  with check (public.can_manage_community(community_id));

drop policy if exists community_roles_update on public.community_roles;
create policy community_roles_update on public.community_roles
  for update to authenticated
  using (public.can_manage_community(community_id))
  with check (public.can_manage_community(community_id));

drop policy if exists community_roles_delete on public.community_roles;
create policy community_roles_delete on public.community_roles
  for delete to authenticated
  using (public.can_manage_community(community_id));

-- Bans: readable by fellow members (so a client can show "banned" state and
-- refuse to re-invite), written only by a moderator+.
drop policy if exists community_bans_read on public.community_bans;
create policy community_bans_read on public.community_bans
  for select to authenticated
  using (public.is_community_member(community_id));

drop policy if exists community_bans_insert on public.community_bans;
create policy community_bans_insert on public.community_bans
  for insert to authenticated
  with check (public.can_moderate_community(community_id));

drop policy if exists community_bans_delete on public.community_bans;
create policy community_bans_delete on public.community_bans
  for delete to authenticated
  using (public.can_moderate_community(community_id));

-- No `_view` layer here, unlike most files in this codebase — that pattern
-- exists for "world-readable minus one column"; nothing in these tables is
-- world-readable, RLS alone does the real work, and clients hit the base
-- tables directly through the fluent client (the same shape docs/paid_servers.sql
-- already uses for community_passes).


-- ####################################################################
-- ## docs/community_voice.sql
-- ####################################################################
-- Voice channel presence, Phase 2 of "central authority" (2026-08-13): the
-- direct answer to "is Discord voice channels the same way" — a deterministic
-- SELECT for full current occupancy the moment a voice channel is opened,
-- instead of only ever knowing who's here from accumulated broadcasts.
--
-- SAME SHAPE AS PHASE 1 (docs/community_structure.sql), reusing its helpers
-- directly: is_community_member gates reads, can_moderate_community gates a
-- force-disconnect. This file adds near-zero new design — one table.
--
-- PRESENCE STAYS A LIVE SIGNAL; THIS IS A GROUND-TRUTH READ, NOT A SECOND
-- SOURCE OF TRUTH. The existing `vpres` broadcast (VoicePresenceStore) is
-- UNTOUCHED and stays the low-latency path for "someone just joined/left/
-- muted while I'm already watching this room" — nobody wants a 20-second
-- heartbeat lag for that. What this table buys is the ONE moment broadcast
-- can't cover at all: opening a room you weren't already watching. Every
-- state-changing action a joined device already takes (join, leave, mute,
-- camera, screen-share, and the existing 20s heartbeat) upserts or deletes
-- this device's own row alongside the broadcast it already sends — one
-- callback (VoicePresenceStore.onPresence), two consequences, the exact
-- shape publishCommunityStructure took off onStructureChanged in Phase 1.
--
-- NO SERVER-SIDE SWEEP, ON PURPOSE. A force-quit or a dead network stops the
-- heartbeat, which stops the row's `last_seen` from advancing — nothing
-- deletes it. A reader filters `last_seen > now() - interval '65 seconds'`
-- CLIENT-SIDE (VoicePresenceStore.staleAfter, the exact 65s rule its own
-- sweep() already enforces for broadcast-heard occupants), so a stale row
-- simply never renders rather than needing a cron or a trigger to clean up
-- after devices that never got to say goodbye. The row itself outlives its
-- own truth for a while; nothing downstream believes it past 65 seconds.
--
-- A FORCE-DISCONNECT CAPABILITY THE OLD MODEL LITERALLY COULD NOT OFFER —
-- there was nothing to delete. A moderator's DELETE reaches this table
-- (can_moderate_community), which the client can use to remove someone from
-- a room server-side; it does NOT tear down that person's actual WebRTC
-- connection (that stays a client-driven hangup the same way it always has),
-- so this is the roster-eviction half of a kick, not the media half. No
-- "kick from voice" button is wired to it in this pass — the capability is
-- built and tested; a UI for it is a stated follow-up, not invented here.
--
-- Run ONCE in the Supabase SQL editor, AFTER docs/community_structure.sql
-- (needs community_servers for the FK, and is_community_member /
-- can_moderate_community). Safe to re-run: every statement is idempotent.

create table if not exists public.community_voice_presence (
  channel_id   text not null,
  member_phone text not null,
  community_id text not null
                 references public.community_servers(id) on delete cascade,
  member_name  text not null default '',
  muted        boolean not null default false,
  video        boolean not null default false,
  screen       boolean not null default false,
  joined_at    timestamptz not null default now(),
  last_seen    timestamptz not null default now(),
  primary key (channel_id, member_phone)
);

create index if not exists community_voice_presence_community_idx
  on public.community_voice_presence (community_id);

alter table public.community_voice_presence enable row level security;

-- Same lesson Phase 1 had to re-learn live (docs/community_structure.sql):
-- a Supabase project grants table-wide privileges to anon on every NEW
-- table by default. Closed here from the start rather than found after —
-- anon should never reach this table at all, same as every table in
-- community_structure.sql.
revoke all on public.community_voice_presence from anon;
grant select, insert, update, delete on public.community_voice_presence
  to authenticated;

drop policy if exists community_voice_presence_read
  on public.community_voice_presence;
create policy community_voice_presence_read on public.community_voice_presence
  for select to authenticated
  using (public.is_community_member(community_id));

drop policy if exists community_voice_presence_insert
  on public.community_voice_presence;
create policy community_voice_presence_insert on public.community_voice_presence
  for insert to authenticated
  with check (
    member_phone = (auth.jwt() ->> 'phone')
    and public.is_community_member(community_id)
  );

-- Own row only — a member's mic/camera/screen state is theirs to update,
-- never another member's or a moderator's to rewrite (a moderator's power
-- here is limited to DELETE, i.e. eviction, never impersonating state).
drop policy if exists community_voice_presence_update
  on public.community_voice_presence;
create policy community_voice_presence_update on public.community_voice_presence
  for update to authenticated
  using (member_phone = (auth.jwt() ->> 'phone'))
  with check (member_phone = (auth.jwt() ->> 'phone'));

-- Self-leave, or a moderator+ force-disconnecting someone else.
drop policy if exists community_voice_presence_delete
  on public.community_voice_presence;
create policy community_voice_presence_delete on public.community_voice_presence
  for delete to authenticated
  using (
    member_phone = (auth.jwt() ->> 'phone')
    or public.can_moderate_community(community_id)
  );


-- ####################################################################
-- ## docs/chat_structure.sql
-- ####################################################################
-- Server-authoritative chat structure (2026-08-13): Phase 3 of "central
-- authority for the entire app" — the same cache-coherence backstop
-- community_structure.sql built for servers, now for 1:1 and group chats.
--
-- WHY THIS EXISTS. A chat's ROSTER (who's in a group, who a 1:1 is between)
-- has always been pure client gossip: `gupd` events, fanned out pairwise and
-- unconditionally trusted by every recipient, with no server-side check that
-- a payload claiming to add or remove a member actually came from someone
-- allowed to. This file adds a durable, RLS-scoped copy of that structure —
-- who is in the chat, and (for a group) its name/photo/about — so a device
-- can read a permission-checked truth instead of trusting whatever the last
-- `gupd` happened to say, and a removal can finally be enforced somewhere
-- other than "the sender's app chose to send it."
--
-- WHAT STAYS EXACTLY AS TODAY: message CONTENT. Every message — 1:1 or
-- group — keeps riding the Double Ratchet / static-ECDH pairwise ladder
-- (RelayService.sealContent/send/sendToGroup), fanned out one sealed copy
-- per recipient, exactly as it does now. Nothing in this file can read a
-- message body, and there is no sender-key/rotation concept here at all —
-- group content crypto is independent pairwise sessions, not a shared key a
-- roster change would need to rotate (see CLAUDE.md's own note on this).
-- `gupd`/`applyGroupUpdate` are untouched and remain the only path for a
-- fully offline device or one reachable only over Bluetooth mesh — that is
-- the permanent, correct shape for a local-first app, not a migration-window
-- limitation.
--
-- SHIPPED PERMISSIONS, NOT NEW ONES. Reading lib/screens/group_info_screen.dart
-- directly (not trusting a first-pass summary that turned out to be wrong)
-- found the app ALREADY enforces admin-only removal client-side (roster
-- index 0, `iAmAdmin && i != 0` gates the remove button) and there is no
-- "leave group" feature anywhere in the app at all. This file's RLS matches
-- that shipped behavior — admin-only delete from chat_members, nobody (not
-- even the admin) can remove themselves — rather than inventing a stricter
-- or looser rule than what the client already promises.
--
-- TWO KINDS OF CHAT, ONE PAIR OF TABLES. A group has a real owner (roster
-- index 0) and an objective shared name/photo/about everyone sees the same
-- way. A 1:1 has neither — Chat.contact.name is each side's OWN local name
-- for the other person (you might call them "Mom", they call you "John"),
-- so publishing a shared "name" for a 1:1 would either leak how you renamed
-- them or be meaningless. `direct_chats.owner_phone` is the switch: '' means
-- a 1:1 (name/avatar_color/about stay empty and are never published), a real
-- phone means a group whose owner is that phone.
--
-- BOOTSTRAP, TWO SHAPES. A group gets the same trigger-seed pattern
-- community_structure.sql uses for a server's owner: creating the
-- direct_chats row automatically seeds the owner's own chat_members row, so
-- there's no chicken-and-egg for the admin-only insert policy. A 1:1 has no
-- "owner" to seed from a trigger — BOTH real parties have to self-register —
-- so `phone_a`/`phone_b` (set once, at insert, and never grantable to update)
-- name the two real parties directly, and the chat_members bootstrap insert
-- policy checks a self-insert against those two named phones instead of
-- trusting a bare "insert yourself" policy. That distinction matters: a
-- group's id ('group_${epochMicroseconds}') is exactly as guessable as a
-- Community.id, which is why community_structure.sql refused a bare
-- self-insert bootstrap for a server's roster — the same discipline applies
-- here, so a group's ONLY bootstrap path is the owner-seed trigger, and every
-- other member is added by an EXISTING member (never a stranger guessing the
-- id). A 1:1's id ('chat_${contact.id}') is no safer in the abstract, but
-- self-inserting into ITS roster requires already being named as phone_a or
-- phone_b on a row that can only ever have been created by one of those two
-- phones in the first place — so guessing the id alone is not enough.
--
-- WHY direct_chats IS INSERT-ONCE FOR A 1:1, NEVER UPDATED. name/avatar_color/
-- about are deliberately never populated for a 1:1 (see above), and
-- is_group/owner_phone/phone_a/phone_b are immutable by design (not even in
-- the update column grant). So there is genuinely nothing about a 1:1's row
-- worth updating after creation — RelayService.publishChatStructure uses
-- `on conflict (id) do nothing` for a 1:1, which sidesteps a real
-- chicken-and-egg: the update policy requires is_chat_member(id), but the
-- SECOND party of a fresh 1:1 hasn't self-registered into chat_members yet
-- the first time their own device syncs.
--
-- NO DELETE PATH, ON PURPOSE — matches the shipped app exactly. There is no
-- "leave group" and no "delete this 1:1 forever" feature client-side, so
-- direct_chats grants no delete at all; the only delete grant is on
-- chat_members, gated to the group owner removing a non-owner. A local
-- ChatStore.deleteChat is exactly that — LOCAL, hides the conversation on
-- this device — and this table was never meant to track that.
--
-- MIGRATION: NOTHING IS REQUIRED, EVERYTHING IS OPPORTUNISTIC. Same as
-- community_structure.sql: an existing chat needs no manual recreation. A
-- group publishes on every `sendGroupUpdate` call (the one funnel every
-- structural change — create, rename, add member, remove member — already
-- goes through); a 1:1 publishes once, the first time either side sends a
-- message in it. A chat whose owner (for a group) or whose two parties (for
-- a 1:1) never open a build carrying this code simply never gets a row here
-- and keeps working exactly as it does today, over gossip alone, forever.
--
-- NUMBERLESS ACCOUNTS ARE NOT REACHED BY THIS FILE — same limit as
-- community_structure.sql, for the same reason (auth.jwt() ->> 'phone' needs
-- a session a numberless account never has). Such a device transparently
-- keeps using legacy peer-broadcast structure for every chat, indefinitely.
--
-- Run ONCE in the Supabase SQL editor, AFTER docs/platform_moderation.sql
-- (is_locked_out) and docs/public_feed.sql (is_silenced). Safe to re-run:
-- every statement is idempotent.

-- ---------------------------------------------------------------------------
-- 1. Tables
-- ---------------------------------------------------------------------------
create table if not exists public.direct_chats (
  id            text primary key,             -- matches Chat.id
  is_group      boolean not null default false,
  owner_phone   text not null default '',      -- group admin; '' means a 1:1
  -- The two real parties of a 1:1 — see the file header for why. Always ''
  -- for a group (a group's members live in chat_members like everything
  -- else; these two columns exist ONLY to make a 1:1's bootstrap safe).
  phone_a       text not null default '',
  phone_b       text not null default '',
  -- Never populated for a 1:1 — see the file header.
  name          text not null default '',
  avatar_color  text not null default '',
  about         text not null default '',
  updated_at    timestamptz not null default now(),
  created_at    timestamptz not null default now()
);

create table if not exists public.chat_members (
  chat_id      text not null
                 references public.direct_chats(id) on delete cascade,
  member_phone text not null,
  joined_at    timestamptz not null default now(),
  primary key (chat_id, member_phone)
);

create index if not exists chat_members_phone_idx
  on public.chat_members (member_phone);

alter table public.direct_chats enable row level security;
alter table public.chat_members enable row level security;

-- ---------------------------------------------------------------------------
-- 2. Functions (the tables above have to exist first)
-- ---------------------------------------------------------------------------

-- Mirrors is_community_member(cid, p) exactly.
create or replace function public.is_chat_member(cid text, p text default null)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.chat_members m
     where m.chat_id = cid
       and m.member_phone = coalesce(p, auth.jwt() ->> 'phone')
  );
$$;

-- THE GROUP OWNER'S BOOTSTRAP — mirrors community_servers_seed_owner exactly.
-- chat_members_insert (below) requires already being a member for the
-- general case, which is correct for every OTHER add but is a chicken-and-egg
-- for the very first row: a brand-new group's owner isn't a chat_members row
-- yet, so their own insert policy would refuse even them. A trigger sidesteps
-- that the same way it does for a server. A 1:1 (owner_phone = '') has no
-- single identity to seed from here — both real parties self-register via
-- the phone_a/phone_b bootstrap branch in chat_members_insert instead.
create or replace function public.direct_chats_seed_owner()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.is_group and new.owner_phone <> '' then
    insert into public.chat_members (chat_id, member_phone)
    values (new.id, new.owner_phone)
    on conflict (chat_id, member_phone) do nothing;
  end if;
  return new;
end;
$$;

drop trigger if exists direct_chats_seed_owner_trigger on public.direct_chats;
create trigger direct_chats_seed_owner_trigger
  after insert on public.direct_chats
  for each row execute function public.direct_chats_seed_owner();

-- Whether [p] is one of a 1:1's two named parties. SECURITY DEFINER on
-- purpose, for the same reason is_chat_member is: a plain subquery embedded
-- directly in chat_members_insert's WITH CHECK below would run as the
-- CALLING role and so would itself be subject to direct_chats_read's own
-- is_chat_member(id) policy — which is false for the very party trying to
-- bootstrap their way IN, making the row invisible to its own check even
-- though it genuinely names them. Found by running this file's own tests:
-- the first version had the subquery inline and self-registration failed
-- with "new row violates row-level security policy" for a real named party.
create or replace function public.is_direct_chat_party(cid text, p text default null)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.direct_chats d
     where d.id = cid
       and not d.is_group
       and coalesce(p, auth.jwt() ->> 'phone') in (d.phone_a, d.phone_b)
  );
$$;

-- ---------------------------------------------------------------------------
-- 3. Column privileges
-- ---------------------------------------------------------------------------
-- No phone-hiding dance here (unlike community_servers' secret_hash) — there
-- is no secret in either table, and neither is world-readable (RLS scopes
-- both to real members only), so a plain column-unrestricted select is fine.
-- What IS restricted: which columns an UPDATE may touch. is_group,
-- owner_phone, phone_a and phone_b are never in the update grant, so even a
-- caller who passes the update policy's USING/CHECK cannot rewrite a chat's
-- identity or flip a 1:1 into a group — the same "grant only the columns
-- that should ever move" pattern public_posts_update_own uses for edited
-- posts (docs/public_feed_edit.sql).
revoke select, insert, update, delete on public.direct_chats from anon, authenticated;
grant select, insert on public.direct_chats to authenticated;
grant update (name, avatar_color, about, updated_at) on public.direct_chats to authenticated;
-- No delete grant at all — see the file header ("no delete path, on purpose").

revoke select, insert, update, delete on public.chat_members from anon, authenticated;
grant select, insert, delete on public.chat_members to authenticated;
-- No update grant — a member row has nothing mutable but joined_at, which
-- should never move once set.

-- REVOKE ANON EXPLICITLY, ON EVERY TABLE — the lesson community_structure.sql
-- already had to state once for this codebase: a live Supabase project grants
-- table-wide privileges to `anon` on every NEW table by default, and
-- `revoke ... from public` does not take that away. Named here from the
-- start rather than found after.
revoke all on public.direct_chats from anon;
revoke all on public.chat_members from anon;

-- ---------------------------------------------------------------------------
-- 4. Policies (the functions above have to exist first)
-- ---------------------------------------------------------------------------

drop policy if exists direct_chats_read on public.direct_chats;
create policy direct_chats_read on public.direct_chats
  for select to authenticated
  using (public.is_chat_member(id));

-- A group: you may create it only as its own owner. A 1:1: owner_phone must
-- be '' and you must be one of the two named parties — see the file header
-- for why phone_a/phone_b exist at all.
drop policy if exists direct_chats_insert on public.direct_chats;
create policy direct_chats_insert on public.direct_chats
  for insert to authenticated
  with check (
    (is_group
      and owner_phone = (auth.jwt() ->> 'phone')
      and not public.is_silenced(owner_phone))
    or (not is_group
      and owner_phone = ''
      and phone_a <> '' and phone_b <> '' and phone_a <> phone_b
      and (auth.jwt() ->> 'phone') in (phone_a, phone_b))
  );

-- Rename/re-photo/about — any member, not just the owner. Matches the
-- shipped app exactly: openGroupEditor has no admin gate, only member
-- REMOVAL does. The update grant above already restricts which columns this
-- can ever touch, so is_chat_member alone is the whole gate needed here.
drop policy if exists direct_chats_update on public.direct_chats;
create policy direct_chats_update on public.direct_chats
  for update to authenticated
  using (public.is_chat_member(id))
  with check (public.is_chat_member(id));

drop policy if exists chat_members_read on public.chat_members;
create policy chat_members_read on public.chat_members
  for select to authenticated
  using (public.is_chat_member(chat_id));

-- General case: any existing member may add another — matches the shipped
-- app exactly (adding members has no admin gate, unlike removal). Bootstrap
-- case: a fresh 1:1's own two named parties may self-insert even before
-- either is a chat_member yet — see the file header for why this is safe
-- (phone_a/phone_b were fixed at insert time by one of the two real parties,
-- never by a client-supplied member_phone).
drop policy if exists chat_members_insert on public.chat_members;
create policy chat_members_insert on public.chat_members
  for insert to authenticated
  with check (
    public.is_chat_member(chat_id)
    or (member_phone = (auth.jwt() ->> 'phone')
        and public.is_direct_chat_party(chat_id))
  );

-- Admin-only, and the admin can never remove themselves — matches
-- group_info_screen.dart's shipped `iAmAdmin && i != 0` exactly. For a 1:1
-- (owner_phone = '') this can never match anyone, which is correct: there is
-- no member-removal concept for a 1:1 at all.
drop policy if exists chat_members_delete on public.chat_members;
create policy chat_members_delete on public.chat_members
  for delete to authenticated
  using (
    exists (
      select 1 from public.direct_chats d
       where d.id = chat_id and d.owner_phone = (auth.jwt() ->> 'phone')
    )
    and member_phone <> (auth.jwt() ->> 'phone')
  );

-- No `_view` layer here, same reasoning as community_structure.sql — nothing
-- in either table is world-readable, RLS alone does the real work.


-- ####################################################################
-- ## docs/server_messages.sql
-- ####################################################################
-- Server-stored direct messages (2026-08-22) — the owner's direction change:
-- "move away from privacy and storing things local and be more social media",
-- answered as "server-stored, encrypted at rest, keys held by the server".
--
-- WHAT THIS IS, SAID PLAINLY RATHER THAN DRESSED UP. Message bodies live in
-- this table in the clear. "Encrypted at rest" is the PLATFORM's disk
-- encryption, whose keys Supabase holds and manages — the same thing every
-- mainstream messenger means by the phrase, and the same thing that is
-- already true of every public post, listing and forum thread in this
-- project. It is NOT end-to-end encryption and this file must never be
-- described as if it were. Anyone with database access can read a message,
-- and that is the deliberate trade: it is what makes history follow an
-- account to a new phone, what makes a reported message readable by a
-- moderator, and what makes the app behave like the social apps it is being
-- pointed at.
--
-- THE LEGAL DOCUMENTS ARE PART OF THIS CHANGE, NOT A FOLLOW-UP. The
-- published Privacy Policy and Terms (legalVersion 7, live at
-- /pages/privacy and /pages/terms and submitted to App Store Connect) say
-- outright that message bodies cannot be read by us. That stops being true
-- the moment anything WRITES to this table, so the client wiring and a
-- legalVersion bump have to land together. Applying this migration alone
-- changes nothing: no code writes here yet, and an empty table makes no
-- promise either way.
--
-- WHAT IS NOT REPLACED. The existing sealed broadcast and the `mailbox`
-- store-and-forward stay exactly as they are and keep being the delivery
-- path — this table is DURABLE HISTORY, not transport. A device still
-- receives a message the way it does today; what changes is that the message
-- is also written somewhere it can be read back from on a different phone,
-- next year, after a reinstall. Keeping the two apart means an older build
-- goes on working unchanged, and a device with no session (a name-only
-- account) still sends and receives over the anon-key mailbox exactly as it
-- always has.
--
-- ROUTING, AND WHY BOTH SHAPES ARE ONE TABLE. A 1:1 message names a
-- recipient; a group message names a group and nobody in particular. Rather
-- than two tables with two sets of policies to keep in step, `group_id` is
-- the switch: empty means 1:1 (and `recipient_phone` is the other party),
-- non-empty means a group whose membership is already server-authoritative
-- in chat_members (docs/chat_structure.sql), so `is_chat_member` is the
-- whole read gate for that half and there is no second roster to maintain.
--
-- ANON HAS NOTHING HERE, granted explicitly rather than left to RLS. The
-- community_structure.sql lesson, learned live: Supabase grants table-wide
-- privileges to `anon` on every NEW table by default, and a policy scoped
-- `to authenticated` merely means no policy ever matches an anon caller —
-- the raw grant still sits there waiting for the day a policy changes.

create table if not exists public.direct_messages (
  -- The client's own message id. Already unique within a conversation, and
  -- paired with chat_id below it is unique everywhere; kept as the primary
  -- key so an edit, a delete and a receipt all address the same row the app
  -- already addresses locally, with no id translation layer.
  id              text primary key,
  chat_id         text not null,
  -- Never taken from the client: filled from the caller's own JWT, so a
  -- device cannot write a message as somebody else even before RLS looks.
  sender_phone    text not null default (auth.jwt() ->> 'phone'),
  -- '' for a group message.
  recipient_phone text not null default '',
  -- '' for a 1:1.
  group_id        text not null default '',
  -- The readable message. Empty for a message that carries no words (a
  -- photo, a poll, a location) — those live in `payload`.
  body            text not null default '',
  -- Everything else the app's Message model holds, verbatim, so a message
  -- kind added later needs no migration. Same shape community_posts and
  -- market_listings already use.
  payload         jsonb not null default '{}'::jsonb,
  created_at      timestamptz not null default now(),
  edited_at       timestamptz,
  -- A delete-for-everyone. The row stays so the tombstone reaches a device
  -- that was offline, and so a moderator can still see what was reported.
  deleted         boolean not null default false
);

create index if not exists direct_messages_chat_idx
  on public.direct_messages (chat_id, created_at);
create index if not exists direct_messages_recipient_idx
  on public.direct_messages (recipient_phone, created_at);
create index if not exists direct_messages_sender_idx
  on public.direct_messages (sender_phone, created_at);

alter table public.direct_messages enable row level security;

revoke all on table public.direct_messages from anon;
revoke all on table public.direct_messages from authenticated;
grant select, insert, delete on table public.direct_messages to authenticated;
-- Column-scoped UPDATE: an edit may change the words and stamp itself, and a
-- delete-for-everyone may set the flag. Nothing else can move — a later
-- write can never reassign a message's author, its conversation, or when it
-- was sent, which is what keeps the history somebody reads back the history
-- that happened.
grant update (body, payload, edited_at, deleted)
  on table public.direct_messages to authenticated;

-- Whether the caller is a party to this message: its sender, its named
-- recipient, or a member of the group it was sent to.
--
-- SECURITY DEFINER because the group half reads chat_members, which is
-- itself behind RLS — the same self-reference trap is_chat_member and
-- is_community_member are already definer to avoid.
create or replace function public.is_message_party(
  p_sender text, p_recipient text, p_group text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select case
    when auth.jwt() ->> 'phone' is null then false
    when p_sender = auth.jwt() ->> 'phone' then true
    when p_group <> '' then public.is_chat_member(p_group)
    else p_recipient = auth.jwt() ->> 'phone'
  end;
$$;

revoke all on function public.is_message_party(text, text, text) from public;
revoke all on function public.is_message_party(text, text, text) from anon;
grant execute on function public.is_message_party(text, text, text)
  to authenticated;

drop policy if exists direct_messages_read on public.direct_messages;
create policy direct_messages_read on public.direct_messages
  for select to authenticated
  using (public.is_message_party(sender_phone, recipient_phone, group_id));

-- Send. The sender is always yourself (the column default fills it from the
-- JWT, and this refuses it even if a client names somebody else), and a
-- group message is refused unless you are actually on that group's roster —
-- which is the thing `gupd` gossip could never check.
drop policy if exists direct_messages_send on public.direct_messages;
create policy direct_messages_send on public.direct_messages
  for insert to authenticated
  with check (
    sender_phone = auth.jwt() ->> 'phone'
    and not public.is_silenced(auth.jwt() ->> 'phone')
    and (
      (group_id = '' and recipient_phone <> '')
      or (group_id <> '' and public.is_chat_member(group_id))
    )
  );

-- Edit and delete-for-everyone: the author, and only the author. A
-- recipient deleting somebody else's message from the record is a different
-- feature from the one the app has, and it is not this one.
drop policy if exists direct_messages_edit on public.direct_messages;
create policy direct_messages_edit on public.direct_messages
  for update to authenticated
  using (sender_phone = auth.jwt() ->> 'phone')
  with check (sender_phone = auth.jwt() ->> 'phone');

-- A real DELETE, distinct from the `deleted` tombstone above: the tombstone
-- is what other devices need to see, this is "take it off the server
-- entirely" and is the author's own right over their own words.
drop policy if exists direct_messages_remove on public.direct_messages;
create policy direct_messages_remove on public.direct_messages
  for delete to authenticated
  using (sender_phone = auth.jwt() ->> 'phone');


-- ####################################################################
-- ## docs/user_items.sql
-- ####################################################################
-- Per-row user data (2026-08-23) — the X model for the lists that used to
-- ride the backup blob.
--
-- WHY A GENERIC TABLE RATHER THAN ONE PER STORE. Roughly forty stores hold
-- list-shaped data (bookmarks and their folders, muted accounts, chat
-- folders, inbox tiers, quick replies, saved forms, stickers, saved cities,
-- watch history…). A table each would be forty migrations, forty policy
-- sets and forty client wrappers to keep in step, and this project has
-- already learned what happens when N copies of one idea drift. One table
-- with a `kind` column costs one migration and makes converting the next
-- store a few lines instead of a schema change.
--
-- WHAT IT FIXES. The blob is ONE document with last-writer-wins over the
-- whole of it: two devices that both change something offline do not merge —
-- the second uploader wins outright, including for categories it never
-- touched. Per ROW, that conflict shrinks to the single item both devices
-- actually touched, and everything else on both sides survives. That is the
-- difference between a backup and a sync, and it is why X-shaped apps store
-- rows rather than documents.
--
-- THE CLOCK IS THE SERVER'S. `updated_at` is stamped by a trigger, never by
-- the client, so "last write wins" means the last write to REACH THE SERVER
-- — not whichever device has the furthest-ahead clock. A client-supplied
-- timestamp would let a phone with a wrong clock win every conflict for
-- ever, and there would be no way to tell that from working correctly.
--
-- DELETES ARE TOMBSTONES. A row removed outright would come straight back
-- from any device that still had it locally, so `deleted` is a flag and the
-- row keeps its place in the incremental fetch. That is also what lets a
-- delete made on one device reach the others at all.

create table if not exists public.user_items (
  -- Never taken from the client: filled from the caller's own JWT, so a
  -- device cannot write into somebody else's items even before RLS looks.
  owner_phone text not null default (auth.jwt() ->> 'phone'),
  -- Which store this belongs to ('bookmark', 'mute', …). The one column that
  -- makes this generic.
  kind        text not null,
  -- The store's own id for the thing. Unique within a kind, per owner.
  item_id     text not null,
  payload     jsonb not null default '{}'::jsonb,
  updated_at  timestamptz not null default now(),
  deleted     boolean not null default false,
  primary key (owner_phone, kind, item_id)
);

-- The incremental read: "everything of mine, of this kind, changed since X".
create index if not exists user_items_sync_idx
  on public.user_items (owner_phone, kind, updated_at);

-- The server's clock, on every write. See the header: a client-supplied
-- timestamp hands every conflict to whichever device is furthest ahead.
create or replace function public.user_items_touch()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  new.updated_at := now();
  return new;
end $$;

drop trigger if exists user_items_touch on public.user_items;
create trigger user_items_touch
  before insert or update on public.user_items
  for each row execute function public.user_items_touch();

alter table public.user_items enable row level security;

-- The community_structure.sql lesson, applied from the start: Supabase grants
-- table-wide privileges to `anon` on every new table, and a policy scoped
-- `to authenticated` only means no policy ever MATCHES an anon caller — the
-- raw grant sits there waiting for the day a policy changes.
revoke all on table public.user_items from anon;
revoke all on table public.user_items from authenticated;
grant select, insert, delete on table public.user_items to authenticated;
-- Column-scoped UPDATE: an edit may change the thing or retire it. It can
-- never move a row to a different owner, a different kind or a different id,
-- and it can never set its own timestamp — the trigger owns that.
grant update (payload, deleted) on table public.user_items to authenticated;

-- Yours and nobody else's, for every verb. There is no sharing model here at
-- all: these are one account's own lists.
drop policy if exists user_items_own on public.user_items;
create policy user_items_own on public.user_items
  for all to authenticated
  using (owner_phone = auth.jwt() ->> 'phone')
  with check (owner_phone = auth.jwt() ->> 'phone');


-- ####################################################################
-- ## docs/call_presence.sql
-- ####################################################################
-- Server-authoritative call presence (2026-08-13): Phase 4 of "central
-- authority" — a durable, RLS-scoped roster for a live call, the same
-- cache-coherence backstop Phase 1/2/3 built for servers, voice channels and
-- chats.
--
-- WHY THIS EXISTS. CallSession.members has never had a ground truth beyond
-- accumulated signaling events (onRemoteJoined/onRemoteLeft) — a `left`
-- event that never arrives (a force-quit, a dropped connection) leaves that
-- peer permanently `joined` on every other device, with no sweep or
-- server-side read that could correct it. This table is that correction: a
-- durable row per (call, member) that a reconnecting device can read to
-- learn who is actually still on the call, plus a real place to enforce
-- "only someone who was actually dialed may join this call's roster."
--
-- WHAT STAYS EXACTLY AS TODAY: call SIGNALING and MEDIA. `offer`/`answer`/
-- `ice`/`end`/`decline`/`joined`/`left` all keep riding the pairwise Double
-- Ratchet/static-ECDH ladder exactly as they do now (RelayService.sendCall,
-- sealContent), and this table carries none of that traffic. Media itself
-- stays DTLS-SRTP, WebRTC's own layer, below any of this. There is no
-- sender-key/rotation concept here — this is presence bookkeeping, not a
-- broadcast key.
--
-- NO DURABLE PARENT ROW, UNLIKE community_voice_presence. A voice channel's
-- presence FKs to community_servers, whose id is a real, durable, join-gated
-- identity. A call has nothing like that: CallSession.callId is minted
-- client-side purely as a signaling correlation id
-- ('call_${peerDigits}_${epochMs}_${seq}', see CallService._newCallId) —
-- there is no "the call" row anywhere to reference, and inventing one would
-- be a bigger, unasked-for change (a durable call-log table, which
-- CallLog.dart already deliberately keeps LOCAL-ONLY — see its own doc
-- comment — and this file does not change that). So call_rosters is keyed
-- purely by call_id with no foreign key at all, and the RLS below has to
-- answer "who may touch this call's rows" from first principles rather than
-- delegating to a parent table's membership, the way every other central-
-- authority table so far has been able to.
--
-- ELIGIBILITY IS DIAL-LIST-BASED, NOT MEMBERSHIP-BASED — the real design
-- difference from every earlier central-authority table. The INITIATOR's
-- row is the one that ever carries a real `dial_phones` array (who they
-- actually rang); `call_dial_list(cid)` reads it off whichever row has a
-- non-empty one, and `is_call_eligible` is true for anyone named on that
-- list OR the initiator themselves (covering the initiator's own later
-- re-inserts/heartbeats, once their first row already exists).
--
-- THE BOOTSTRAP HOLE THIS DESIGN NEEDED TO CLOSE, AND HOW (2026-08-13).
-- Because call_id has no durable parent to gate against, the FIRST row for
-- any call_id is insertable by whoever gets there first, as long as they
-- name themselves both member and initiator — this part of the design is
-- permanent, and the RLS below still allows it. What is CLOSED is what
-- originally made that a real hole: call_id used to be guessable within a
-- narrow window (a predictable prefix plus an epoch-millisecond timestamp
-- and a small sequence counter), so a caller could in principle race to
-- squat someone else's about-to-start call before its real initiator's row
-- landed. CallService._newCallId now appends 128 bits of real entropy
-- (Random.secure(), the OS CSPRNG) to that id — the timestamp and peer
-- digits stay, for readability/sortability, but they no longer carry any
-- of the actual unpredictability the id needs. With that fixed, "founder
-- claims the first row" is no longer squattable in practice: nobody can
-- guess a call_id nobody has told them, so the bootstrap branch only ever
-- fires for someone who was actually handed the id over the existing
-- sealed pairwise signaling.
--
-- Deliberately a CLIENT-SIDE fix, not a server-minted id. The alternative —
-- an authenticated RPC that mints the id before a call can start ringing —
-- was considered and rejected: it would mean a numberless account (no
-- Supabase session at all — see the numberless-accounts section) could no
-- longer place or receive calls, breaking the one invariant every phase of
-- central authority has held so far, that the legacy path keeps working,
-- unconditionally, forever. A forged row here was already bounded before
-- this fix and remains so: the ACTUAL ringing, the ACTUAL WebRTC media, and
-- who can decrypt either are governed entirely by the existing sealed
-- pairwise signaling, which this table cannot see or influence — a forged
-- row can at most confuse a READ of this table (RelayService.
-- fetchCallPresence, still wired conservatively — see that function's own
-- doc comment), never grant access to a call's audio, video, or signaling.
--
-- CLEANUP IS BOTH CLIENT-SIDE (best-effort, on every real call end/decline —
-- see RelayService.leaveCallRoster's call sites in call_service.dart) AND A
-- SCHEDULED pg_cron JOB, chosen deliberately over client-side-only: a call
-- that ends by a force-quit or a dropped connection never runs any client
-- cleanup code at all, and unlike a voice channel's presence (which sweeps
-- CLIENT-SIDE off a live staleAfter clock the moment anyone opens the
-- channel screen) a call has no "someone will open this again soon" moment
-- to piggyback a sweep onto — an ended call's stale rows would otherwise sit
-- forever. This is genuinely the first use of pg_cron in this project;
-- the whole cron block below is guarded so a Postgres without the extension
-- (this repo's own throwaway-Postgres test harness, or a Supabase plan/
-- region that doesn't offer it) skips scheduling rather than failing the
-- whole migration.
--
-- Run ONCE in the Supabase SQL editor, after docs/platform_moderation.sql
-- (not a hard dependency here, but kept in migration order with the rest of
-- central authority). Safe to re-run: every statement is idempotent.

-- ---------------------------------------------------------------------------
-- 1. Table
-- ---------------------------------------------------------------------------
create table if not exists public.call_rosters (
  call_id         text not null,
  member_phone    text not null,
  -- Set only on the row that named the dial list — see call_dial_list().
  initiator_phone text not null default '',
  -- Only ever non-empty on the initiator's own row.
  dial_phones     text[] not null default '{}',
  member_name     text not null default '',
  video           boolean not null default false,
  joined_at       timestamptz not null default now(),
  last_seen       timestamptz not null default now(),
  primary key (call_id, member_phone)
);

create index if not exists call_rosters_last_seen_idx
  on public.call_rosters (last_seen);

alter table public.call_rosters enable row level security;

-- ---------------------------------------------------------------------------
-- 2. Functions (the table above has to exist first)
-- ---------------------------------------------------------------------------

-- The real dial list for [cid] — whichever row carries a non-empty one (the
-- initiator's). '{}' when no such row exists yet, which is also how the
-- insert policy's bootstrap branch recognizes "nobody has claimed this call
-- id yet."
create or replace function public.call_dial_list(cid text)
returns text[]
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(
    (select dial_phones from public.call_rosters
      where call_id = cid and cardinality(dial_phones) > 0
      limit 1),
    '{}'::text[]
  );
$$;

-- True when [p] was actually dialed for [cid], or is the call's own
-- initiator (covering their later re-inserts/heartbeats, once their first
-- row — the one that established the dial list at all — already exists).
create or replace function public.is_call_eligible(cid text, p text default null)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(p, auth.jwt() ->> 'phone') = any(public.call_dial_list(cid))
      or exists (
        select 1 from public.call_rosters
         where call_id = cid
           and initiator_phone = coalesce(p, auth.jwt() ->> 'phone')
      );
$$;

-- ---------------------------------------------------------------------------
-- 3. Column privileges
-- ---------------------------------------------------------------------------
-- No column-hiding dance — nothing here is a secret the way secret_hash is
-- for a server, and the table is never world-readable (RLS scopes it to
-- eligible callers only).
revoke select, insert, update, delete on public.call_rosters from anon, authenticated;
grant select, insert, update, delete on public.call_rosters to authenticated;

-- REVOKE ANON EXPLICITLY — the lesson this codebase already learned once
-- live (find_people_by_hashes, docs/directory_phone_privacy.sql) and has
-- restated in every central-authority file since: a live Supabase project
-- grants table-wide privileges to `anon` on every NEW table by default, and
-- `revoke ... from public` does not take that away.
revoke all on public.call_rosters from anon;

-- ---------------------------------------------------------------------------
-- 4. Policies (the functions above have to exist first)
-- ---------------------------------------------------------------------------

drop policy if exists call_rosters_read on public.call_rosters;
create policy call_rosters_read on public.call_rosters
  for select to authenticated
  using (public.is_call_eligible(call_id));

-- Self-row only, and either the bootstrap case (nothing claims this call_id
-- yet — you may found it, naming yourself as initiator) or real eligibility
-- (you're on the existing dial list, or you're re-inserting your own row as
-- the initiator who already founded it).
drop policy if exists call_rosters_insert on public.call_rosters;
create policy call_rosters_insert on public.call_rosters
  for insert to authenticated
  with check (
    member_phone = (auth.jwt() ->> 'phone')
    and (
      (cardinality(public.call_dial_list(call_id)) = 0
        and initiator_phone = member_phone)
      or public.is_call_eligible(call_id)
    )
  );

-- Own row only — a heartbeat (last_seen) or a mid-call video toggle.
drop policy if exists call_rosters_update on public.call_rosters;
create policy call_rosters_update on public.call_rosters
  for update to authenticated
  using (member_phone = (auth.jwt() ->> 'phone'))
  with check (member_phone = (auth.jwt() ->> 'phone'));

-- Own row only. Deliberately NO moderator-delete, unlike voice presence's
-- force-disconnect — a call has no owner/moderator concept to grant that
-- power to, and inventing one is out of scope here.
drop policy if exists call_rosters_delete on public.call_rosters;
create policy call_rosters_delete on public.call_rosters
  for delete to authenticated
  using (member_phone = (auth.jwt() ->> 'phone'));

-- ---------------------------------------------------------------------------
-- 5. Scheduled cleanup — guarded, since pg_cron may not be available
-- ---------------------------------------------------------------------------
do $outer$
begin
  begin
    execute 'create extension if not exists pg_cron';
  exception when others then
    raise notice '  pg_cron unavailable in this environment — skipping '
      'scheduled call_rosters cleanup (docs/call_presence.sql). Client-side '
      'cleanup (RelayService.leaveCallRoster) still runs on every real '
      'call end; only the force-quit/dropped-connection backstop is missing.';
    return;
  end;

  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    begin
      perform cron.unschedule('call_rosters_cleanup');
    exception when others then
      null; -- no existing job to unschedule — fine on a first run
    end;
    perform cron.schedule(
      'call_rosters_cleanup',
      '*/15 * * * *',
      $cron$delete from public.call_rosters where last_seen < now() - interval '2 hours'$cron$
    );
  end if;
end
$outer$;


-- ####################################################################
-- ## docs/app_pricing.sql
-- ####################################################################
-- Owner-editable pricing (2026-08-09). The prices the APP assumes — the
-- storage ladder, the four subscription tier levels, and the four tip
-- amounts — so the owner can keep them in step with App Store Connect from
-- inside the app instead of shipping a build. A single row (id = 1).
--
-- WHAT THIS IS NOT: it is not what anybody is charged. Apple charges whatever
-- the SKU says in App Store Connect, and the app always shows the store's own
-- localized price when StoreKit has answered (see lib/payments/store_prices.
-- dart). These numbers fill in only where there is no store price to show —
-- web, payments-test mode, the frame before StoreKit replies — and they set
-- the tier ladder a creator picks a price from. So a mistake here can never
-- advertise a price different from the charge on a real purchase.
--
-- READABLE BY EVERYONE — every device fetches it on launch, like the legal
-- documents. WRITABLE ONLY by the `pricing-set` Edge Function (service role),
-- which checks the caller is the platform owner first. No client write grants.
--
-- Run this in the SQL editor, then paste the `pricing-set` function. Until
-- then the app uses its built-in defaults and the editor says so.
-- ---------------------------------------------------------------------------

create table if not exists public.app_pricing (
  id         int primary key default 1,
  -- { storagePerGbCents, tierCents: [4], tipCents: {id: cents},
  --   storageCents: {gb: cents} }
  -- A jsonb blob on purpose: a new price kind is a key, not a migration.
  prices     jsonb not null default '{}'::jsonb,
  edited_at  timestamptz not null default now(),
  constraint app_pricing_singleton check (id = 1)
);

alter table public.app_pricing enable row level security;

-- Anyone may READ the current prices (fetched on launch, like legal docs).
drop policy if exists app_pricing_read on public.app_pricing;
create policy app_pricing_read on public.app_pricing
  for select using (true);
grant select on table public.app_pricing to anon, authenticated;

-- Nobody writes through the API. The pricing-set function (service role,
-- which bypasses RLS) is the only writer, and it checks ownership first.
revoke insert, update, delete on table public.app_pricing
  from anon, authenticated;


-- ####################################################################
-- ## docs/taken_signups.sql
-- ####################################################################
-- A number or email already in use cannot be claimed twice (2026-08-09).
-- Run AFTER docs/platform_moderation.sql and docs/banned_signups.sql.
--
-- RUN + VERIFIED LIVE 2026-08-09: email_claims exists with RLS on and ZERO
-- client grants, all four functions present, every real directory row reads
-- as taken in both the stored and digits-only form, a made-up number reads
-- free, anon may call the two lookups but can neither read nor write the
-- claims table (42501) and claim_email returns false without a session.
-- Do not re-raise as pending.
--
-- Two doors were open:
--
--   * PHONE — signing UP with a number that already has an account, and
--     attaching a number to a name-only account when somebody else already
--     holds it. Both ended with two accounts pointing at one number. Signing
--     IN with your own existing number is of course fine and is untouched;
--     the difference is which button was pressed, and only signup/attach ask.
--
--   * EMAIL — nothing stopped the same address being attached to any number
--     of accounts, because there was no server-side record of who holds one.
--
-- EMAILS ARE NEVER STORED HERE. The client sends sha256 of the trimmed,
-- lowercased address and the server holds only that — the same shape as
-- `usernames.phone_hash` in schema.sql. So this can answer "is it taken?"
-- and "release mine" without the project ever holding a list of its users'
-- email addresses. (The `banned_emails` list is plaintext on purpose: it is
-- small, admin-curated, and has to be matched by a human typing it.)
--
-- Neither table is readable or writable by a client. Everything goes through
-- the definer functions below, so the claims list can never be enumerated —
-- a downloadable email-hash list is a rainbow-table offline in an afternoon.
-- ---------------------------------------------------------------------------

-- Which account holds which email. One row per address, keyed by its hash.
create table if not exists public.email_claims (
  email_hash text primary key,             -- sha256(lower(trim(email)))
  phone      text not null,                -- digits, the holder
  claimed_at timestamptz not null default now()
);

create index if not exists email_claims_phone_idx on public.email_claims (phone);

alter table public.email_claims enable row level security;
-- No policies and no grants: the definer functions are the only way in.
revoke all on table public.email_claims from anon, authenticated;

-- ---------------------------------------------------------------------------
-- Is this number already an account?
--
-- Canonicalizes both sides, like is_phone_banned — the directory stores
-- E.164 and a client passes digits, the '+'-vs-digits trap the follow and
-- admin lookups already learned the hard way. Callable by anon, because the
-- question is asked at SIGNUP, before there is any session.
--
-- It answers only yes/no about a number the caller already typed, so it
-- reveals nothing they could not learn by trying to sign in.
create or replace function public.is_phone_taken(p text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists(
    select 1 from public.usernames u
     where regexp_replace(u.phone, '\D', '', 'g')
         = regexp_replace(coalesce(p, ''), '\D', '', 'g')
       and regexp_replace(coalesce(p, ''), '\D', '', 'g') <> ''
  );
$$;

grant execute on function public.is_phone_taken(text) to anon, authenticated;

-- ---------------------------------------------------------------------------
-- Is this email hash held by SOMEBODY ELSE?
--
-- Excludes the caller's own claim, so re-saving your own address is not
-- "taken". A signed-out caller has no phone, so every existing claim counts.
create or replace function public.is_email_taken(h text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists(
    select 1 from public.email_claims c
     where c.email_hash = coalesce(h, '')
       and coalesce(h, '') <> ''
       and c.phone is distinct from
           regexp_replace(coalesce(auth.jwt() ->> 'phone', ''), '\D', '', 'g')
  );
$$;

grant execute on function public.is_email_taken(text) to anon, authenticated;

-- ---------------------------------------------------------------------------
-- Claim an email hash for the CALLER. Refuses (false) when another account
-- holds it; moves the caller's previous claim aside so changing your address
-- frees the old one. Needs a session — the claim is meaningless without a
-- phone to attach it to.
create or replace function public.claim_email(h text)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  me text := regexp_replace(coalesce(auth.jwt() ->> 'phone', ''), '\D', '', 'g');
begin
  if me = '' or coalesce(h, '') = '' then
    return false;
  end if;
  -- Held by somebody else: refuse rather than steal it.
  if exists(select 1 from public.email_claims c
             where c.email_hash = h and c.phone <> me) then
    return false;
  end if;
  -- One address per account: drop whatever this account held before.
  delete from public.email_claims where phone = me;
  insert into public.email_claims (email_hash, phone) values (h, me)
    on conflict (email_hash) do update set phone = me, claimed_at = now();
  return true;
end;
$$;

grant execute on function public.claim_email(text) to authenticated;

-- Release the caller's claim (removing the address from the account).
create or replace function public.release_email()
returns void
language sql
security definer
set search_path = public
as $$
  delete from public.email_claims
   where phone = regexp_replace(
           coalesce(auth.jwt() ->> 'phone', ''), '\D', '', 'g')
     and regexp_replace(coalesce(auth.jwt() ->> 'phone', ''), '\D', '', 'g') <> '';
$$;

grant execute on function public.release_email() to authenticated;


-- ####################################################################
-- ## docs/email_account_bans.sql
-- ####################################################################
-- Banning an account bans the EMAIL behind it (2026-08-16).
--
-- Run after docs/banned_signups.sql (the address list and the role gate) and
-- docs/taken_signups.sql (email_claims, which maps an email hash to the
-- account holding it).
--
-- WHY THIS EXISTS. Letting an email-verified account with no phone number use
-- the whole app (supabase/functions/email-account) makes ban evasion cheap:
-- a ban lands on the account's CODE, and a code costs nothing to re-mint, so
-- the same person signs up again with the same inbox and is straight back in.
-- A phone number was the thing that made evasion expensive; an email is not,
-- which is exactly why DisposableEmails exists on the client. This closes the
-- loop by making a ban stick to the address as well as to the account.
--
-- WHY A SECOND TABLE INSTEAD OF REUSING banned_emails. `banned_emails` is
-- keyed by the ADDRESS, in the clear — fine for a moderator typing one in.
-- But `email_claims` deliberately holds only `sha256(lower(trim(email)))`
-- (its own comment: "a downloadable email-hash list is a rainbow-table
-- offline in an afternoon" is the reason it is not readable, and the address
-- itself is never stored at all). So when a moderator bans an ACCOUNT, the
-- address is not recoverable from anything the server holds — only its hash
-- is. Adding it to `banned_emails` is therefore impossible, not merely
-- awkward. This table is the hash-keyed twin, and the two are checked
-- separately by whoever holds the form they can check.
--
-- WHY NO SERVER-SIDE HASHING. Nothing in this project hashes in Postgres —
-- there is no pgcrypto dependency anywhere, and `claim_email` already takes a
-- hash computed by the caller. That stays true here: `is_email_hash_banned`
-- takes a hash, and the one caller that holds a plaintext address (the
-- `email-account` function, which has the confirmed email on the session)
-- computes the digest itself. Adding an extension dependency to check a
-- string the caller can hash in three lines would buy nothing.

-- Which email hashes are barred. One row per hash.
create table if not exists public.banned_email_hashes (
  email_hash  text primary key,           -- sha256(lower(trim(email)))
  actor_phone text not null default '',   -- who banned it (digits)
  reason      text not null default '',
  created_at  timestamptz not null default now()
);
alter table public.banned_email_hashes enable row level security;
-- No policy and no grants: the definer functions below are the only doors,
-- the same posture as banned_emails and email_claims. A client that could
-- read this could confirm a guessed address offline.
revoke all on table public.banned_email_hashes from anon, authenticated;

-- Is this hash barred? A yes/no about a hash the caller already holds, so
-- it reveals nothing it did not bring with it — the same posture as
-- is_email_taken, which is granted the same way and for the same reason.
create or replace function public.is_email_hash_banned(h text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists(select 1 from public.banned_email_hashes
                 where email_hash = coalesce(h, ''));
$$;
revoke all on function public.is_email_hash_banned(text) from public;
-- Named explicitly: Supabase grants EXECUTE on every new function in `public`
-- to anon and authenticated by default, and revoking the PUBLIC pseudo-role
-- leaves those standing. That trap cost a real hole once already
-- (find_people_by_hashes) and the fix is to name the role.
revoke all on function public.is_email_hash_banned(text) from anon, authenticated;
grant execute on function public.is_email_hash_banned(text) to anon, authenticated;

-- Owner/admin only: bar the email behind account [p], addressed by the phone
-- or account code the ban itself names. Returns false and changes nothing for
-- anyone else, and for an account that never attached an email.
create or replace function public.ban_account_email(p text, reason text default '')
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare ph text; ok boolean; target text; h text;
begin
  ph := regexp_replace(coalesce(auth.jwt() ->> 'phone', ''), '\D', '', 'g');
  target := regexp_replace(coalesce(p, ''), '\D', '', 'g');
  if ph = '' or target = '' then return false; end if;
  select exists(
    select 1 from public.platform_roles r
     where regexp_replace(r.phone, '\D', '', 'g') = ph
       and r.role in ('owner', 'admin')) into ok;
  if not ok then return false; end if;
  -- Canonicalized on both sides: an account code is stored bare while a
  -- phone may carry a '+', and comparing them as written would miss.
  select c.email_hash into h
    from public.email_claims c
   where regexp_replace(c.phone, '\D', '', 'g') = target
   limit 1;
  if h is null or h = '' then return false; end if;
  insert into public.banned_email_hashes (email_hash, actor_phone, reason)
    values (h, ph, reason)
    on conflict (email_hash) do nothing;
  return true;
end;
$$;
revoke all on function public.ban_account_email(text, text) from public;
revoke all on function public.ban_account_email(text, text) from anon, authenticated;
grant execute on function public.ban_account_email(text, text) to authenticated;

-- Owner/admin only: lift it again. Same gate, same canonicalization.
create or replace function public.unban_account_email(p text)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare ph text; ok boolean; target text; h text;
begin
  ph := regexp_replace(coalesce(auth.jwt() ->> 'phone', ''), '\D', '', 'g');
  target := regexp_replace(coalesce(p, ''), '\D', '', 'g');
  if ph = '' or target = '' then return false; end if;
  select exists(
    select 1 from public.platform_roles r
     where regexp_replace(r.phone, '\D', '', 'g') = ph
       and r.role in ('owner', 'admin')) into ok;
  if not ok then return false; end if;
  select c.email_hash into h
    from public.email_claims c
   where regexp_replace(c.phone, '\D', '', 'g') = target
   limit 1;
  if h is null or h = '' then return false; end if;
  delete from public.banned_email_hashes where email_hash = h;
  return true;
end;
$$;
revoke all on function public.unban_account_email(text) from public;
revoke all on function public.unban_account_email(text) from anon, authenticated;
grant execute on function public.unban_account_email(text) to authenticated;


-- ####################################################################
-- ## docs/moderation_scopes.sql
-- ####################################################################
-- Shadow bans and area bans (2026-08-09). Run AFTER docs/platform_moderation.sql,
-- docs/public_feed.sql, docs/public_market.sql, docs/public_forum.sql,
-- docs/community_notes.sql and docs/public_servers.sql — it re-creates read and
-- insert policies those files define.
--
-- Until now moderation had one blunt setting: a whole account, banned or
-- timed out everywhere. Two things were missing.
--
--   * A SHADOW BAN. The account carries on exactly as before — it can post,
--     and it sees its own posts in place — but nobody else does. It is the
--     answer to the spammer who simply signs up again the moment they are
--     told they are banned, and it works only because they are NOT told.
--
--   * AREA BANS. Somebody scamming in the marketplace should lose the
--     marketplace, not their conversations. One row per (account, area), so
--     a seller can be barred from selling while still using the forum.
--
-- WHAT A SHADOW BAN IS NOT: it does not hide the account's MESSAGES. Chats
-- are end-to-end encrypted and delivered device to device — the server could
-- not filter them if it wanted to, and would have to break the encryption to
-- try. It hides what is PUBLIC: feed posts, listings, forum posts and
-- comments, community notes, and a listed server. Say that plainly rather
-- than implying a reach this does not have.
-- ---------------------------------------------------------------------------

-- 'shadow' joins the existing kinds. It is deliberately NOT in is_locked_out:
-- a shadow-banned account is not locked out of anything, which is the point.
alter table public.account_sanctions drop constraint if exists account_sanctions_kind_check;
alter table public.account_sanctions add constraint account_sanctions_kind_check
  check (kind in ('timeout', 'suspend', 'ban', 'shadow'));

-- One row per account per area they are barred from.
create table if not exists public.account_area_bans (
  phone       text not null,
  area        text not null check (area in ('marketplace','servers','forum','feed')),
  reason      text not null default '' check (char_length(reason) <= 500),
  until       timestamptz,                  -- null = indefinite
  actor_phone text not null default '',
  created_at  timestamptz not null default now(),
  primary key (phone, area)
);
alter table public.account_area_bans enable row level security;

-- Readable, like account_sanctions: a barred device has to be able to say
-- WHY the marketplace refused it, and every device must agree. Written only
-- by moderation-act (service role), which checks the caller's rank first.
drop policy if exists account_area_bans_read on public.account_area_bans;
create policy account_area_bans_read on public.account_area_bans
  for select to anon, authenticated using (true);

create index if not exists account_area_bans_until_idx
  on public.account_area_bans (until);

-- ---------------------------------------------------------------------------
-- The three predicates every policy below is built from
-- ---------------------------------------------------------------------------
create or replace function public.is_shadow_banned(p text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.account_sanctions s
     where s.phone = p
       and s.kind = 'shadow'
       and (s.until is null or s.until > now())
  );
$$;

-- is_silenced matched ANY active sanction row, whatever its kind. Adding
-- 'shadow' to that table therefore silenced the account — refusing its posts,
-- which is precisely how a shadow-banned person finds out they are shadow
-- banned. Exclude it: a shadow ban must change nothing the target can see.
-- Every existing write policy already calls this, so they all pick it up.
create or replace function public.is_silenced(p text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.account_sanctions s
     where s.phone = p
       and s.kind <> 'shadow'
       and (s.until is null or s.until > now())
  );
$$;

create or replace function public.is_area_banned(p text, a text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.account_area_bans b
     where b.phone = p
       and b.area = a
       and (b.until is null or b.until > now())
  );
$$;

-- Whether an author's public content is visible to the CALLER.
--
-- The self-exception is the whole mechanism of a shadow ban: the author still
-- sees their own posts exactly where they left them, so nothing tells them to
-- go and make another account.
create or replace function public.content_visible(author text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select not public.is_locked_out(author)
     and (
       author = (auth.jwt() ->> 'phone')
       or not public.is_shadow_banned(author)
     );
$$;

grant execute on function public.is_shadow_banned(text) to anon, authenticated;
grant execute on function public.is_area_banned(text, text) to anon, authenticated;
grant execute on function public.content_visible(text) to anon, authenticated;

-- ---------------------------------------------------------------------------
-- Reads: a shadow-banned author's public content disappears for everyone else
-- ---------------------------------------------------------------------------
drop policy if exists public_posts_read on public.public_posts;
create policy public_posts_read on public.public_posts
  for select to anon, authenticated
  using (public.content_visible(author_phone));

drop policy if exists market_listings_read on public.market_listings;
create policy market_listings_read on public.market_listings
  for select to anon, authenticated
  using (public.content_visible(author_phone));

drop policy if exists public_forum_posts_read on public.public_forum_posts;
create policy public_forum_posts_read on public.public_forum_posts
  for select to anon, authenticated
  using (public.content_visible(author_phone));

drop policy if exists public_forum_comments_read on public.public_forum_comments;
create policy public_forum_comments_read on public.public_forum_comments
  for select to anon, authenticated
  using (public.content_visible(author_phone));

drop policy if exists community_notes_read on public.community_notes;
create policy community_notes_read on public.community_notes
  for select to anon, authenticated
  using (public.content_visible(author_phone));

drop policy if exists server_directory_read on public.server_directory;
create policy server_directory_read on public.server_directory
  for select to anon, authenticated
  using (public.content_visible(owner_phone));

-- ---------------------------------------------------------------------------
-- Writes: an area ban refuses new content in THAT area only
-- ---------------------------------------------------------------------------
-- Each of these is the policy that already existed, plus one clause. A
-- shadow-banned account is NOT stopped from writing — being stopped is how
-- you find out.
drop policy if exists public_posts_insert_own on public.public_posts;
create policy public_posts_insert_own on public.public_posts
  for insert to authenticated
  with check (
    author_phone = (auth.jwt() ->> 'phone')
    and not public.is_silenced(author_phone)
    and not public.is_area_banned(author_phone, 'feed')
  );

drop policy if exists market_listings_insert_own on public.market_listings;
create policy market_listings_insert_own on public.market_listings
  for insert to authenticated
  with check (
    author_phone = (auth.jwt() ->> 'phone')
    and not public.is_silenced(author_phone)
    and not public.is_area_banned(author_phone, 'marketplace')
  );

drop policy if exists public_forum_posts_insert_own on public.public_forum_posts;
create policy public_forum_posts_insert_own on public.public_forum_posts
  for insert to authenticated
  with check (
    author_phone = (auth.jwt() ->> 'phone')
    and not public.is_silenced(author_phone)
    and not public.is_area_banned(author_phone, 'forum')
  );

drop policy if exists public_forum_comments_insert_own on public.public_forum_comments;
create policy public_forum_comments_insert_own on public.public_forum_comments
  for insert to authenticated
  with check (
    author_phone = (auth.jwt() ->> 'phone')
    and not public.is_silenced(author_phone)
    and not public.is_area_banned(author_phone, 'forum')
  );

drop policy if exists community_notes_insert_own on public.community_notes;
create policy community_notes_insert_own on public.community_notes
  for insert to authenticated
  with check (
    author_phone = (auth.jwt() ->> 'phone')
    and not public.is_silenced(author_phone)
    and not public.is_area_banned(author_phone, 'feed')
  );

drop policy if exists server_directory_insert_own on public.server_directory;
create policy server_directory_insert_own on public.server_directory
  for insert to authenticated
  with check (
    owner_phone = (auth.jwt() ->> 'phone')
    and not public.is_silenced(owner_phone)
    and not public.is_area_banned(owner_phone, 'servers')
  );

-- ---------------------------------------------------------------------------
-- What a barred account is allowed to know about itself
-- ---------------------------------------------------------------------------
-- Its own area bans, so the app can say "you can't sell here" with a reason.
-- Deliberately NOT its shadow ban: an endpoint that answers "am I shadow
-- banned?" is a shadow ban that does not work.
create or replace function public.my_area_bans()
returns table (area text, reason text, until timestamptz)
language sql
stable
security definer
set search_path = public
as $$
  select b.area, b.reason, b.until
    from public.account_area_bans b
   where b.phone = (auth.jwt() ->> 'phone')
     and (b.until is null or b.until > now());
$$;

grant execute on function public.my_area_bans() to authenticated;


-- ####################################################################
-- ## docs/promoted_posts.sql
-- ####################################################################
-- Promoted posts (2026-08-18): a user pays to have one of their own public
-- posts carried further up the timeline, labelled as an ad.
--
-- The owner's ask was "a custom ad system... so I can allow users to pay to
-- advertise their post". This is that: the app's OWN ad inventory, sold to
-- its own users, separate from the AdMob banners that already run on the two
-- public surfaces.
--
-- WHY THE CLIENT CANNOT PROMOTE ITSELF. There are no client writes on
-- `post_promotions` at all. The row is written ONLY by the `promote-post`
-- Edge Function, which verifies the App Store receipt (JWS) first and dedupes
-- the transaction — the same trust model as creator subscriptions and the
-- storage subscription. A modified client can change what it DRAWS; it cannot
-- buy itself reach.
--
-- WHY IT IS READ THROUGH A VIEW WITH NO PHONE. A promotion names the account
-- that paid for it, and the phone-hiding rule every public table here follows
-- applies: the table-wide select is revoked, every column but `promoter_phone`
-- is granted back, and clients read `promoted_posts_view`. A buyer of ad space
-- is not thereby publishing their phone number.
--
-- WHY A SANCTIONED ACCOUNT'S PROMOTION DISAPPEARS. `content_visible` is the
-- same gate the public feed itself uses, so a shadow-banned promoter's paid
-- placement is visible to them and nobody else — a ban that money could buy
-- its way past would not be a ban.
--
-- Idempotent: safe to run more than once. Apply AFTER
-- docs/moderation_scopes.sql — the read policy calls `content_visible`, and a
-- policy body is parsed at creation, so applying this first fails with
-- "function content_visible(text) does not exist" rather than quietly
-- deferring. (`check_sql.sh` caught exactly that; it is the same class as the
-- functions-above-their-tables bug this repo has hit before.)

-- ---------------------------------------------------------------------------
-- 1. The promotions table.
-- ---------------------------------------------------------------------------
create table if not exists public.post_promotions (
  post_id        text primary key,
  promoter_phone text not null,
  -- When the placement stops. Extended, never duplicated: buying again while
  -- one is running stacks onto whatever is left, the same as every 30-day
  -- pass in this app.
  until          timestamptz not null,
  -- What has been spent on this placement, for the promoter's own screen.
  -- Never used to rank: paying more buys more DAYS, not a better slot, so
  -- there is no auction to game and no reason to read this at serve time.
  spent_cents    int not null default 0,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);

alter table public.post_promotions enable row level security;

-- The default grants Supabase gives a NEW table reach `anon` explicitly, and
-- revoking the PUBLIC pseudo-role does not take them away — the lesson from
-- find_people_by_hashes. Name the roles.
revoke all on table public.post_promotions from anon, authenticated;
grant select (post_id, until, spent_cents, created_at, updated_at)
  on public.post_promotions to anon, authenticated;

-- Readable by everyone, because everyone has to agree on which post is an ad
-- — a promotion nobody but the buyer could see would be a placement that
-- never ran. Sanctioned promoters are filtered here rather than in the view,
-- so a direct column-select cannot see round it.
drop policy if exists post_promotions_read on public.post_promotions;
create policy post_promotions_read on public.post_promotions
  for select to anon, authenticated
  using (content_visible(promoter_phone));

-- No insert/update/delete policy of ANY kind: the Edge Function runs as the
-- table owner and is the only writer. This is not an omission.

create index if not exists post_promotions_until_idx
  on public.post_promotions (until desc);

-- ---------------------------------------------------------------------------
-- 2. Receipt dedupe — one App Store transaction buys one placement.
-- ---------------------------------------------------------------------------
create table if not exists public.promote_receipts (
  txn_id     text primary key,
  created_at timestamptz not null default now()
);
alter table public.promote_receipts enable row level security;
revoke all on table public.promote_receipts from anon, authenticated;

-- ---------------------------------------------------------------------------
-- 3. The phone-free view every client reads.
-- ---------------------------------------------------------------------------
-- security_invoker so the read policy above actually applies — the one thing
-- `public_forum_comments_v` was missing, which silently bypassed ban-hiding
-- until Supabase's own advisor caught it.
create or replace view public.promoted_posts_view
with (security_invoker = on) as
select
  p.post_id,
  p.until,
  p.created_at
from public.post_promotions p
where p.until > now();

grant select on public.promoted_posts_view to anon, authenticated;


-- ####################################################################
-- ## docs/directory_phone_privacy.sql
-- ####################################################################
-- The directory stops handing out phone numbers in bulk.
-- ============================================================================
-- Run ONCE in the Supabase SQL editor, AFTER docs/directory_numberless.sql
-- (it replaces that file's find_people) and docs/directory_privacy.sql
-- (find_by_username / find_by_phone).
--
-- WHAT WAS WRONG. Two doors, and the second was the wide one:
--
--   1. find_people(q) is granted to ANON and returned `phone` as its first
--      column. A two-character prefix answered up to 25 rows, so roughly
--      1,300 queries with nothing but the publishable key — which ships in
--      the web build and is readable by anyone — walked most of the handle
--      space and collected real E.164 numbers on the way.
--   2. usernames_read was `for select to authenticated using (... or not
--      is_locked_out(phone))`. Any account that could sign up could then
--      select the WHOLE table, phone column included, unbounded. Fixing (1)
--      alone would have been theatre.
--
-- Everywhere else in this schema the pattern is already right — market_listings,
-- public_forum and server_directory all revoke the table-wide select and hand
-- back every column but the poster's phone. The directory was the exception,
-- and it is the one table where the phone IS every row's primary key.
--
-- WHAT THIS DOES.
--   * find_people(q) still answers anon (a numberless account has no session
--     and the handle is the only thing it can be found by) but returns a
--     phone ONLY when q is the EXACT handle. A prefix search — the thing that
--     scales — now returns names and handles and nothing to dial.
--   * usernames_read narrows to the caller's OWN row. Everything the app used
--     to read across other people's rows moves to a definer function below,
--     each one answering a single question rather than handing over the table.
--
-- WHAT THIS DOES NOT DO, stated rather than implied. Exact-handle resolution
-- is still unmetered: enumerate handles with find_people, then ask once per
-- handle, and the numbers come out one at a time. That is far slower and far
-- more attributable than 25-at-a-time, but it is a cost increase, not a wall.
-- A wall needs per-caller rate limiting, and a SECURITY DEFINER function
-- cannot see the caller's IP — that belongs in an Edge Function, and it is
-- the follow-up. Sign-in by username is why the anon door cannot simply be
-- shut: the caller is signed out by definition and needs the number to send
-- itself a code.

-- ---------------------------------------------------------------------------
-- 1. Search: handles and names for anyone, a number only for an exact match.
--
-- This is the THIRD definition of find_people: directory_numberless.sql
-- installs it, account_lifecycle.sql replaces it to add the `hidden` filter
-- (a deactivated account answers no search), and this one replaces that. Both
-- earlier filters have to be carried forward or running this file quietly
-- reactivates everybody who deactivated — which is exactly what check_sql.sh
-- caught the first time this was written. Whatever redefines it next: copy
-- every `and` below, not just the ones your own change is about.
drop function if exists public.find_people(text);

create function public.find_people(q text)
returns table (phone text, username text, name text, verified boolean)
language plpgsql security definer set search_path = public as $$
begin
  -- Handle-shaped queries only; anything else could smuggle LIKE wildcards.
  if q is null or q !~ '^[a-z0-9_.]{2,32}$' then
    return;
  end if;
  return query
    select
      -- The whole fix. A prefix match is a browsing result and gets no
      -- number; only somebody who typed the handle exactly — which is what
      -- signing in and opening a chat both do — is answered with one.
      case when lower(u.username) = q then u.phone else '' end,
      u.username,
      u.name,
      coalesce(u.verified, false)
    from public.usernames u
    -- '_' is a legal handle character but a LIKE wildcard; escape it so
    -- searching a_b does not match axb.
    where lower(u.username) like replace(q, '_', '\_') || '%'
      and coalesce(u.find_by_username, true)
      -- From account_lifecycle.sql: a deactivated row answers no search.
      and not coalesce(u.hidden, false)
      and not public.is_locked_out(u.phone)
    order by u.username
    limit 25;
end $$;

revoke all on function public.find_people(text) from public;
grant execute on function public.find_people(text) to anon, authenticated;

-- ---------------------------------------------------------------------------
-- 2. The table itself: your own row, and nobody else's.
drop policy if exists usernames_read on public.usernames;
create policy usernames_read on public.usernames
  for select to authenticated
  using (phone = (auth.jwt() ->> 'phone'));

-- ---------------------------------------------------------------------------
-- 3. The questions the app used to answer by reading other people's rows.
--    Each returns one fact rather than a row, and none of them returns a
--    phone the caller did not already supply.

-- Is this handle free? Answers 'available' | 'mine' | 'taken' — never who
-- holds it. Anon may ask: a handle is chosen during sign-up, before a session.
create or replace function public.username_status(uname text)
returns text
language plpgsql stable security definer set search_path = public as $$
declare
  me text := coalesce(auth.jwt() ->> 'phone', '');
  owner text;
begin
  if uname is null or uname !~ '^[a-z0-9_.]{2,32}$' then
    return 'invalid';
  end if;
  select u.phone into owner from public.usernames u
   where lower(u.username) = lower(uname) limit 1;
  if owner is null then return 'available'; end if;
  if me <> '' and owner = me then return 'mine'; end if;
  return 'taken';
end $$;

revoke all on function public.username_status(text) from public;
grant execute on function public.username_status(text) to anon, authenticated;

-- Contact sync. The caller hashed numbers out of its own address book, so it
-- already holds every number this can return — the hash IS the proof of that,
-- which is why this one may answer with phones. Capped so the array cannot be
-- turned into a brute-force oracle in one call.
create or replace function public.find_people_by_hashes(hashes text[])
returns table (phone text, username text, name text, verified boolean)
language plpgsql stable security definer set search_path = public as $$
begin
  if hashes is null or array_length(hashes, 1) is null
     or array_length(hashes, 1) > 500 then
    return;
  end if;
  return query
    select u.phone, u.username, u.name, coalesce(u.verified, false)
    from public.usernames u
    where u.phone_hash = any(hashes)
      and coalesce(u.find_by_phone, true)
      and not public.is_locked_out(u.phone)
    limit 500;
end $$;

-- `revoke ... from public` is NOT enough on a Supabase project: the default
-- privileges on schema public grant EXECUTE on every new function to anon and
-- authenticated outright, and revoking the PUBLIC pseudo-role leaves those
-- explicit grants standing. Verified live — this function came out
-- anon-callable on the first apply, which would have handed a signed-out
-- caller a 500-at-a-time oracle turning guessed phone hashes into real
-- numbers and names. Name the role to actually take it away.
revoke all on function public.find_people_by_hashes(text[]) from public;
revoke all on function public.find_people_by_hashes(text[]) from anon;
grant execute on function public.find_people_by_hashes(text[]) to authenticated;

-- Does this number have an account? The caller supplied the number, so a
-- yes/no adds nothing it could not learn by trying to message them.
create or replace function public.is_on_app(p text)
returns boolean
language sql stable security definer set search_path = public as $$
  select exists(
    select 1 from public.usernames u
     where u.phone = coalesce(p, '') and coalesce(p, '') <> ''
  );
$$;

revoke all on function public.is_on_app(text) from public;
grant execute on function public.is_on_app(text) to anon, authenticated;

-- The handle on a number the caller already has. Used at sign-in, before
-- there is a session to read your own row with.
create or replace function public.username_for_phone(p text)
returns text
language sql stable security definer set search_path = public as $$
  select u.username from public.usernames u
   where u.phone = coalesce(p, '') and coalesce(p, '') <> ''
   limit 1;
$$;

revoke all on function public.username_for_phone(text) from public;
grant execute on function public.username_for_phone(text) to anon, authenticated;


-- ####################################################################
-- ## docs/public_profiles.sql
-- ####################################################################
-- Public-by-default profiles (2026-08-23), continuing the owner's direction:
-- "move away from privacy and storing things local and be more social media".
--
-- WHAT WAS WRONG. Browsing people barely worked. The directory carried a
-- handle, a display name and a verified flag and NOTHING else — no avatar, no
-- bio, no location — so a stranger in search results, or on a profile you
-- opened from a public post, drew as coloured initials with an @handle under
-- them. `knownUserFor` could only ever answer for yourself or somebody you
-- had already chatted with, which is exactly the person you are NOT looking
-- at when you are trying to find somebody new.
--
-- WHAT THIS PUBLISHES, and it is a real disclosure rather than a schema
-- tidy-up: the avatar bundle, the bio, the location and the business chip
-- become world-readable for anyone holding the publishable key. That is the
-- deliberate trade — it is what makes a social app's people search work at
-- all — and the app says so on the screen where somebody edits them.
--
-- WHAT IT DOES NOT PUBLISH, and this is load-bearing:
--
-- * THE PHONE NUMBER. docs/directory_phone_privacy.sql (2026-08-10) closed a
--   real hole where a two-character prefix answered 25 rows carrying real
--   E.164 numbers, so ~1,300 anon queries walked the handle space collecting
--   them. Every rule from that file is preserved below, verbatim in effect:
--   a PREFIX match is a browsing result and gets no number, only an EXACT
--   handle is answered with one (sign-in by username needs it, signed out).
--   Nothing here widens that by a character.
-- * pronouns and links, which were removed from the profile UI entirely on
--   2026-08-17 at the owner's call. Publishing a field the app no longer
--   lets anybody edit would be publishing stale data nobody can correct.
--
-- FIND_PEOPLE IS NOW DEFINED FOUR TIMES across the migrations —
-- directory_numberless.sql, then account_lifecycle.sql (adds the `hidden`
-- filter), then directory_phone_privacy.sql (the phone rule), then here.
-- CLAUDE.md's own warning applies and is the reason this file is written the
-- way it is: replacing it without copying every earlier condition quietly
-- reactivates everybody who deactivated, or hands out numbers again. All
-- four conditions are carried below and check_sql.sh asserts each of them
-- STILL holds after this file is applied, not merely that the new columns
-- arrived.

alter table public.usernames add column if not exists avatar_color text not null default '';
alter table public.usernames add column if not exists avatar_color2 text not null default '';
alter table public.usernames add column if not exists emoji text not null default '';
alter table public.usernames add column if not exists avatar_seed text not null default '';
alter table public.usernames add column if not exists avatar_face text not null default '';
alter table public.usernames add column if not exists avatar_gif text not null default '';
alter table public.usernames add column if not exists about text not null default '';
alter table public.usernames add column if not exists location text not null default '';
alter table public.usernames add column if not exists is_business boolean not null default false;
alter table public.usernames add column if not exists business_category text not null default '';

-- The search. Every condition from all three earlier definitions is here:
-- the handle shape guard, find_by_username, hidden (account_lifecycle), the
-- lock-out check, and the exact-handle-only phone rule.
-- The return type gains columns, and `create or replace` cannot change one —
-- it fails outright with "cannot change return type of existing function".
-- The same wall `public_follow` hit when it started returning a boolean, and
-- the reason that one is dropped first too. Caught by check_sql.sh's
-- re-apply pass, which is exactly what that second loop is for.
--
-- A drop hands the new function FRESH default privileges, so the grants
-- below are not decoration: on a Supabase project the defaults would give
-- anon EXECUTE anyway, but relying on that is how the opposite mistake
-- (find_people_by_hashes coming out anon-callable) happened. State it.
drop function if exists public.find_people(text);
create function public.find_people(q text)
returns table (
  phone text, username text, name text, verified boolean,
  avatar_color text, avatar_color2 text, emoji text, avatar_seed text,
  avatar_face text, avatar_gif text, about text, location text,
  is_business boolean, business_category text)
language plpgsql security definer set search_path = public as $$
begin
  -- Handle-shaped queries only; anything else could smuggle LIKE wildcards.
  if q is null or q !~ '^[a-z0-9_.]{2,32}$' then
    return;
  end if;
  return query
    select
      -- UNCHANGED from directory_phone_privacy.sql, and the reason this
      -- function is rewritten by hand rather than patched: a prefix match is
      -- a browsing result and gets no number; only somebody who typed the
      -- handle exactly — which is what signing in and opening a chat both do
      -- — is answered with one.
      case when lower(u.username) = q then u.phone else '' end,
      u.username,
      u.name,
      coalesce(u.verified, false),
      coalesce(u.avatar_color, ''),
      coalesce(u.avatar_color2, ''),
      coalesce(u.emoji, ''),
      coalesce(u.avatar_seed, ''),
      coalesce(u.avatar_face, ''),
      coalesce(u.avatar_gif, ''),
      coalesce(u.about, ''),
      coalesce(u.location, ''),
      coalesce(u.is_business, false),
      coalesce(u.business_category, '')
    from public.usernames u
    -- '_' is a legal handle character but a LIKE wildcard; escape it so
    -- searching a_b does not match axb.
    where lower(u.username) like replace(q, '_', '\_') || '%'
      and coalesce(u.find_by_username, true)
      -- From account_lifecycle.sql: a deactivated row answers no search.
      and not coalesce(u.hidden, false)
      and not public.is_locked_out(u.phone)
    order by u.username
    limit 25;
end $$;

revoke all on function public.find_people(text) from public;
grant execute on function public.find_people(text) to anon, authenticated;

-- One person's profile, by exact handle — what opening a stranger's profile
-- asks for. Deliberately returns NO phone at all, not even on an exact
-- match: find_people already answers that question for the one caller that
-- needs it (sign-in, and opening a chat), and a second door handing out
-- numbers is how the 2026-08-10 hole would grow back.
create or replace function public.public_profile(uname text)
returns table (
  username text, name text, verified boolean,
  avatar_color text, avatar_color2 text, emoji text, avatar_seed text,
  avatar_face text, avatar_gif text, about text, location text,
  is_business boolean, business_category text)
language plpgsql stable security definer set search_path = public as $$
declare q text := lower(coalesce(uname, ''));
begin
  if q !~ '^[a-z0-9_.]{2,32}$' then
    return;
  end if;
  return query
    select
      u.username, u.name, coalesce(u.verified, false),
      coalesce(u.avatar_color, ''), coalesce(u.avatar_color2, ''),
      coalesce(u.emoji, ''), coalesce(u.avatar_seed, ''),
      coalesce(u.avatar_face, ''), coalesce(u.avatar_gif, ''),
      coalesce(u.about, ''), coalesce(u.location, ''),
      coalesce(u.is_business, false), coalesce(u.business_category, '')
    from public.usernames u
    where lower(u.username) = q
      and coalesce(u.find_by_username, true)
      and not coalesce(u.hidden, false)
      and not public.is_locked_out(u.phone)
    limit 1;
end $$;

revoke all on function public.public_profile(text) from public;
grant execute on function public.public_profile(text) to anon, authenticated;

-- The write side needs nothing new. usernames_read still scopes SELECT on the
-- table to the caller's OWN row, and the existing insert/update policies
-- already let an account write that row — so publishing a profile is the app
-- upserting its own row with more columns in it, checked by the same RLS that
-- has always governed it. A client cannot write anybody else's profile.


-- ####################################################################
-- ## docs/chat_backup_bucket.sql
-- ####################################################################
-- Storage bucket for encrypted chat backups.
-- ============================================================================
-- Run this ONCE in the Supabase dashboard (SQL Editor → New query → Run),
-- after docs/supabase_setup.sql.
--
-- WHY A BUCKET, NOT A TABLE. Chat backups are the only large, paid thing the
-- server holds. Storage buckets bill at ~$0.0213/GB where Postgres disk bills
-- at $0.125/GB — roughly 6× cheaper. Selling storage is only profitable at the
-- bucket rate, so backups live here and the small (free) communal sync blob
-- stays in the `sync_blobs` table.
--
-- WHAT'S IN IT. One object per account, named with the 256-bit HMAC of that
-- account's encryption key. The bytes are AES-256-GCM ciphertext the server
-- cannot read, exactly as before — moving backends changed the bill, not the
-- privacy model.

-- Private bucket: objects are never served over a public URL. A 50 MB per-file
-- ceiling is far above a text-only chat backup and stops a single object from
-- running away.
insert into storage.buckets (id, name, public, file_size_limit)
values ('chat-backups', 'chat-backups', false, 52428800)
on conflict (id) do update
  set public = false,
      file_size_limit = 52428800;

-- Access model, matching `sync_blobs`: the object name is an unguessable HMAC
-- of a key only the user holds, so possession of the name IS the capability to
-- read/write that object — and the contents are end-to-end encrypted anyway.
-- (With no server-side auth in this project, RLS cannot bind an object to a
-- verified caller; the name's entropy is what protects it.)
drop policy if exists chat_backups_read on storage.objects;
create policy chat_backups_read on storage.objects
  for select to anon, authenticated
  using (bucket_id = 'chat-backups');

drop policy if exists chat_backups_insert on storage.objects;
create policy chat_backups_insert on storage.objects
  for insert to anon, authenticated
  with check (bucket_id = 'chat-backups');

drop policy if exists chat_backups_update on storage.objects;
create policy chat_backups_update on storage.objects
  for update to anon, authenticated
  using (bucket_id = 'chat-backups');

-- Without delete, a user could overwrite their backup but never remove it.
drop policy if exists chat_backups_delete on storage.objects;
create policy chat_backups_delete on storage.objects
  for delete to anon, authenticated
  using (bucket_id = 'chat-backups');

-- ----------------------------------------------------------------------------
-- Optional: usage accounting against the bucket
-- ----------------------------------------------------------------------------
-- If you ran docs/storage_usage_setup.sql, this view reports what the bucket
-- actually holds — the number your Supabase bill is computed from.
--
-- security_invoker, and granted to NOBODY. A view without it runs with its
-- owner's privileges, which is what Supabase's advisor flags as CRITICAL: it
-- reads storage.objects past the caller's RLS, so any signed-in client could
-- count and size every backup in the bucket. This is an operator's number,
-- read in the SQL editor by whoever owns the project.
create or replace view public.chat_backup_totals
with (security_invoker = on) as
  select
    count(*)                                          as backups,
    coalesce(sum((metadata->>'size')::bigint), 0)     as total_bytes,
    round(coalesce(sum((metadata->>'size')::bigint), 0)
          / 1073741824.0, 3)                          as total_gb
  from storage.objects
  where bucket_id = 'chat-backups';

revoke all on public.chat_backup_totals from anon, authenticated;


-- ####################################################################
-- ## docs/market_media_bucket.sql
-- ####################################################################
-- Storage bucket for sealed marketplace listing videos.
-- ============================================================================
-- Run this ONCE in the Supabase dashboard (SQL Editor → New query → Run).
--
-- WHY A BUCKET. A video cannot ride the message relay: one broadcast caps out
-- around a quarter megabyte and even a short clip is tens of that, each chunk
-- a mailbox row per offline member, one lost chunk a broken video. Videos are
-- also the first marketplace media that costs real money to host, which is
-- why uploading them requires the cloud storage subscription in the app.
--
-- WHAT'S IN IT. One object per listing, at <serverId>/<listingId>.sealed.
-- The bytes are AES-256-GCM ciphertext sealed with the server's shared key —
-- the same key that seals the server's relay traffic — so only members of
-- that server (the listing's entire audience) can play the video. The bucket
-- operator sees ciphertext. Plaintext media must never be stored here.

-- Private bucket; 24 MB per object comfortably covers a sealed 12 MB video
-- (base64 + encryption inflate ~4/3) and stops runaways.
insert into storage.buckets (id, name, public, file_size_limit)
values ('market-media', 'market-media', false, 25165824)
on conflict (id) do update
  set public = false,
      file_size_limit = 25165824;

-- Access model, matching the relay itself: the object path contains the
-- server id, which is only known to members (it arrives inside the E2E
-- encrypted invite), and the contents are sealed with the server key anyway.
-- With REQUIRE_OTP off there is no verified caller for RLS to bind to; the
-- seal is the real protection, exactly as it is for relay traffic.
drop policy if exists market_media_read on storage.objects;
create policy market_media_read on storage.objects
  for select to anon, authenticated
  using (bucket_id = 'market-media');

drop policy if exists market_media_insert on storage.objects;
create policy market_media_insert on storage.objects
  for insert to anon, authenticated
  with check (bucket_id = 'market-media');

drop policy if exists market_media_update on storage.objects;
create policy market_media_update on storage.objects
  for update to anon, authenticated
  using (bucket_id = 'market-media');

-- Sellers remove their video when the listing goes.
drop policy if exists market_media_delete on storage.objects;
create policy market_media_delete on storage.objects
  for delete to anon, authenticated
  using (bucket_id = 'market-media');


-- ####################################################################
-- ## docs/voice_notes_bucket.sql
-- ####################################################################
-- Storage bucket for sealed voice notes longer than the relay envelope.
-- ============================================================================
-- Run this ONCE in the Supabase dashboard (SQL Editor → New query → Run).
--
-- WHY A BUCKET. A short voice note rides the message relay inline, sealed like
-- a photo. A long one cannot: one broadcast caps out around a quarter megabyte
-- and a few minutes of audio is several of that, each chunk a mailbox row per
-- offline recipient, one lost chunk a broken note. So a long note goes here
-- instead — the same bucket machinery marketplace videos and chat backups use.
--
-- WHAT'S IN IT. One object per note, at a random name ending .sealed. The
-- bytes are AES-256-GCM ciphertext sealed with a PER-NOTE random key that
-- never touches this bucket: it travels inside the E2E-encrypted chat message
-- that names the object, so only that conversation's devices can unseal it.
-- The bucket operator sees ciphertext, and even the object path leaks nothing
-- without the key. Plaintext audio must never be stored here.

-- Private bucket; 24 MB per object comfortably covers a sealed 12 MB note
-- (base64 + encryption inflate ~4/3) and stops runaways.
insert into storage.buckets (id, name, public, file_size_limit)
values ('voice-notes', 'voice-notes', false, 25165824)
on conflict (id) do update
  set public = false,
      file_size_limit = 25165824;

-- Access model, matching the relay: with REQUIRE_OTP off there is no verified
-- caller for RLS to bind to, so the seal is the real protection — exactly as
-- it is for relay traffic. The per-note key lives only in the sealed message.
drop policy if exists voice_notes_read on storage.objects;
create policy voice_notes_read on storage.objects
  for select to anon, authenticated
  using (bucket_id = 'voice-notes');

drop policy if exists voice_notes_insert on storage.objects;
create policy voice_notes_insert on storage.objects
  for insert to anon, authenticated
  with check (bucket_id = 'voice-notes');

drop policy if exists voice_notes_update on storage.objects;
create policy voice_notes_update on storage.objects
  for update to anon, authenticated
  using (bucket_id = 'voice-notes');

drop policy if exists voice_notes_delete on storage.objects;
create policy voice_notes_delete on storage.objects
  for delete to anon, authenticated
  using (bucket_id = 'voice-notes');

